window.JASTROW_CHUNKS[42]={"16800":{"h":"מְשֹׁוחָאָה","r":"M02824","html":"<div class=\"sense\"> <span class=\"citation\">B. Mets. 107ᵇ</span></div>","alt":[]},"16801":{"h":"מָשֹׁוט","r":"M02825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>oar.</i> <span class=\"citation\">Zab. IV, 3</span>.—Pl. <span dir=\"rtl\">מְשֹׁוטִין</span>. <span class=\"citation\">B. Bath. 73ᵃ</span> ed. (Mss. <span dir=\"rtl\">מְשֹׁוטוֹת</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"16802":{"h":"מָשֹׁוט ²","r":"M02826","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מָשֹׁוט\">same</a>. <span class=\"citation\">Targ. Ez. XXVII, 29</span>.—Pl. <span dir=\"rtl\">מְשֹׁוטִין</span>. <span class=\"citation\">Ib. 6</span>.</div><div class=\"sense\"><b>—2)</b> <i>light ship</i>.—Pl. as ab. <span class=\"citation\">Targ. Is. XLIII, 14</span> (h. text <a href=\"#\" data-headword=\"רֵיחַיִים\">רִיחִים</a>!).</div>","alt":["מְשֹׁוטָא"]},"16803":{"h":"מַשֹּׂוי","r":"M02827","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשּׂוֹא\">מַשֹּׂוא</a></div>","alt":[]},"16804":{"h":"מָשׁוּךְ","r":"M02828","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁךְ I\">מָשַׁךְ</a>) <i>one who has his prepuce drawn forward</i> in order to disguise the sign of the covenant. <span class=\"citation\">Tosef. Sabb. XV</span> (<span class=\"citation\">XVI), 9</span>; <span class=\"citation\">Y. Yeb. VIII, 9ᵃ</span> top <span dir=\"rtl\">המושך</span> (corr. acc.). Bab. <span class=\"citation\">ib. 72ᵇ</span> <span dir=\"rtl\">מ׳ דאורייתא</span> that a <i>mashukh</i> must be circumcised again is a Biblical injunction; a. fr.—Pl. <span dir=\"rtl\">מְשׁוּכִין</span>. Y. Yeb. l. c.</div>","alt":[]},"16805":{"h":"מְשׂוּכָּה","r":"M02829","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>hedge, a hedged-in place, fold</i>.—Pl. <span dir=\"rtl\">מְשׂוּכֹּות</span>. <span class=\"citation\">Tosef. Ohol. XVIII, 12</span> (ed. Zuck., a. R. S. to Ohol. XVIII, 10 <a href=\"#\" data-headword=\"משיכות\">משיכות</a>; ed. Zolk. <a href=\"#\" data-headword=\"*מְשׁוּנִּית\">משונית</a>).</div>","alt":[]},"16806":{"h":"מְשׁוּלַּחַת","r":"M02830","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁלַח\">שָׁלַח</a>) <i>a divorced wife taken back after being married to another man</i> (against the law, <span class=\"citation\">Deut. XXIV, 4</span>). <span class=\"citation\">Nidd. 69ᵇ</span> <span dir=\"rtl\">בת מ׳</span> the daughter of a woman illegitimately remarried.</div>","alt":[]},"16807":{"h":"מְשׁוּלָּשׁ","r":"M02831","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> ; pl. <span dir=\"rtl\">מְשׁוּלָּשִׁים</span>, <span dir=\"rtl\">מְשׁוּלָּשִׁין</span></div><div class=\"sense\"><b>1)</b> <i>developed to one third of the full growth</i>. <span class=\"citation\">B. Mets. V, 4</span>.</div><div class=\"sense\"><b>—2)</b> <i>group of three</i>. <span class=\"citation\">Y. Shebi. I, 33ᵇ</span> <span dir=\"rtl\">חשבין מ׳</span> the quantity (of one cake of figs) for each three trees out of nine.</div>","alt":[]},"16808":{"h":"מְשׁוּמָּד","r":"M02832","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁמַד\">שָׁמַד</a>) <i>one deserving extinction</i>; (interch. in edd. a. mss. with <a href=\"#\" data-headword=\"מוּמָר\">מוּמָר</a> q. v.) <i>open opponent to Jewish law, apostate</i>. <span class=\"citation\">Y. Snh. X, end, 29ᵈ</span> <span dir=\"rtl\">משום קדשי מ׳</span> it comes under the category of dedicated sacrifices of an apostate (which cannot be offered, but are forbidden for private use). <span class=\"citation\">Y. Pes. VII, 34ᶜ</span> bot. <span dir=\"rtl\">המ׳ בהורייה</span> a heretic inasmuch as he opposes the decisions of the Supreme Court (v. <a href=\"#\" data-headword=\"מַמְרֵא II\"><span dir=\"rtl\">מַמְרֵא</span> II</a>). Y. Hor. III, 48ᵇ bot. <span dir=\"rtl\">גר ומ׳ מ׳ קודם</span> if a proselyte and a (penitent) apostate ask for charity, the apostate has the preference; a. fr.—[<span class=\"citation\">Y. Snh. III, 21ᵇ</span> top <span dir=\"rtl\">חד מ׳</span>, v. <a href=\"#\" data-headword=\"*הָאַסְטוּ\">הָאַסְטוּ</a>.]—Pl. <span dir=\"rtl\">מְשׁוּמָּדִים</span>. <span class=\"citation\">R. Hash. 17ᵃ</span> Ms. M. (missing in ed.). Sifra Vayikra, N’dab., ch. II, Par. 2; a. e.</div>","alt":[]},"16809":{"h":"מְשׁוּמָּדוּת","r":"M02833","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשׁוּמָּד\">preced.</a>) <i>apostasy</i>. <span class=\"citation\">Pes. 96ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">המרת דת</span>), v. <a href=\"#\" data-headword=\"הֲמָרָה\">הֲמָרָה</a>; <span class=\"citation\">Yalk. Ex. 211</span> <span dir=\"rtl\">משמדות פסולות</span> (read: <span dir=\"rtl\">משומ׳ פוסלת</span>).</div>","alt":[]},"16810":{"h":"מְשׁוּמְשָׁנָא","r":"M02834","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַשׁ\">שְׁמַשׁ</a>) <i>servant, attendant</i>. <span class=\"citation\">Targ. Num. XI, 28</span>; a. fr.—Pl. <span dir=\"rtl\">מְשׁוּמְשָׁנִין</span>, <span dir=\"rtl\">מְשֻׁמְּ׳</span>. <span class=\"citation\">Targ. I Kings X, 5</span> <span dir=\"rtl\">מְשׁוּמְשָׁנוֹהִי</span> (ed. Lag. … <a href=\"#\" data-headword=\"*נָיָה\">ניה</a>, corr. acc.).—<span class=\"citation\">Koh. R. to I, 3</span> <span dir=\"rtl\">והוה ר׳ אמר למשומשנוהי</span> and Rabbi asked his waiters; <span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">למְשֻׁמְּשָׁנוֹי</span>.</div>","alt":["מְשֻׁמְּשָׁנָא"]},"16811":{"h":"מְשׁוּמָּת","r":"M02835","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שַׁמְתָּא\">שַׁמְתָּא</a>) (<i>be</i>) <i>excommunicated</i>. <span class=\"citation\">Sabb. 67ᵃ</span> (in an incantation).</div>","alt":[]},"16812":{"h":"*מְשׁוּנִּית","r":"M02836","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"מְשׁוּנִּיתָא\">next w.</a>) <i>grotto</i>. <span class=\"citation\">Tosef. Ohol. XVIII, 12</span>, v. <a href=\"#\" data-headword=\"מְשׂוּכָּה\">מְשׂוּכָּה</a>.</div>","alt":[]},"16813":{"h":"מְשׁוּנִּיתָא","r":"M02837","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שִׁינּ־\">שִׁינָּא</a> <i>tooth</i>) </div><div class=\"sense\"><b>1)</b> <i>jaw</i>. <span class=\"citation\">Erub. 100ᵃ</span> <span dir=\"rtl\">דדמו כמ׳</span> (some ed. … <span dir=\"rtl\">ניתה</span>; Ms. M. <span dir=\"rtl\">כי שִׁינִּיתָא</span>) if the roots on the surface are shaped like a jaw-bone (Rashi: ‘rocky crag’, v. infra).</div><div class=\"sense\"><b>—2)</b> <i>cliff; bluff; grotto</i>. <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">מ׳ דימא וכ׳</span> the bluffs at Caesarea; (<span class=\"citation\">Koh. R. to XI, 1</span> <a href=\"#\" data-headword=\"שׁוּנִּיתָא\">שוניתא</a>; <span class=\"citation\">ib. to V, 8</span> <a href=\"#\" data-headword=\"שׁוּנְּתָא\">שונתא</a>).—<span class=\"citation\">Taan. 23ᵃ</span> <span dir=\"rtl\">אהדרא ליה מ׳</span> a grotto formed around him; <span class=\"citation\">Midr. Till. to Ps. CXXVI</span>. <span class=\"citation\">B. Mets. 108ᵇ</span> <span dir=\"rtl\">אפסיק מ׳</span> if a craggy mound separated the fields. <span class=\"citation\">Ib. 109ᵃ</span> <span dir=\"rtl\">אהדר ליה מ׳</span> he surrounded the fields with an embankment.</div>","alt":[]},"16814":{"h":"מַשּׁוּפִי","r":"M02838","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְשַׁף I\">נְשַׁף</a>) <i>blowing</i>. <span class=\"citation\">Yalk. Ps. 864</span>, v. <a href=\"#\" data-headword=\"מַגְעוּרִי\">מַגְעוּרִי</a>.</div>","alt":[]},"16815":{"h":"מְשׁוּפָּשׁ","r":"M02839","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">מפושפש</span>, v. <a href=\"#\" data-headword=\"פִּשְׁפָּשׁ\">פִּשְׁפָּשׁ</a>; cmp. <span dir=\"rtl\">כֶּסֶךְ כַּסְכַּס</span>. for <a href=\"#\" data-headword=\"סִכְסֵךְ I\">סכסך</a>) <i>small side-door, passage-way</i> (v. <span class=\"citation\">Tam. III, 7</span>). <span class=\"citation\">Zeb. 82ᵇ</span> <span dir=\"rtl\">דרך מ׳</span> (Ms. K. <span dir=\"rtl\">משובש</span>) by the way of small passages in the loft (v. <span class=\"citation\">Midd. IV, 5</span> quot. s. v. <a href=\"#\" data-headword=\"לוּל\">לוּל</a>). <span class=\"citation\">Men. 27ᵇ</span> <span dir=\"rtl\">דרך מ׳</span> by breaking through a side entrance (or walking in a zigzag as on winding stairs); [Rashi: = <span dir=\"rtl\">משובש</span>, v. <a href=\"#\" data-headword=\"שָׁבַשׁ\">שָׁבַשׁ</a>]; <span class=\"citation\">Yalk. Lev. 571</span> <span dir=\"rtl\">משופע</span> (corr. acc.).</div>","alt":[]},"16816":{"h":"מְשׁוּקָּע","r":"M02840","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁקַע\">שָׁקַע</a></div>","alt":[]},"16817":{"h":"מְשׂוּרָה","r":"M02841","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>m’surah</i>, a measure of capacity, one thirty-sixth of a Log. <span class=\"citation\">Ab. ch. VI</span> (adopted fr. <span class=\"citation\">Ez. V, 11</span>). <span class=\"citation\">B. Mets. 61ᵇ</span>; <span class=\"citation\">B. Bath. 89ᵇ</span>.—Sifra K’dosh. Par. 3, ch. VIII במ׳ זו זיר הגדול ‘in measure’ (<span class=\"citation\">Lev. XIX, 35</span>) that means you must leave a large crest (in dry measure), v. <a href=\"#\" data-headword=\"זֵיר\">זֵיר</a>.</div>","alt":[]},"16818":{"h":"מְשֹׁורְיָא","r":"M02842","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שִׁיר I\">שור</a>) <i>journey</i>.—Pl. <span dir=\"rtl\">מְשֹׁורְיָין</span>. <span class=\"citation\">Targ. Y. I Num. XXI, 1</span>.</div>","alt":[]},"16819":{"h":"מְשֹׁורֵר","r":"M02843","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>singer</i>, v. <a href=\"#\" data-headword=\"שִׁיר I\"><span dir=\"rtl\">שִׁיר</span> I</a>.</div>","alt":[]},"16820":{"h":"מָשׁוֹשׁ","r":"M02844","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a> or <a href=\"#\" data-headword=\"מָשַׁשׁ\">מָשַׁשׁ</a>; cmp. <a href=\"#\" data-headword=\"דָּשֹׁושׁ\">דָּשֹׁושׁ</a>) <i>groper, slow walker</i>.—Pl. <span dir=\"rtl\">מָשֹׁושׁוֹת</span>. Y. Peah VIII, beg. 20ᵈ, v. <a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a> h.</div>","alt":[]},"16821":{"h":"מְשֵׁזֵב","r":"M02845","html":"<div class=\"sense\">, etc., v. sub. <span dir=\"rtl\">מְשֵׁיז׳</span>.</div>","alt":["מְשֵׁזְבָא"]},"16822":{"h":"מָשַׁח I","r":"M02846","html":"<div class=\"sense\"> (b. h.) <i>to stroke, smear;</i> esp. <i>to anoint; to install in office by anointing</i>. <span class=\"citation\">Ker. 5ᵇ</span> <span dir=\"rtl\">מושְׁחִין את המלכים כמין נזר וכ׳</span> in anointing kings you draw the figure of a crown with the oil on your finger &amp;c., v. <a href=\"#\" data-headword=\"כי\">כי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין מושחין מלך וכ׳</span> a king succeeding his father is not anointed; a. v. fr.—Part. pass. <a href=\"#\" data-headword=\"מָשׁוּחַ\">מָשׁוּחַ</a>, pl. <span dir=\"rtl\">מְשׁוּחִים</span>, <span dir=\"rtl\">מְשׁוּחִין</span>. <span dir=\"rtl\">כהן מ׳</span> a high priest installed with the ceremony of anointing, contrad. to <span dir=\"rtl\">מרובה בגדים</span>, v. <a href=\"#\" data-headword=\"מְרוּבֶּה\">מְרוּבֶּה</a>. <span class=\"citation\">Hor. III, 4</span>; <span class=\"citation\">Meg. I, 9</span> <span dir=\"rtl\">אין כין כהן מ׳ בשמן וכ׳</span> there is no difference between the anointed and the unanointed high priest except &amp;c. Sifré Tsav, Par. 3, ch. V; a. fr., v. <a href=\"#\" data-headword=\"מָשִׁיחַ\">מָשִׁיחַ</a>.—<span dir=\"rtl\">מְשׁוּחַ מלחמה</span> the priest anointed as the chaplain of the army. <span class=\"citation\">Yoma 72ᵇ</span>; a. fr., v. <a href=\"#\" data-headword=\"מָשִׁיחַ\">מָשִׁיחַ</a>.—<span class=\"citation\">Pesik. R. s. 8</span> <span dir=\"rtl\">מ׳ מלחמה</span>, v. <a href=\"#\" data-headword=\"מָשִׁיחַ\">מָשִׁיחַ</a> end. <span class=\"citation\">Hor. 12ᵃ</span>, v. <a href=\"#\" data-headword=\"יָמַן\">יָמַן</a>. <span class=\"citation\">Ib. 11ᵇ</span> <span dir=\"rtl\">מלכי בית דוד מ׳ וכ׳</span> the kings of the house of David are anointed kings, those of Israel are not installed by anointment; a. fr.</div><div class=\"sense\"><b>Nif. נִמְשַׁח</b> <div class=\"sense\"><i>to be anointed</i>. Ib. <span dir=\"rtl\">יהוא לא נ׳ וכ׳</span> Jehu would not have been anointed but for the contest of Joram’s followers. Ib. <span dir=\"rtl\">וממנו היה נִמְשָׁח המשכן וכ׳</span> with that oil (prepared by Moses) were anointed the Tabernacle &amp;c.; Y. Sot. VIII, 22ᶜ. <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">עד שנִמְשְׁחוּ כולם</span> until all the vessels were anointed; a. fr.</div></div>","alt":[]},"16823":{"h":"מְשַׁח","r":"M02847","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XXXI, 13</span>. <span class=\"citation\">Targ. Ps. LXIV, 4</span> (Ms. <span dir=\"rtl\">מתח</span>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מָשִׁיחַ\">מְשִׁיחַ</a>. <span class=\"citation\">Targ. II Sam. I, 21</span>; a. e.—<span class=\"citation\">Ker. 5ᵇ</span> <span dir=\"rtl\">ההוא דמשיח וכ׳</span> (not <span dir=\"rtl\">דמשח</span>) that son of the high priest that was anointed was high priest &amp;c.; <span class=\"citation\">Hor. 11ᵇ</span> <span dir=\"rtl\">אי הוה משיח וכ׳</span>.</div><div class=\"sense\"><b>Ithpe. אִיתְמְשַׁח</b> <div class=\"sense\"><i>to be rubbed with oil, perfumed</i>. <span class=\"citation\">Targ. Am. VI, 6</span>.</div></div>","alt":[]},"16824":{"h":"מָשַׁח II","r":"M02848","html":"<div class=\"sense\"><i>to stretch, measure</i>. Denom. <a href=\"#\" data-headword=\"מָשׁוֹחַ\">מָשׁוֹחַ</a>, <a href=\"#\" data-headword=\"מְשִׁיחָה I\">מְשִׁיחָה</a>.</div><div class=\"sense\"><b>Hif. הִמְשִׁיחַ</b> <div class=\"sense\"><i>to draw the outlines</i>. <span class=\"citation\">Yalk. Num. 719</span> <span dir=\"rtl\">עומד ומַמְשִׁיחַ בה</span> stood there drawing (the pattern of the candlestick).</div></div>","alt":[]},"16825":{"h":"מְשַׁח ²","r":"M02849","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. X, 25</span>. <span class=\"citation\">Targ. Ez. XL, 5</span>; a. fr.—<span class=\"citation\">Sabb. 19ᵃ</span> נִימְשַׁח וניתיב ליה נימשח ונשקול מיניה Ms. M. (ed., v. <span dir=\"rtl\">מִשְׁחָא II</span>) let him measure when giving it out and again when receiving it back. <span class=\"citation\">B. Mets. 107ᵇ</span> לא תִימְשְׁחִינְהוּ כלל Ms. M. (ed. <span dir=\"rtl\">תימשחנו</span>) do not measure (survey) at all.</div>","alt":[]},"16826":{"h":"מְשַׁח III","r":"M02850","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מְשַׁח I) </div><div class=\"sense\"><b>1)</b> <i>oil, fat</i>. <span class=\"citation\">Targ. Num. VII, 13</span>. <span class=\"citation\">Targ. Ex. XXIX, 7</span>; a. fr.—Y. Maas. Sh. IV, 54ᵈ bot. <span dir=\"rtl\">הוה ליה משח וכ׳</span> had oil which he took down to Acco (for sale). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ההוא מִישְׁחָךְ וכ׳</span> (not <span dir=\"rtl\">מישחף</span>, some ed. <a href=\"#\" data-headword=\"מִישְׁחָא\">מישחא</a>) that oil of thine at Beth M.—<span class=\"citation\">Ab. Zar. 37ᵃ</span> <span dir=\"rtl\">דשרו מ׳</span> who permitted oil (of gentiles). <span class=\"citation\">Ib. 28ᵃ</span> <span dir=\"rtl\">מ׳ דאווזא</span> goose-fat; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>resin</i>. <span class=\"citation\">Targ. Is. XLI, 19</span> אעין דמ׳ <i>pine-wood</i> (h. text <span dir=\"rtl\">עצי שמן</span>, v. <a href=\"#\" data-headword=\"דדנין\">דדנין</a>).—<span class=\"citation\">Succ. 40ᵃ</span>, v. <a href=\"#\" data-headword=\"מִשְׁחָן\">מִשְׁחָן</a>. <span class=\"citation\">Gitt. 69ᵇ</span>, v. <a href=\"#\" data-headword=\"כּוּפְרָא II\"><span dir=\"rtl\">כּוּפְרָא</span> II</a>.</div>","alt":["מִשְׁחָא","מִישְׁ׳ I"]},"16827":{"h":"מְשַׁח IV","r":"M02851","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מְשַׁח II) <i>measure, length</i>. <span class=\"citation\">Targ. II Chr. IV, 2</span> <span dir=\"rtl\">חוט מ׳</span> measuring line; a. e.—[<span class=\"citation\">Targ. I Kings VI, 25</span> <span dir=\"rtl\">משחא חדא</span>, v. <a href=\"#\" data-headword=\"מְשַׁחְתָּא\">מִשְׁחֲתָא</a>.]—<span class=\"citation\">B. Bath. 145ᵇ</span> <span dir=\"rtl\">עתיר משח</span> rich in things that are measured (corn &amp;c.).—<span class=\"citation\">Sabb. 19ᵃ</span> <span dir=\"rtl\">במ׳ ניתיב וכ׳</span> let him give it out (for washing) by measure &amp;c., v. <a href=\"#\" data-headword=\"מָשַׁח II\"><span dir=\"rtl\">מְשַׁח</span> II</a>.—V. <a href=\"#\" data-headword=\"מְשַׁחְתָּא\">מִשְׁחֲתָא</a>.</div>","alt":["מִשְׁחָא","מִי׳ II"]},"16828":{"h":"*משחביב","r":"M02852","html":"<div class=\"sense\"><span class=\"citation\">Targ. Is. XXXIV, 4</span> ed. Lag., Ar. s. v. <a href=\"#\" data-headword=\"שחביב\">שחביב</a>, absent in ed., a corrupt Massoretic gloss, perh. <span dir=\"rtl\">משתבש׳</span>, v. Berl. Mass., p. 142.</div>","alt":[]},"16829":{"h":"מָשְׁחָה","r":"M02853","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>official distinction, official emoluments</i>. <span class=\"citation\">Y. Bicc. II, 64ᵈ</span> (ref. to <span class=\"citation\">Num. XVIII, 8</span>) <span dir=\"rtl\">למ׳ לגדולה למ׳ וכ׳</span> <i>l’moshḥa</i> means for official distinction, for anointing (the body) &amp;c., v. <a href=\"#\" data-headword=\"הַדְלָקָה\">הַדְלָקָה</a>; <span class=\"citation\">Zeb. 28ᵃ</span>, a. e. <span dir=\"rtl\">למ׳ לגדולה וכ׳</span> <i>l’moshḥa</i> means for distinction, as kings eat.</div>","alt":[]},"16830":{"h":"מִשְׁחָה","r":"M02854","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מָשְׁחָה\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>anointing, official installation</i>; <span dir=\"rtl\">שמן המ׳</span> the oil used for installation. <span class=\"citation\">Hor. III, 4</span>; <span class=\"citation\">Meg. I, 9</span>, v. <a href=\"#\" data-headword=\"מָשַׁח I\"><span dir=\"rtl\">מָשַׁח</span> I</a>. <span class=\"citation\">Tosef. Sot. XIII, 1</span> <span dir=\"rtl\">גנז … וצנצנת של שמן המ׳</span> (Josiah) removed out of sight the Ark … and the bottle of the oil of installation (made by Moses). <span class=\"citation\">Hor. 11ᵇ</span> <span dir=\"rtl\">ש׳ המ׳ … היו שולקין וכ׳</span> in the oil of installation which Moses prepared, they boiled the roots of spices. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נמעול מש׳ המ׳</span> Ms. M. (ed. omit <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a>) dare we desecrate the sacred oil (by using it for non-Davidic kings)? <span class=\"citation\">Ib. 12ᵃ</span> <span dir=\"rtl\">ומי הוה ש׳ המ׳</span> did any oil for the installation exist (in the days of Joahaz)?; a. v. fr.—<a href=\"#\" data-headword=\"מוֹרִיָּה\">הר המ׳</a> (= b. h. <span dir=\"rtl\">הר הזיתים</span>) <i>Mount of Olives.</i> <span class=\"citation\">R. Hash. II, 4</span>; Tosef. ib. II (I), 2; a. fr.—[<span class=\"citation\">Sabb. 56ᵇ</span>, quot. fr. <span class=\"citation\">II Kings XXIII, 13</span> <a href=\"#\" data-headword=\"מוֹרִיָּה\">הר המ׳</a>, Ms. M. <span dir=\"rtl\">המשחית</span>.]</div>","alt":[]},"16831":{"h":"מִשְׁחֶזֶת","r":"M02855","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁחַז\">שָׁחַז</a>) <i>whetting implement</i> of stone or wood. <span class=\"citation\">Kel. XVII, 17</span>; <span class=\"citation\">Tosef. Kel. B. Mets. VII, 10</span> <span dir=\"rtl\">מ׳ שיש בה בית וכ׳</span> a (wooden) whetter which has a receptacle for oil. <span class=\"citation\">Bets. 28ᵃ</span> <span dir=\"rtl\">מ׳ של אבן</span> a whetstone; <span dir=\"rtl\">מ׳ של עץ</span> a wooden whetter; a. fr. [Ar. reads <span dir=\"rtl\">מַשְׁחֵז</span>.]</div>","alt":[]},"16832":{"h":"מַשְׁחִית","r":"M02856","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>destroyer</i>, esp. <i>Mashḥith</i>, name of a demon of destruction. <span class=\"citation\">Deut. R. s. 3</span>; <span class=\"citation\">Yalk. Deut. 853</span>; a. e.; v. <a href=\"#\" data-headword=\"הַשְׁחֵת\">הַשְׁחֵת</a>.—הר המ׳ Mount Mashhith, v. <a href=\"#\" data-headword=\"מִשְׁחָה\">מִשְׁחָה</a>.</div>","alt":[]},"16833":{"h":"מִשְׁחָן","r":"M02857","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְשַׁח III\"><span dir=\"rtl\">מִשְׁחָא</span> I</a>) <i>pine</i>. <span class=\"citation\">Succ. 40ᵃ</span> <span dir=\"rtl\">עצים דמ׳</span> (Ms. M. <span dir=\"rtl\">דמישחא</span>) wood of the pine-tree (used for torches).</div>","alt":[]},"16834":{"h":"מִשְׁחָנָא","r":"M02858","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִשְׁחָן\">preced.</a>) <i>ointment, perfumed oil</i>.—Pl. <span dir=\"rtl\">מִשְׁחָנִין</span>. Targ. II Esth. VI, 11 (ed. Vien. <span dir=\"rtl\">מַשְׁחֲנִין</span>); a. e.</div>","alt":[]},"16835":{"h":"משחף","r":"M02859","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשַׁח III\"><span dir=\"rtl\">מְשַׁח</span> III</a></div>","alt":[]},"16836":{"h":"מְשַׁחְתָּא","r":"M02860","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מְשַׁחְתָּא\">מִשְׁחֲתָא</a>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a> f. (מְשַׁח II) <i>measure, length</i>. <span class=\"citation\">Targ. I Kings VI, 25</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"מְשַׁח III\">מִשְׁחָא</a> <i>fem</i>.). <span class=\"citation\">Targ. Ex. XXVI, 2</span>; a. fr.—<span class=\"citation\">Sabb. 74ᵇ</span> <span dir=\"rtl\">אי קפיד אמ׳</span> if he is particular about a uniform length (of the chips). <span class=\"citation\">B. Mets. 107ᵇ</span> <span dir=\"rtl\">לא תזלזל במי׳</span> (or <span dir=\"rtl\">במִישְׁחָתָא</span>, <i>pl.</i>) do not treat surveying lightly.—<i>Pl.</i> <a href=\"#\" data-headword=\"מִשְׁחָן\">מִשְׁחָן</a>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <span class=\"citation\">Targ. O. Num. XIII, 32</span> <span dir=\"rtl\">אינשן דמ׳</span> (h. text <span dir=\"rtl\">אנשי מדות</span>).—<a href=\"#\" data-headword=\"מְשַׁחְתָּא\">מִשְׁחָתָא</a>. <span class=\"citation\">Targ. Ez. XL, 28</span>, sq.; a. e.—[משחתא <i>balance</i>, v. <a href=\"#\" data-headword=\"מְסָאתָא\">מְסָאתָא</a> a. <a href=\"#\" data-headword=\"מִסְחֲתָא\">מִסְהֲתָא</a>.]</div>","alt":[]},"16837":{"h":"מַשְׁטוּחָא","r":"M02861","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁטָחָא\">מַשְׁטָחָא</a></div>","alt":[]},"16838":{"h":"מִשְׁטֵחַ","r":"M02862","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(b. h. <i>spreading, grapes spread on the ground; spreading place.</i> <span class=\"citation\">Toh. X, 4</span> <span dir=\"rtl\">הנותן … ומן המ׳ של אדמה</span> he who puts in the press grapes collected in baskets or such as were spread on the (naked) ground; ib. <span dir=\"rtl\">מן המ׳ של עלים</span> grapes spread on leaves. Tosef. ib. XI, 8. Y’lamd. to Num. VII, 1 <span dir=\"rtl\">ממלא מִשְׁטֵחוֹ</span> he fills his spreading place.—Pl. <span dir=\"rtl\">מִשְׁטֵחִים</span>, <span dir=\"rtl\">מִשְׁטֵחִין</span>, <span dir=\"rtl\">מִשְׁטֵי׳</span> <i>layers</i>. <span class=\"citation\">Sifré Num. 98</span> <span dir=\"rtl\">שהיתה עשויה מ׳ מ׳</span> the quails formed layers; <span class=\"citation\">Yoma 75ᵇ</span></div>","alt":["מִשְׁטֵיחַ"]},"16839":{"h":"מַשְׁטָחָא","r":"M02863","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Kings XVIII, 17</span> <span dir=\"rtl\">חקל מַשְׁטַח וכ׳</span> field where washers spread (their clothes).—Pl. <span dir=\"rtl\">מַשְׁטָחִין</span> <i>layers</i>. <span class=\"citation\">Targ. O. Num. XI, 32</span> ed. Berl. (Var. <span dir=\"rtl\">מַשְׁטִיחִין</span>, <span dir=\"rtl\">מְשַׁטְּחִין</span>, v. Berl. Targ. O. II, p. 41; Ms. II <span dir=\"rtl\">מַשְׁטוּ׳</span>; Y. <span dir=\"rtl\">מַשְׁטִי׳</span>).</div>","alt":[]},"16840":{"h":"מִשְׁטֵיחַ","r":"M02864","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מַשְׁטוּחָא\">מַשְׁטִיחָא</a>, v. <a href=\"#\" data-headword=\"מַשְׁטָחָא\">preced.</a> wds.</div>","alt":[]},"16841":{"h":"מִשְׂטָר","r":"M02865","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְטר\">מִסְטָר</a></div>","alt":[]},"16842":{"h":"מְשֵׁי","r":"M02866","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מְשָׁא\">מְשָׁא</a> (cmp. <a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>to feel, touch</i>. <span class=\"citation\">Targ. O. Gen. XXVII, 22</span>.</div><div class=\"sense\"><b>—2)</b>  (with <a href=\"#\" data-headword=\"יַד\">ידא</a>) <i>to rub</i>, whence <i>to wash and dry</i>, esp. <i>one’s hands</i> before and after meals. <span class=\"citation\">Ber. 46ᵇ</span> <span dir=\"rtl\">מְשִׁי ידך</span> wash thy hands. <span class=\"citation\">Ḥull. 107ᵃ</span> <span dir=\"rtl\">מְשׁוּ ידייכו וכ׳</span> wash your hands in the morning. <span class=\"citation\">Ib. 46ᵇ</span> <span dir=\"rtl\">ולא מְשִׁית ידיך</span> (not <span dir=\"rtl\">ידיה</span>) and didst not wash thy hands. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ואנא מָשֵׁינָא</span> and I should wash? <span class=\"citation\">Pes. 112ᵃ</span>. <span class=\"citation\">Ned. 91ᵃ</span> <span dir=\"rtl\">מַשְׁיָא ידיה וכ׳</span> she washed her husband’s hands. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">למִמְשָׁא</span> to wash; a. fr.—<span class=\"citation\">Sabb. 77ᵇ</span> <a href=\"#\" data-headword=\"מָאשֵׁי\">מָאשֵׁי</a>, v. <a href=\"#\" data-headword=\"מְשִׁיכְלָא\">מְשִׁיכְלָא</a>. <span class=\"citation\">Kidd. 52ᵇ</span> <span dir=\"rtl\">מַשְׁיָא כרעא וכ׳</span> was washing a foot in a basin of water.</div><div class=\"sense\"><b>Af. אַמְשֵׁי</b> <div class=\"sense\"><i>to handle, draw</i>. <span class=\"citation\">B. Bath. 153ᵃ</span>. <span dir=\"rtl\">אַמְשִינְהוּ … במיא</span> they drew Raba’s clothes through water.</div></div>","alt":[]},"16843":{"h":"משיגא","r":"M02867","html":"<div class=\"sense\">, Y. Shek. VII, 50ᶜ bot., read <span dir=\"rtl\">משזגא</span>, v. <a href=\"#\" data-headword=\"שְׁזַג\">שְׁזַג</a></div>","alt":[]},"16844":{"h":"מְשֵׁיזֵב","r":"M02868","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שֵׁיזֵיב\">שִׁיזֵיב</a>) <i>one who has escaped, refugee</i>. <span class=\"citation\">Targ. Deut. III, 3</span> (Y. <span dir=\"rtl\">מְשֵׁזִיב</span>). <span class=\"citation\">Targ. II Kings IX, 15</span>; a. fr.—Pl. <span dir=\"rtl\">מְשֵׁיזְבִין</span>, <span dir=\"rtl\">מְשֵׁיזְבַיָּא</span>, <span dir=\"rtl\">מְשֵׁזְ׳</span>. <span class=\"citation\">Targ. Is. LXVI, 19</span>. <span class=\"citation\">Targ. Jud. XII, 4</span>; a. fr.</div>","alt":["מְשֵׁיזְבָא מְשֵׁיזִיב"]},"16845":{"h":"מְשֵׁיזֵבְתָּא","r":"M02869","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשֵׁיזֵב\">preced.</a>) <i>escape, deliverance</i>. <span class=\"citation\">Targ. Ob. I, 17</span> (ed. Lag. <a href=\"#\" data-headword=\"שֵׁיזֶבְתָּא\">שֵׁיזֵבְתָּא</a>).</div>","alt":[]},"16846":{"h":"מָשִׁיחַ","r":"M02870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>anointed</i>, esp. </div><div class=\"sense\"><b>1)</b>  <span dir=\"rtl\">כֹּהֵן מ׳</span> or <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (v. <a href=\"#\" data-headword=\"מָשׁוּחַ\">מָשׁוּחַ</a>, s. v. <a href=\"#\" data-headword=\"מָשַׁח I\"><span dir=\"rtl\">מָשַׁח</span> I</a>, v. <span class=\"citation\">Lev. IV, 3</span>) <i>the high priest installed by anointment</i>. <span class=\"citation\">Tosef. Meg. I, 18</span> <span dir=\"rtl\">כ׳ מ׳ משמש</span> the active high priest; <span dir=\"rtl\">כ׳ מ׳ שעבר</span> the unfitted high priest (prevented from officiating on the Day of Atonement). <span class=\"citation\">Hor. III, 4</span> <span dir=\"rtl\">ואיזהו המ׳ המשוח וכ׳</span> what high priest is called <i>mashiaḥ?</i> He who has been anointed &amp;c. Sifra Vayikra, Ḥobah, ch. I, Par. 2, a. e. <span dir=\"rtl\">מ׳ יכול זה המלך</span> by <i>mashiaḥ</i> (<span class=\"citation\">Lev. IV, 3</span>) you might understand the king. Ib. <span dir=\"rtl\">המ׳ זה מ׳ וכ׳</span> ‘the anointed’ means an anointed who has no superior anointed; a. fr.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">מֶלֶךְ הַמָּ׳</span>, or <span dir=\"rtl\">מָ׳</span> <i>the Messiah, the future redeemer of Israel from captivity</i>. <span class=\"citation\">Gen. R. s. 2</span> (ref. to <span class=\"citation\">Gen. I, 2</span>) <span dir=\"rtl\">זה רוחו של מ׳ המ׳</span> that means the divine spirit of the king Messiah (with ref. to <span class=\"citation\">Is. XI, 2</span>). <span class=\"citation\">Succ. 52ᵃ</span>, a. fr. <span dir=\"rtl\">מ׳ בן דוד</span> the Davidic Messiah, contrad. to <span dir=\"rtl\">מ׳ בן יוסף</span> the M., son of Joseph, who is to precede the former. <span class=\"citation\">Snh. 98ᵇ</span> אין מ׳ לישראל וכ׳ Israel has no Messiah to expect, for it has enjoyed him (the glory which he was predicted to bring) in the days of Hezekiah. <span class=\"citation\">Ib. 97ᵃ</span>; a. fr.—<span dir=\"rtl\">ימות המ׳</span> the Messianic epoch. Ib. bot. <span class=\"citation\">Ber. I, 5</span> <span dir=\"rtl\">להביא לימות מ׳</span> this includes (the duty of remembering the exodus from Egypt) even in the Messianic days; a. fr.—<span dir=\"rtl\">חבלו של מ׳</span>, v. <a href=\"#\" data-headword=\"חֵבֶל\">חֵבֶל</a>.—Pl. <span dir=\"rtl\">מְשִׁיחִים</span>. <span class=\"citation\">Pesik. R. s. 8</span> (ref. to <span class=\"citation\">Zech. IV, 3</span>) <span dir=\"rtl\">אלו שני המ׳ אחד משוח מלחמה וכ׳</span> these are the two expected Messiahs, one appointed to conduct war (<span dir=\"rtl\">מ׳ בן יוסף</span>) &amp;c.; <span class=\"citation\">Yalk. Zech. 570</span>.</div>","alt":[]},"16847":{"h":"מְשִׁיחָא I","r":"M02871","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. XXIV, 7</span>; a. fr.—Esp. <span dir=\"rtl\">מַלְכָּא מְ׳</span> or <a href=\"#\" data-headword=\"מָנִיכָא\">מְ׳</a> <i>the Messiah</i>, v. <a href=\"#\" data-headword=\"מָשִׁיחַ\">preced.</a> <span class=\"citation\">Targ. I Chr. III, 24</span>. <span class=\"citation\">Targ. Y. Ex. XL, 9</span>; a. fr.—[<span class=\"citation\">Targ. Cant. IV, 5</span> <span dir=\"rtl\">מָשִׁיחַ בר דוד</span>, <span dir=\"rtl\">מָ׳ בר אפרים</span>, v. preced.]—<span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">היינו מלכא מ׳</span> this (Bar Kokhba) is the expected king Messiah; Y. Taan. IV, 68ᵈ bot.—<span class=\"citation\">Sot. IX, 15</span> (<span class=\"citation\">49ᵇ</span>) <span dir=\"rtl\">בעקבות מ׳</span> in the period preceding the coming of the Messiah; a. fr.</div>","alt":[]},"16848":{"h":"מְשִׁיחָא II","r":"M02872","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rope</i>, v. <a href=\"#\" data-headword=\"מְשִׁיחָה II\"><span dir=\"rtl\">מְשִׁיחָה</span> II</a> a. <a href=\"#\" data-headword=\"מְשִׁיחֲתָא\"><a href=\"#\" data-headword=\"מְשִׁיחֲתָא\">מְשִׁיחֲתָא</a>.</a></div>","alt":[]},"16849":{"h":"מְשִׁיחָה I","r":"M02873","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מָשַׁח I) <i>anointing, installation by anointing; use of the stem</i> <a href=\"#\" data-headword=\"מָשַׁח I\">מָשַׁח</a>. <span class=\"citation\">Ker. 5ᵇ</span>, a. fr. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בעי\">בעי</a>) <span dir=\"rtl\">טעון מ׳</span></span> requires anointment (in order to be recognized). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ עדיפא</span> anointing (by drawing a figure, v. <a href=\"#\" data-headword=\"מָשַׁח I\"><span dir=\"rtl\">מָשַׁח</span> I</a>) is preferable to pouring oil <a href=\"#\" data-headword=\"יְצִיקָה\">(יְצִיקָה</a>). <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">מְשִׁיחַת אהרן כיצד</span> how was Aaron’s installation done? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">במְשִׁיחָתָן של אלו וכ׳</span> with the anointment of these vessels were all the vessels of subsequent days consecrated. <span class=\"citation\">Sifré Num. 117</span> <span dir=\"rtl\">אין מ׳ אלא גדולה</span> the stem <a href=\"#\" data-headword=\"מְשַׁח\">משח</a> refers to official emoluments, as we read (<span class=\"citation\">Lev. VII, 35</span>) &amp;c.; ib. <span dir=\"rtl\">אין מ׳ אלא שמן המשחה</span> <i>mashaḥ</i> means installation with oil; a. fr.</div>","alt":[]},"16850":{"h":"מְשִׁיחָה II","r":"M02874","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מָשַׁח II) <i>band, cord</i>, esp. <i>flax rope for surveying</i>. <span class=\"citation\">Tosef. Erub. VI</span> (<span class=\"citation\">V), 13</span>. <span class=\"citation\">Kel. XXI, 3</span> <span dir=\"rtl\">בחוט ובמ׳</span> the string or the rope (of the saw). <span class=\"citation\">Tosef. Sabb. V</span> (<span class=\"citation\">VI), 2</span> <span dir=\"rtl\">כרכן במ׳</span> (ed. Zuck. <span dir=\"rtl\">במשיחא</span>) tied a cord around them; <span class=\"citation\">Sabb. 50ᵃ</span>. <span class=\"citation\">Tosef. Ḥull. III</span> (<span class=\"citation\">IV), 22</span> <span dir=\"rtl\">כל הנותן ע&quot;ג מ׳ החולק וכ׳</span> when you place a fowl on a rope, that fowl which divides its claws &amp;c., is unclean; <span class=\"citation\">Ḥull. 65ᵃ</span> <span dir=\"rtl\">מותחין לו חוט של מ׳</span> you stretch a cord for it in a line; a. fr.—Pl. <a href=\"#\" data-headword=\"מְשִׁיחוּת\">מְשִׁיחוֹת</a>. <span class=\"citation\">Kil. IX, 9</span> <span dir=\"rtl\">מ׳ של ארגמן</span> purple-colored ribbons, v. <a href=\"#\" data-headword=\"מָלַל I\">מָלַל</a> I end; Y. ib. 32ᵈ. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 7</span>.</div>","alt":[]},"16851":{"h":"מְשִׁיחוּת","r":"M02875","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מָשִׁיחַ\">מָשִׁיחַ</a>) <i>office of the anointed priest</i>. <span class=\"citation\">Hor. III, 1</span> <span dir=\"rtl\">עבר ממְשִׁיחוּתוֹ</span> resigned his office.</div>","alt":[]},"16852":{"h":"מְשִׁיחֲתָא","r":"M02876","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> ch. = h., <i>rope</i>. <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> top <span dir=\"rtl\">יהבון מ׳ וכ׳</span> fasten a rope to my feet; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> bot. <span dir=\"rtl\">יבון משיחא בריגלי</span> (not <span dir=\"rtl\">בריגלו</span>).—Y. Kil. l. c. bot. (R. Meir said before his death) <span dir=\"rtl\">הא מְשִׁיחֲכוֹן דידכון</span> this is your band (the attraction of Palestine made me travel all the way to die there); Y. Keth. l. c. bot. <span dir=\"rtl\">די דא מ׳ וכ׳</span> (corr. acc.).</div>","alt":["מְשִׁיחָא"]},"16853":{"h":"מְשָׁיְילָא","r":"M02877","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<span dir=\"rtl\">שאל</span>) = h. <a href=\"#\" data-headword=\"מִשְׁאָלָה\">מִשְׁאֲלָה</a>, <i>prayer, request</i>.—Pl. constr. <a href=\"#\" data-headword=\"מְשָׁיְילָא\">מְשָׁיְילֵי</a>. <span class=\"citation\">Targ. Ps. XXXVII, 4</span> (ed. Wil. <a href=\"#\" data-headword=\"מַשְׁיָלֵי\">מֵשְׁיָלֵי</a>).</div>","alt":[]},"16854":{"h":"מְשִׁיךְ","r":"M02878","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשַׁךְ I\">מְשַׁךְ</a></div>","alt":[]},"16855":{"h":"מְשִׁיכָה","r":"M02879","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁךְ I\">מָשַׁךְ</a>) <i>drawing, pulling</i>. <span class=\"citation\">Y. B. Kam. X, end, 7ᶜ</span> <span dir=\"rtl\">מְשִׁיכַת המחט</span>, v. <a href=\"#\" data-headword=\"מַחַט\">מַחַט</a>. <span class=\"citation\">Num. R. s. 18</span>, beg. <span dir=\"rtl\">משיכת דברים רכים</span> the drawing (winning) power of soft words; Tanḥ. Korah 1; a. e.—Esp. <i>m’shikhah, taking possession by drawing towards one’s self the object to be acquired</i>. <span class=\"citation\">Kidd. I, 4</span> <span dir=\"rtl\">נקנית במ׳</span> is taken possession of by pulling, contrad. to <a href=\"#\" data-headword=\"הַגְבָּהָה\">הַגְבָּהָה</a> a. <a href=\"#\" data-headword=\"מְסִירָה\">מְסִירָה</a>. <span class=\"citation\">B. Mets. 9ᵃ</span>, contrad. to <a href=\"#\" data-headword=\"הַנְהָגָה\">הַנְהָגָה</a>. <span class=\"citation\">Ib. 47ᵇ</span>, a. e. <span dir=\"rtl\">כדרך שתיקנו מ׳ וכ׳</span> as the scholars declared <i>m’shikhah</i> to be necessary to bind the seller, so did they make it necessary to bind the buyer; a. fr.</div>","alt":[]},"16856":{"h":"משיכות","r":"M02880","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ohol. XVIII, 12</span>, v. <a href=\"#\" data-headword=\"מְשׂוּכָּה\">מְשׂוּכָּה</a></div>","alt":[]},"16857":{"h":"משיכותא","r":"M02881","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשִׁיכְלָא\">next w.</a></div>","alt":[]},"16858":{"h":"מְשִׁיכְלָא","r":"M02882","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׂכַל I\">שכל</a>, Shaf. of <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>; cmp. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָא</a>, <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילְתָּא</a>) </div><div class=\"sense\"><b>1)</b> <i>a wash-basin</i>. <span class=\"citation\">Sabb. 77ᵇ</span> (phonetic etymol.) <span dir=\"rtl\">מ׳ מאשי כולא</span> ‘washing everybody’, contrad. to <a href=\"#\" data-headword=\"מַשְׁכִּילְתָּא\">משכילתא</a>: <span dir=\"rtl\">משיא כלתא</span> ‘washing brides’ (distinguished people). <span class=\"citation\">Kidd. 52ᵇ</span>, v. <a href=\"#\" data-headword=\"מְשֵׁי\">מְשֵׁי</a>.—Pl. <a href=\"#\" data-headword=\"מְשִׁיכְלָא\">מְשִׁיכְלֵי</a>. <span class=\"citation\">Ab. Zar. 39ᵃ</span> <span dir=\"rtl\">מ׳ חיורי</span> white (glazed) basins. <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">שיתין מ׳ דמא</span> sixty basin-fuls of blood. <span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">מ׳ דמני וכ׳</span> (Ms. M. sing.) basins filled with linen garments (for rinsing in the lake). <span class=\"citation\">Gitt. 69ᵇ</span> bot.—Fem. form <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מַשְׁכִּילְתָּא\">מַשְׁכִּילְתָּא</a>) <a href=\"#\" data-headword=\"מְשִׁיכְלָא\">מְשִׁיכְלְתָא</a></span>. Sabb. l. c. <span dir=\"rtl\">משיכ׳</span> Ms. M. (ed. <span dir=\"rtl\">משכיל׳</span>), v. supra. <span class=\"citation\">Ḥull. 47ᵇ</span> <span dir=\"rtl\">משיכותא דמיא וכ׳</span> (corr. acc.) a basin of tepid water. <span class=\"citation\">Ab. Zar. 51ᵇ</span> <span dir=\"rtl\">דסחיפא ליה מ׳ ארישיה</span> (v. Rabb. D. S. a. l. note 8) the idolatrous statuary has an inverted washbasin on its head.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a>, <a href=\"#\" data-headword=\"מָאן\">מָאן</a> as <i>vessel</i> and <i>garment</i>) <i>a sort of cloak</i>. <span class=\"citation\">Lev. R. s. 23</span> (expl. <a href=\"#\" data-headword=\"שְׂמִיכָה\">שמיכה</a>, <span class=\"citation\">Jud. IV, 18</span>) <span dir=\"rtl\">רבנן … ורבנן דתמן אמרי במ׳</span> the rabbis here (in Palestine) say, it means with a <i>sudra</i> <a href=\"#\" data-headword=\"סוּדָרָא\">(סוּדְרָא</a>), while the Babylonian rabbis say <i>m’shikhla</i>; <span class=\"citation\">Yalk. Jud. 44</span>; <span class=\"citation\">Yalk. Lev. 585</span>.</div>","alt":[]},"16859":{"h":"מַשְׁיָלֵי","r":"M02883","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשָׁיְילָא\">מְשָׁיְילָא</a></div>","alt":[]},"16860":{"h":"מְשִׁילְיָא","r":"M02884","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשִׁלְיָא\">מְשִׁלְיָא</a></div>","alt":[]},"16861":{"h":"מְשִׂימָה","r":"M02885","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שׂוּם\">שׂוּם</a>, formed with ref. to <span dir=\"rtl\">שום תשים</span>, <span class=\"citation\">Deut. XVII, 15</span>) <i>appointment, office.</i> <i>—</i> Pl. <span dir=\"rtl\">מְשִׂימוֹת</span>. <span class=\"citation\">Yeb. 45ᵇ</span> <span dir=\"rtl\">כל מ׳ שאתה משים וכ׳</span> whatever offices thou createst, the elected must be from among thy brethren; <span class=\"citation\">Kidd. 76ᵇ</span>; a. e.</div>","alt":[]},"16862":{"h":"מְשִׁיפָה","r":"M02886","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שׁוּף\">שׁוּף</a>) <i>embrocation</i>. <span class=\"citation\">Sabb. 77ᵇ</span></div>","alt":[]},"16863":{"h":"מְשִׁיקוֹת","r":"M02887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוֹקְיוּתָא\">שׁוֹקְיוּתָא</a></div>","alt":[]},"16864":{"h":"מַשִּׁירְיָא","r":"M02888","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">מַשְׁרִיתָא</a></div>","alt":[]},"16865":{"h":"מְשִׁיתָא","r":"M02889","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’shitha</i>, surname of one Joseph or José. <span class=\"citation\">Gen. R. s. 65</span>; <span class=\"citation\">Yalk. Gen. 114</span> <span dir=\"rtl\">משיתה</span>.</div>","alt":[]},"16866":{"h":"מֶשֶׁךְ","r":"M02890","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Meshech</i>, a son of Japheth and progenitor of a race of the same name (v. Schrader KAT, p. 84). <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot.; <span class=\"citation\">Yoma 10ᵃ</span>, v. <a href=\"#\" data-headword=\"מוּסְיָא\">מוּסְיָא</a>.</div>","alt":[]},"16867":{"h":"משַׁךְ","r":"M02891","html":"<div class=\"sense\"><i>to draw, pull; to seize;</i> (with <span dir=\"rtl\">מן</span>) <i>to withdraw;</i> in gen. <i>to stretch, produce a continuous line or flow; to conduct.</i> <span class=\"citation\">Kil. VIII, 2</span> <span dir=\"rtl\">לחרוש לִמְשׁוֹךְ ולהנהיג</span> to plough with, to pull (by the head, go in front of), and to drive. <span class=\"citation\">Gen. R. s. 86</span> <span dir=\"rtl\">שהיו מוֹשְׁכִין וכ׳</span>, v. infra. Mekh. Bo, s. 11 (ref. to <span class=\"citation\">Ex. XII, 21</span>) <span dir=\"rtl\">מִשְׁכוּ מי שיש לו וכ׳</span> ‘lead forth’ (select), refers to him who has a lamb, ‘and buy’, refers to one who has none. Ib. <span dir=\"rtl\">מִשְׁכוּ מע&quot;ז</span> withdraw from idolatry. Ib. <span dir=\"rtl\">שמוֹשְׁכִין את ידיהם ממנו וכ׳</span> that you may withdraw your share in the Passover lamb as long as it has not been slaughtered (v. <a href=\"#\" data-headword=\"מני\">מָנָה</a>); <span class=\"citation\">Pes. VIII, 3</span>. <span class=\"citation\">Ib. IX, 10</span> <span dir=\"rtl\">אלו מושכין להן אחד וכ׳</span> the one company select one lamb, the other &amp;c.—<span class=\"citation\">M. Kat. I, 3</span> <span dir=\"rtl\">מוֹשְׁכִים את המים וכ׳</span> you may draw (conduct) the water in channels from tree to tree. <span class=\"citation\">Pesik. R. s. 26</span> <span dir=\"rtl\">שמא יִמְשׁוֹךְ לו חלב והוא אינו מוֹשֵׁךְ</span> perhaps it (the breast) will yield him milk when sucking, but it did not yield. <span class=\"citation\">Ex. R. s. 52</span> <span dir=\"rtl\">התחילה מוֹשֶׁכֶת דינרי וכ׳</span> it (the valley) began to give forth a flow of gold denars before their eyes. <span class=\"citation\">Tosef. Sot. XIV, 8</span>; <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">מוֹשְׁכֵי הרוק</span> those who draw out their spittle (assume aristocratic airs). <span class=\"citation\">Ḥag. 14ᵃ</span> <span dir=\"rtl\">מושכין לבו וכ׳</span> they draw the heart of the people as one conducts water, when they lecture; <span class=\"citation\">Sabb. 87ᵃ</span> (play on <span dir=\"rtl\">ויגד</span>, <span class=\"citation\">Ex. XIX, 9</span>, v. <a href=\"#\" data-headword=\"נָגַד\">נָגַד</a>) <span dir=\"rtl\">דברים שמושכין … כאגדה</span> words which draw (attract) the heart of man like a lecture. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top <span dir=\"rtl\">מָשְׁכוּ צינורות דם וכ׳</span> the gutters of Laodicea carried a flow of blood; a. v. fr.—Esp. (law) <i>to take possession</i> by drawing or seizing an object, v. <a href=\"#\" data-headword=\"מְשִׁיכָה\">מְשִׁיכָה</a>. <span class=\"citation\">B. Mets. IV, 2</span> <span dir=\"rtl\">מ׳ הימנו פירות וכ׳</span> if he took possession of fruits bought of him before paying. <span class=\"citation\">Ib. 47ᵃ</span> <span dir=\"rtl\">לא הספיק לִמְשׁוֹךְ וכ׳</span> he had not yet had time to take possession of the ass; a. v. fr.—<span class=\"citation\">Zeb. 6ᵇ</span> <span dir=\"rtl\">סכין מוֹשְׁכַתָּן למה שהן</span> the slaughtering knife takes possession of them for what they are to be, i.e. the slaughtering of the sacrifices decides their purpose; <span class=\"citation\">Shebu. 12ᵇ</span>.—מ׳ ערלה <i>to stretch the prepuce, to disguise circumcision</i>. <span class=\"citation\">Y. Peah I, 16ᵇ</span>; a. e.—Part. pass. <a href=\"#\" data-headword=\"מָשׁוּךְ\">מָשׁוּךְ</a>; f. <a href=\"#\" data-headword=\"מְשׂוּכָּה\">מְשׁוּכָה</a>; pl. <span dir=\"rtl\">מְשׁוּכִים</span>, <span dir=\"rtl\">מְשׁוּכִין</span>; <span dir=\"rtl\">מְשׁוּכוֹת</span> a) <i>straight-lined, continuous</i>. <span class=\"citation\">Nidd. 57ᵇ</span> <span dir=\"rtl\">אם מ׳</span> if the blood-stain has the shape of a line, opp. <span dir=\"rtl\">עגול</span>. <span class=\"citation\">Y. Erub. I, 19ᵇ</span> top <span dir=\"rtl\">היה מ׳</span> if the wall is straight-lined. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שלא תהא הקורה מ׳ וכ׳</span> that the beam be not prolonged more than &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">במשוכין יותר וכ׳</span> when they are longer than &amp;c.; a. fr.—<span class=\"citation\">Mikv. V, 3</span>, v. <a href=\"#\" data-headword=\"נָדָל\">נָדָל</a>.—b) (with <span dir=\"rtl\">מ־</span>) <i>withdrawn</i>. <span class=\"citation\">Pes. IX, 10</span> <span dir=\"rtl\">ידיך מ׳ משלך וכ׳</span> thy share be withdrawn from thy lamb, and be transferred to ours; a. e.—c) v. <a href=\"#\" data-headword=\"מָשׁוּךְ\">מָשׁוּךְ</a>.</div><div class=\"sense\"><b>Nif. נִמְשַׁךְ</b> <div class=\"sense\"><b>1)</b> <i>to be stretched</i>. Y. Yeb. VIII, 8ᵈ bot. <span dir=\"rtl\">נִמְשְׁכָה מאליה</span> if the prepuce overgrew the corona of itself, v. <a href=\"#\" data-headword=\"מָשׁוּךְ\">מָשׁוּךְ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to be prolonged, continued</i>. <span class=\"citation\">Hor. 12ᵃ</span>. <span dir=\"rtl\">אין מושחין … כדי שׁתִּמָּשֵׁךְ מלכותן</span> kings are anointed at a spring in order that their government may be prolonged (cmp. Ḥag. l. c.). Ib. <span dir=\"rtl\">נמשכה מלכותן</span> their dynasty was prolonged; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be withdrawn</i>. <span class=\"citation\">Tosef. Pes. VII, 7</span> <span dir=\"rtl\">רצו להִמָּשֵׁךְ ולהמנות וכ׳</span> (ed. Zuck. incorrect) if they desire to withdraw, and that others be entered &amp;c. Ib. <span dir=\"rtl\">נִמְשָׁכִין והולכין וכ׳</span> they may go on withdrawing &amp;c., a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to be drawn after; to follow</i>. <span class=\"citation\">Ex. R. s. 24</span>. <span class=\"citation\">Gen. R. s. 86</span> <span dir=\"rtl\">לפרה שהיו מושכין … ולא היתה נִמְשֶׁכֶת</span> like a cow which they attempt to pull to the slaughter-house, and which will not go; a. fr.</div><div class=\"sense\"><b>—5)</b> <i>to be conducted in a channel</i>. <span class=\"citation\">Tosef. Par. IX (VIII), 9</span> <span dir=\"rtl\">המים הנִמְשָׁכִין וכ׳</span> well-water derived into a channel &amp;c., v. <a href=\"#\" data-headword=\"מָרַץ\">מָרַץ</a>; a. e.</div></div><div class=\"sense\"><b>Hif. הִמְשִׁיךְ</b> <div class=\"sense\"><b>1)</b> <i>to cause to extend</i>. <span class=\"citation\">Keth. 10ᵇ</span> (the rain) <span dir=\"rtl\">מצדן ומַמְשִׁיךְ</span> gives beauty and enlargement (to the fruits).</div><div class=\"sense\"><b>—2)</b> <i>to draw, pull</i>. Y. Kil. VIII, 31ᶜ top, a. e. <span dir=\"rtl\">הנהיגה הִמְשִׁיכָהּ וכ׳</span> if he drove the animal, or pulled it, or called it. <span class=\"citation\">Ex. R. s. 20</span>, beg. <span dir=\"rtl\">הִמְשַׁכְתִּיו ברסן</span> I pulled him by the bridle; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to conduct</i> water into channels. <span class=\"citation\">Tem. 12ᵇ</span> <span dir=\"rtl\">שאובה שהִמְשִׁיכוּהָ כולה</span> a collection of drawn water all of which has been conducted through a channel. Y. Shebi. II, end, 34ᵇ <span dir=\"rtl\">להַמְשִׁיךְ</span> to irrigate by gutters, contrad. to <span dir=\"rtl\">להשקות</span>. Y. M. Kat. I, 80ᵇ top <span dir=\"rtl\">ה׳ המעיין וכ׳</span> he led the water of a well into it. <span class=\"citation\">Tosef. Sabb. VII</span> (<span class=\"citation\">VIII), 16</span> <span dir=\"rtl\">מַמְשִׁיכִין יין וכ׳</span> you may let wine or oil run in gutters before bride and groom; <span class=\"citation\">Ber. 50ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to prolong a meal, to add a course</i>. <span class=\"citation\">Succ. 27ᵃ</span>, v. <a href=\"#\" data-headword=\"פַּרְפֶּרֶת\">פַּרְפֶּרֶת</a>.</div></div>","alt":[]},"16868":{"h":"מְשַׁךְ I","r":"M02892","html":"<div class=\"sense\"><b>1)</b> <i>to draw, carry along</i>. <span class=\"citation\">Targ. Y. Gen. IX, 20</span> <span dir=\"rtl\">דמושכיה נהרא וכ׳</span> (read: <span dir=\"rtl\">דמַשְׁכֵיה</span>) which the river had carried along from &amp;c.—<span class=\"citation\">Zeb. 53ᵇ</span>, a. e. <span dir=\"rtl\">מַשְׁכוּ גברי לגברא</span> the many brought the single man over (to their opinion).</div><div class=\"sense\"><b>—2)</b> <i>to attract</i>. <span class=\"citation\">Ab. Zar. 27ᵇ</span> <span dir=\"rtl\">שאני מינות דמָשְּׁכָא</span> it is different with heresy, because it attracts (persuades, offers inducements).</div><div class=\"sense\"><b>—3)</b>  (neut. verb) <a href=\"#\" data-headword=\"מְשַׁךְ I\">מְשׁךְ</a>, <a href=\"#\" data-headword=\"מְשִׁיךְ\">מְשִׁיךְ</a> <i>to run in a continuous line; to be prolonged, continued</i>. <span class=\"citation\">Targ. Y. Num. XXI, 35</span>; <span class=\"citation\">Ber. 54ᵇ</span> <span dir=\"rtl\">מַשְׁכֵי שיניה</span> his teeth were prolonged. <span class=\"citation\">Hor. 12ᵃ</span> <span dir=\"rtl\">כי היכי דמַשְׁכוּ מיא מַשְׁכָן וכ׳</span>. as the water runs continually, so may the traditions which you teach be continued. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אי משיך נהוריה</span> (Rashi <a href=\"#\" data-headword=\"מְשִׁיךְ\">משיך</a>) if the light continues to burn; <span class=\"citation\">Ker. 5ᵇ</span>.—[<span class=\"citation\">Ib.</span> <span dir=\"rtl\">משכו שתא</span>, read: <a href=\"#\" data-headword=\"מַסִּיק I\">מסיק</a>.]—<span class=\"citation\">Pes. 8ᵃ</span> <span dir=\"rtl\">משיך נהוריה</span> the light (of a lamp or a candle) burns steadily, opp. <span dir=\"rtl\">מיקטף איקטופי</span>. <span class=\"citation\">Ab. Zar. 2ᵇ</span> <span dir=\"rtl\">משכי במלכותייהו</span> they will continue their rulership; <span class=\"citation\">Yalk. Is. 316</span> <span dir=\"rtl\">משכה מלכותייהו</span>; a. e.</div><div class=\"sense\"><b>—4)</b> <i>to take possession</i>. <span class=\"citation\">B. Mets. 48ᵃ</span> <span dir=\"rtl\">עד דמָשֵׁיךְ</span> until he takes possession; <span dir=\"rtl\">עד דמשך</span> until he has taken &amp;c. Ib. 49ᵃ <span dir=\"rtl\">מַשְׁכֵיה</span> he has taken possession of it; a. fr.—<span class=\"citation\">Meg. 31ᵃ</span> משך תורא ‘take possession of the ox’ (mnemotechnical words to designate the order of Scriptural readings on the Passover days, ref. to <span dir=\"rtl\">משכו</span>, <span class=\"citation\">Ex. XII, 21</span>; <a href=\"#\" data-headword=\"שִׁיר I\">שור</a>, <span class=\"citation\">Lev. XXII, 26</span></div><div class=\"sense\"><b>Ithpe. אִימְּשִׁיךְ</b> <div class=\"sense\"><b>1)</b> <i>to be attracted, carried away, seduced</i>. Ab. Zar. l. c. <span dir=\"rtl\">דאתי למִמְּשַׁךְ בתרייהו</span> he may be induced to follow them (the heretics). <span class=\"citation\">Snh. 70ᵃ</span> <span dir=\"rtl\">משום אִימְּשׁוּכֵי הוא</span> it is in order to prevent being carried away (led to intemperance); <span dir=\"rtl\">לא מִימְּשִׁיךְ</span> he will not be carried away (it has no attraction for him); <span class=\"citation\">Yalk. Deut. 929</span>. <span class=\"citation\">Sabb. 147ᵇ</span> <span dir=\"rtl\">אי׳ בתרייהו</span> he was drawn after them, he indulged in the luxuries of the place; a. fr.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"משַׁךְ\">preced.</a><i>Nif.</i>) <i>to withdraw</i>. <span class=\"citation\">Pes. 78ᵇ</span> <span dir=\"rtl\">אי מִמְשְׁכֵי הני וכ׳</span> if these should withdraw (from their participation in the Passover sacrifice), it would remain fit for the others.</div></div>","alt":[]},"16869":{"h":"מְשַׁךְ II","r":"M02893","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁךְ I\">preced.</a>) <i>hide, skin</i>. <span class=\"citation\">Targ. O. Num. XXXI, 20</span>. <span class=\"citation\">Targ. Lev. XIII, 8</span> (ed. Berl. <a href=\"#\" data-headword=\"מְשַׁךְ II\">מַשְׁכָּא</a>). <span class=\"citation\">Targ. Y. Gen. III, 14</span> <span dir=\"rtl\">מִשְׁכ׳</span>; a. fr.—Y. Ned. III, 37ᵈ bot. <span dir=\"rtl\">משך דחיוי</span> the hide of a serpent. <span class=\"citation\">B. Kam. 66ᵇ</span>, v. <a href=\"#\" data-headword=\"*אֲבִרְזִין\">אֲבִרְזִין</a>. Tanḥ. <span class=\"citation\">B’resh. 7</span> <span dir=\"rtl\">הדין ערקא מן הדין מ׳</span> such a strap from such a hide (such poor work with such good material)!; a. fr.—Pl. <a href=\"#\" data-headword=\"מַשְׁכֵּין\">מַשְׁכִין</a>, <span dir=\"rtl\">מַשְׁכֵי</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>, <a href=\"#\" data-headword=\"מִתְנָא\">מוֹ׳</a>. <span class=\"citation\">Targ. Ex. XXVI, 14</span>. <span class=\"citation\">Targ. Gen. XXVII, 16</span>; a. fr.</div>","alt":["מַשְׁכָא","מִישְׁ׳","מוֹשְׁ׳"]},"16870":{"h":"מְשָׁכָא","r":"M02894","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשָׁאכָה\">מְשָאכָה</a></div>","alt":["בֵּי מְ׳"]},"16871":{"h":"מִשְׁכָּב","r":"M02895","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>couch, bed; grave</i>. <span class=\"citation\">Kidd. 31ᵇ</span> <span dir=\"rtl\">כפרת מִשְׁכָּבוֹ</span>, v. <a href=\"#\" data-headword=\"כַּפָּרָה\">כַּפָּרָה</a>. <span class=\"citation\">Keth. 104ᵃ</span>; a. fr.—Esp. <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (<span dir=\"rtl\">טומאת</span>) <i>the uncleanness caused by an unclean person lying on an object</i>, v. <a href=\"#\" data-headword=\"מוֹשָׁב\">מוֹשָׁב</a>. <span class=\"citation\">Kel. I, 3</span>; a. fr.—Pl. <span dir=\"rtl\">מִשְׁכָּבוֹת</span>. Keth. l. c. <span class=\"citation\">Midr. Till. to Ps. CXLIX</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>sexual connection</i>. <span class=\"citation\">Snh. 55ᵃ</span>; a. fr.—<span dir=\"rtl\">מִשְׁכַּב זכור</span> (<span dir=\"rtl\">זכר</span>) <i>pederasty</i>. <span class=\"citation\">Succ. 29ᵃ</span>; a. fr.—Pl. as ab. Snh. l. c. <span dir=\"rtl\">שני מ׳</span> two ways (the natural and the unnatural way) of sexual gratification. Ib. 54ᵃ</div>","alt":[]},"16872":{"h":"מַשְׁכְּבָא","r":"M02896","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XV, 4</span>; a. fr.—<span class=\"citation\">Ber. 56ᵇ</span> <span dir=\"rtl\">מ׳ הפוך</span> (Ms. M. <span dir=\"rtl\">משכבו</span> h.) (his) couch will be upset (his domestic life disturbed).—Pl. constr. <span dir=\"rtl\">מִשְׁכְּבֵי</span>. <span class=\"citation\">Targ. O. Gen. XLIX, 4</span>. <span class=\"citation\">Targ. Num. XXXI, 17</span>; a. fr.</div>","alt":["מִשְׁ׳"]},"16873":{"h":"משכובית","r":"M02897","html":"<div class=\"sense\">, v. next wds.</div>","alt":["משכוביתא"]},"16874":{"h":"מַשְׁכּוֹכִית","r":"M02898","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁךְ I\">מָשַׁךְ</a>) <i>the shepherd’s leading implements</i>, as <i>staff, bell</i> &amp;c.; trnsf. <i>the bell-wether, leader</i>. <span class=\"citation\">B. Kam. 52ᵃ</span> <span dir=\"rtl\">המוכר … כיון שמסר לו מ׳ קנה</span> ed. (Ms. M. <span dir=\"rtl\">משכוב׳</span>; Alf. ed. <span dir=\"rtl\">משכונ׳</span>, Ms. <span dir=\"rtl\">משכוכ׳</span>, v. Rabb. D. S. a. l. note) as soon as he delivers the <i>mashkokhith</i>, the sale is perfected. Ib. <span dir=\"rtl\">מאי מ׳ הכא וכ׳</span> what is <i>m?</i> Here (in Babylonia) they explain it, ‘the bell’. R. J. says, ‘the goat that leads the herd’; <span class=\"citation\">Y. Kidd. I, 60ᵇ</span> top, expl. ‘the staff’, ‘the pipe’, ‘the lender’; Y. B. Bath. III, beg. 13ᵈ, v. <a href=\"#\" data-headword=\"פַּנְדּוּרָה\">פַּנְדּוּרָה</a>.</div>","alt":[]},"16875":{"h":"מַשְׁכּוֹכִיתָא","r":"M02899","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"מַשְׁכּוֹכִית\">preced.</a>), <span dir=\"rtl\">ענא מ׳</span> <i>the leading flock</i>. <span class=\"citation\">Targ. Y. Gen. XXX, 40</span> (ed. <span dir=\"rtl\">משכוב׳</span>, corr. acc.; h. text <span dir=\"rtl\">פני הצאן</span>).</div>","alt":[]},"16876":{"h":"מַשְׁכּוֹן","r":"M02900","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁכַן\">שָׁכַן</a>) <i>security, pledge</i>. <span class=\"citation\">B. Mets. VI, 7</span> <span dir=\"rtl\">הלוהו על המ׳</span> if one loaned on a pledge. Ib. <span dir=\"rtl\">מותר … מַשְׁכּוֹנוֹ וכ׳</span> man is permitted to hire out the poor man’s pledge (for the debtor’s benefit). Ib. 82ᵃ (in Chald. dict.) <span dir=\"rtl\">בדלא שוי מ׳ וכ׳</span> when the pawn is not worth the money loaned on it. Ib. <span dir=\"rtl\">בעל חוב קונה מ׳</span> the creditor owns the pledge (for the time being, and is reponsible for it); a. fr.—<span class=\"citation\">Ex. R. s. 31</span> <span dir=\"rtl\">אל תהא קורא מִשְׁכָּנִי אלא מַשְׁכּוֹנִי</span> read not (<span class=\"citation\">Lev. XXVI, 11</span>) ‘my dwelling’ but ‘my pledge’. <span class=\"citation\">Ex. R. s. 35</span> (play on <span dir=\"rtl\">למשכן</span>, <span class=\"citation\">Ex. XXVI, 15</span>) <span dir=\"rtl\">שהוא עומד למַשְׁכָּן וכ׳</span> the sanctuary stands as a pledge, when the Israelites deserve destruction, it is seized on their account.—Pl. <span dir=\"rtl\">משְׁכּוֹנוֹת</span>, <span dir=\"rtl\">מַשְׁכָּנוֹת</span>. Ib. s. 31 (ref. to <span dir=\"rtl\">משכנתיך</span>, <span class=\"citation\">Num. XXIV, 5</span>) <span dir=\"rtl\">שני מ׳</span> two pledges (the First and the Second Temple); <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">אל תהי קורא מִשְׁכְּנוֹתֶיךָ אלא מַשְׁכְּנוֹתֶיךָ</span> read not thy dwellings &amp;c. (v. supra); Tanḥ. Naso 14. Ex. R. l. c. (with ref. to <span class=\"citation\">Ex. XXII, 25</span>), cmp. <a href=\"#\" data-headword=\"חֲבוֹלָה\">חֲבוֹלָה</a>; a. fr.</div>","alt":[]},"16877":{"h":"מַשְׁכּוֹן ²","r":"M02901","html":"<div class=\"sense\">, <i>pledge, seized goods</i>. <span class=\"citation\">Targ. Am. II, 8</span>. <span class=\"citation\">Targ. Gen. XXXVIII, 17</span>; a. fr.—<span class=\"citation\">Gen. R. s. 70</span> <span dir=\"rtl\">הבו לי מ׳ דלית וכ׳</span> (<span class=\"citation\">Yalk. ib. 125</span> <span dir=\"rtl\">משכונין</span>) give me a pledge that none of you will divulge it; a. e.—Pl. <a href=\"#\" data-headword=\"מַשְׁכּוֹן ²\">מַשְׁכּוֹנַיָּא</a>, <span dir=\"rtl\">מַשְׁכּוֹנִין</span>, <a href=\"#\" data-headword=\"מְשַׁךְ II\">מִישְׁ׳</a>. <span class=\"citation\">Targ. Y. Gen. XXXVIII, 25</span> (not … <a href=\"#\" data-headword=\"*נִיא\">נְיָא</a>).—Gen. R. l. c.—Y. Pes. IV, 31ᵇ bot. <span dir=\"rtl\">והוון בניהון מי׳ גבן</span> and their children were placed as pledges with them (for military levies).</div>","alt":["מַשְׁכּוֹנָא"]},"16878":{"h":"מַשְׁכִּילְתָּא","r":"M02902","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשִׁיכְלָא\">מְשִׁיכְלָא</a></div>","alt":[]},"16879":{"h":"מַשְׁכֵּין","r":"M02903","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁכֵּן\">מַשְׁכֵּן</a>.—[<span class=\"citation\">Y. Yeb. VIII, 9ᵇ</span> top <span dir=\"rtl\">נימולין ומ׳</span>, read: <span dir=\"rtl\">ומַשִּׁיכָן</span>, v. <a href=\"#\" data-headword=\"נָשַךְ\">נָשַׁךְ</a>.]</div>","alt":[]},"16880":{"h":"מַשְׁכָּן","r":"M02904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">מַשְׁכּוֹן</a></div>","alt":["מַשְׁכֹּן"]},"16881":{"h":"מִשְׁכֵּן","r":"M02905","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">מַשְׁכּוֹן</a>) <i>to take a pledge; to seize, levy</i>. <span class=\"citation\">B. Mets. 81ᵇ</span> <span dir=\"rtl\">מִשְׁכְּנוֹ בשעת הלואתו</span> he made him give a pledge at the time when the loan was transacted; <span dir=\"rtl\">מ׳ שלא בשעת וכ׳</span> he seized it (through court proceedings) after the transaction of the loan. Ib. 113ᵇ <span dir=\"rtl\">שליח ב&quot;ד שבא למַשְׁכְּנוֹ</span> when the court messenger comes to seize his goods. <span class=\"citation\">Shek. I, 3</span> <span dir=\"rtl\">את מי מְמַשְׁכְּנִין</span> against whom was seizure (for the contribution of the half-Shekel) executed?—Y. ib. II, beg. 46ᶜ <span dir=\"rtl\">מכיון שב&quot;ד ראויין למַשְכֵּן ולא מִישְׁכְּנוּ</span> since the court had a right to seize and did not do so (because the claim was satisfied with another man’s money). <span class=\"citation\">Cant. R. to I, 4</span> (play on <span dir=\"rtl\">משכני</span>, ib.) <span dir=\"rtl\">מַשְׁכֵּינְנִי אחריך נרוצה</span> execute levy against me (take my sanctuary, v. <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">מַשְׁכּוֹן</a>), yet after thee we run. <span class=\"citation\">Ex. R. s. 35</span> אני נוטל … ומְמַשְׁכְּנוֹ בעדם I take a righteous man from them and seize him for their guilt; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מאושבן\">מְמוּשְׁכָּן</a>; pl. <span dir=\"rtl\">מְמוּשְׁכָּנִים</span>, <span dir=\"rtl\">מְמוּשְׁכָּנִין</span>. Y. Shek. l. c. <span dir=\"rtl\">אין תורמין … ולא על הממ׳</span> in distributing the Temple contributions we do not take into account that which is being collected (and has not yet come in) or that which is to be obtained by seizure. <span class=\"citation\">Peah VIII, 8</span>. <span class=\"citation\">B. Mets. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"מַשְׁכֵּן\">next w.</a>; a. e.</div><div class=\"sense\"><b>Hithpa. הִתְמַשְׁכֵּן</b> </div><div class=\"sense\"><b>Nithpa. נִתְמַשְׁכֵּן</b> <div class=\"sense\"><i>to be seized</i>. <span class=\"citation\">Ex. R. s. 51</span>, beg. <span dir=\"rtl\">שנ׳ שתי פעמים וכ׳</span> it (the sanctuary) was twice seized for their sins, v. <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">מַשְׁכּוֹן</a>. <span class=\"citation\">Ex. R. s. 35</span>; Tanḥ. Vayakh. 9 <span dir=\"rtl\">יהא המשכן מִתְמַשְׁכֵּן עליהם</span>, v. <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">מַשְׁכּוֹן</a>. Ib. <span dir=\"rtl\">ויהיו מִתְמַשְׁכְּנִין וכ׳</span> and they (the righteous) will be seized &amp;c. <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">המשכן והמקדש יִתְמַשְׁכְּנוּ וכ׳</span> the Tabernacle and the Temple shall be seized &amp;c.; a. fr.</div></div>","alt":[]},"16882":{"h":"מַשְׁכֵּן","r":"M02906","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XXII, 25</span>. <span class=\"citation\">Targ. Job XXIV, 3</span>; a. fr.—<span class=\"citation\">B. Mets. 68ᵃ</span> <span dir=\"rtl\">מ׳ ליה פלניא וכ׳</span> (not <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">משכון</a>) A pledged his field to B, and then rented it from him. <span class=\"citation\">Ib. 73ᵇ</span> top <span dir=\"rtl\">ר׳ מרי … מ׳ ליה וכ׳</span> a gentile gave his house (for occupation) as a pledge, and then sold it to &amp;c. <span class=\"citation\">Ib. 113ᵃ</span> אבל מַשְׁכּוּנֵי לא Ms. M. (ed. <span dir=\"rtl\">מַשְׁכְּנוֹ</span>) but to take a pledge out of his house he (the messenger of the court) is not permitted; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מַשְׁכָּן\">מְמַשְׁכַּן</a>, f. <a href=\"#\" data-headword=\"מַשְׁכְּנָא\">מְמַשְׁכְּנָא</a>. <span class=\"citation\">Koh. R. to III, 2</span>, v. <a href=\"#\" data-headword=\"מְחַבַּלְתָּא\">מְחַבַּלְתָּא</a>. <span class=\"citation\">B. Mets. 73ᵇ</span> אי הוה ידענא דממשכן וכ׳ Ms. F. (Ms. M. <span dir=\"rtl\">דמשכן</span>, corr. acc.; ed. <span dir=\"rtl\">דהוה ממוּשְׁכָּן</span>) if I had known that the house was pledged to you. Y. ib. VIII, end, 11ᵈ <span dir=\"rtl\">ביתיה הוות מְמַשְׁכְּנָה וכ׳</span> his house was pledged to &amp;c.; a. e.</div><div class=\"sense\"><b>Ithpa. אִתְמַשְׁכֵּן</b> <div class=\"sense\"><i>to be given as a pledge; to be levied upon; to borrow on pledge</i>. <span class=\"citation\">Targ. II Chr. XXV, 24</span> (h. text <span dir=\"rtl\">תערבות</span>). <span class=\"citation\">Targ. Y. Deut. XV, 6</span>; a. e.</div></div>","alt":["מַשְׁכֵּין"]},"16883":{"h":"מִשְׁכָּן","r":"M02907","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>dwelling,</i> esp. <i>the sanctuary of the desert, the Tabernacle</i>. <span class=\"citation\">Erub. 2ᵃ</span>, v. <a href=\"#\" data-headword=\"מִקְדָּשׁ\">מִקְדָּשׁ</a>. <span class=\"citation\">Num. R. s. 12</span>; a. v. fr.—Pl. <span dir=\"rtl\">מִשְׁכָּנוֹת</span>. Ib.; a. fr.</div>","alt":[]},"16884":{"h":"מַשְׁכְּנָא","r":"M02908","html":"<div class=\"sense\">, <i>dwelling, tent</i>. <span class=\"citation\">Targ. Job XVIII, 14</span>.—Esp. <i>the Tabernacle</i>. <span class=\"citation\">Targ. Ex. XXV, 9</span>; a. fr.—Pl. <span dir=\"rtl\">מַשְׁכְּנִין</span>, <span dir=\"rtl\">מַשְׁכְּנַיָּא</span>, <a href=\"#\" data-headword=\"מַדַּע\">מִ׳</a>. <span class=\"citation\">Targ. Gen. IV, 20</span>. <span class=\"citation\">Targ. Ps. CXXXII, 5</span>. <span class=\"citation\">Ib. LXXXIV, 2</span>; a. fr.</div>","alt":["מִ׳"]},"16885":{"h":"מִשְׁכְּנוּתָא","r":"M02909","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַשְׁכַּנְתָּא\">next w.</a>) <i>pledged property, occupancy subject to redemption at the original owner’s will</i>. <span class=\"citation\">Cant. R. to I, 4</span> (play on <span dir=\"rtl\">משכני</span>, ib.) <span dir=\"rtl\">לארעא טבתא דאתקריאת מ׳</span> to the good land which is called a tenancy (cmp. <span class=\"citation\">Lev. XXV, 23</span>); Yalk. ib. 981 <a href=\"#\" data-headword=\"מַשְׁכַּנְתָּא\">מַשְׁכַּנְתָּא</a>.</div>","alt":["מִישְׁ׳"]},"16886":{"h":"מַשְׁכַּנְתָּא","r":"M02910","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַשְׁכּוֹן\">מַשְׁכּוֹן</a>) <i>a loan transaction whereby landed property is transferred to the creditor with the privilege of redemption by returning the loan</i> (v. Sm. Ant. s. v. Pignus). [The particular conditions of the <a href=\"#\" data-headword=\"מ׳\">מ׳</a> depend on local usages.] <span class=\"citation\">B. Mets. 67ᵃ</span> <span dir=\"rtl\">הא מ׳ באתרא דמסלקי וכ׳</span> as to the settlement of a <i>mashkanta</i>, where the usage allows the debtor to repay the loan at any time, he may reclaim his property as soon as the value of the creditor’s usufruct has reached the amount of the loan, but if the usufruct amounts to more, the balance cannot be claimed. <span class=\"citation\">Ib. 67ᵇ</span> top, v. <a href=\"#\" data-headword=\"נַכְיָיתָא\">נַכְיָיתָא</a>. <span class=\"citation\">Ib. 68ᵃ</span> <span dir=\"rtl\">סתם מ׳ שתא</span> a <i>m</i>. without a fixed term for redemption is meant for a year (during which the occupant cannot be disturbed). <span class=\"citation\">Ib. 110ᵃ</span>, a. e. <span dir=\"rtl\">מ׳ דסורא וכ׳</span> the agreement of a <i>m</i>. customary in Sura, in which it is written, ‘After the lapse of so and so many years, the property shall go back without payment’. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שטרא דמ׳</span> the document of a <i>m</i>.; a. e.—<span class=\"citation\">Yalk. Cant. 981</span>, v. <a href=\"#\" data-headword=\"מִשְׁכְּנוּתָא\">preced.</a></div>","alt":[]},"16887":{"h":"מָשַׁל I","r":"M02911","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to handle, to touch</i>. <span class=\"citation\">Yoma 46ᵃ</span> <span dir=\"rtl\">מָשְׁלָה בהן האור</span> the flames had attacked them.</div><div class=\"sense\"><b>—2)</b> <i>to attend, manage, control</i>. <span class=\"citation\">B. Mets. 75ᵇ</span> <span dir=\"rtl\">מי שאשתו מוֹשֶׁלֶת עליו</span> he whom his wife rules. <span class=\"citation\">Ḥull. 60ᵇ</span> <span dir=\"rtl\">לכי ומְשׁוֹלִי ביום וכ׳</span> (not <span dir=\"rtl\">ומשול</span>; Rashi <span dir=\"rtl\">לך ומְשׁוֹל</span>) go thou and attend by day and by night.—<span class=\"citation\">B. Bath. 78ᵇ</span> (ref. to <span class=\"citation\">Num. XXI, 27</span>) <span dir=\"rtl\">המוֹשְׁלִים ביצרם</span> who control their inclinations; a. e.—מוֹשֵׁל <i>governor, consul.</i> <span class=\"citation\">Yad. IV, 8</span> <span dir=\"rtl\">אתם כותבים את המושל וכ׳</span> you write the governor’s name and year together with the name of Moses in a document. [<span class=\"citation\">B. Kam. 38ᵃ</span> <span dir=\"rtl\">מוֹשְׁלֵי</span>, <span dir=\"rtl\">מוֹשְׁלִים</span>, censorial emendations for <a href=\"#\" data-headword=\"מַלְכוּת\">מַלְכוּת</a>, v. Rabb. D. S. a. l. notes.]</div><div class=\"sense\"><b>Pi. מִשֵּׁל</b> <div class=\"sense\"><i>to handle, dispose of, use</i>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">יכול מְמַשְּׁלָהּ מכל צד</span> you might think, he may use her in whatever way he pleases; <span class=\"citation\">Yalk. ib. 32</span>.</div></div><div class=\"sense\"><b>Hif. הִמְשִׁיל</b> <div class=\"sense\"><i>to make a ruler</i>. <span class=\"citation\">Sot. 36ᵇ</span> <span dir=\"rtl\">עבד … תַּמְשִׁילֵהוּ עלינו</span> a slave whom his master bought for twenty pieces of silver,—wilt thou make him a ruler over us?; a. e.</div></div>","alt":[]},"16888":{"h":"מָשַׁל II","r":"M02912","html":"<div class=\"sense\"> denom. of <a href=\"#\" data-headword=\"מָשָׁל\">next w.</a>) </div><div class=\"sense\"><b>1)</b> <i>to speak metaphorically</i>. <span class=\"citation\">Nidd. V, 7</span> <span dir=\"rtl\">מָשָׁל מָשְׁלוּ וכ׳</span> the scholars introduced metaphors for designating the stages of female puberty.</div><div class=\"sense\"><b>—2)</b> <i>to compare, to give an illustration</i>. <span class=\"citation\">Tosef. Ber. I, 11</span> <span dir=\"rtl\">משלו משל למה וכ׳</span> they made a comparison: what is this to be compared to? To &amp;c. <span class=\"citation\">R. Hash. 17ᵇ</span> <span dir=\"rtl\">אֶמְשׁוֹל לך משל למה וכ׳</span> let me tell thee a parable: what is this like to? To &amp;c. <span class=\"citation\">Cant. R. to II, 15</span> <span dir=\"rtl\">כשחוא מוֹשֵׁל את המלכיות אינו מוֹשְׁלָן אלא באש</span> when one wants to find a simile for hostile governments, one compares them to fire; a. v. fr.—Part. pass. <span dir=\"rtl\">מָשׁוּל</span>; f. <span dir=\"rtl\">מְשׁוּלָה</span>; pl. <span dir=\"rtl\">מְשׁוּלִים</span>, <span dir=\"rtl\">מְשׁוּלִין</span>; <span dir=\"rtl\">מְשׁוּלוֹת</span>. <span class=\"citation\">Meg. 16ᵃ</span> <span dir=\"rtl\">אומה זו מ׳ לעפר ומ׳ וכ׳</span> that nation (Israel) is compared now to dust and now to the stars; a. v. fr.</div><div class=\"sense\"><b>Nif. נִמְשַׁל</b> <div class=\"sense\"><i>to be compared</i> (followed by <span dir=\"rtl\">ל־</span>, <span dir=\"rtl\">כ־</span> or <a href=\"#\" data-headword=\"ב\">ב־</a>). <span class=\"citation\">Taan. 7ᵃ</span> נִמְשְׁלוּ דברי תורה לאש Ms. M. (ed. <span dir=\"rtl\">כאש</span>, <span dir=\"rtl\">באש</span>. v. Rabb. D. S. a. l. note) the words of the Law are compared to fire. <span class=\"citation\">Gen. R. s. 41</span> <span dir=\"rtl\">התורה שנִמְשְׁלָה למים</span> the Law which is compared to water; a. v. fr.</div></div>","alt":[]},"16889":{"h":"מָשָׁל","r":"M02913","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מָשַׁל I\"><span dir=\"rtl\">מָשַׁל</span> I</a>) [<i>something tangible, substantial, plausible</i>; cmp. <a href=\"#\" data-headword=\"אֲמַתְלָא\">אֲמַתְלָא</a>,] <i>a truth substantiated by an illustration, wise saying; fable, allegory; example; mashal</i>. Cant. R. introd. <span dir=\"rtl\">אל יהי המ׳ הזח קל וכ׳</span> do not esteem the <i>mashal</i> lightly, for through it man gets at the basis of &amp;c. Ib. <span dir=\"rtl\">יש לו מקרא ויש לו מ׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"מְלִיצָה\">מְלִיצָה</a>. <span class=\"citation\">Ex. R. s. 40</span>, beg. <span dir=\"rtl\">צריך אדם לחיות נוטל מ׳</span> man should take an example (of the Lord). <span class=\"citation\">Pes. 49ᵃ</span> bot. <span dir=\"rtl\">מ׳ לענבי וכ׳</span> it is like mixing grapes with &amp;c.—<span dir=\"rtl\">מ׳ למה הדבר דומה</span>, v. <a href=\"#\" data-headword=\"דָּמָה\">דָּמָה</a> a. preced.—<span class=\"citation\">B. Bath. 15ᵃ</span> <span dir=\"rtl\">איוב לא היה … אלא מ׳ היה</span> the story of Job never occurred, but was invented merely as a parable. <span class=\"citation\">Snh. 92ᵇ</span> <span dir=\"rtl\">אמת מ׳ היה</span> (the vision of the valley of the dead) was the truth of a <i>mashal</i>, (emended:) <span dir=\"rtl\">באמת מ׳ היה</span> in the truth (the fact of resurrection) there was a symbol (for the redemption of Israel from captivity; <span class=\"citation\">Ez. XXXVII, 11</span>).—<span class=\"citation\">Y. Keth. IV, 28ᶜ</span> top; <span class=\"citation\">Y. Snh. VIII, 26ᶜ</span> top <span dir=\"rtl\">זה … שנאמרו בתורה במ׳</span> this is one of the three verses in which the Law uses metaphorical expressions (<span class=\"citation\">Ex. XXI, 19</span>; <span class=\"citation\">XXII, 2</span>; <span class=\"citation\">Deut. XXII, 17</span>); Mekh. Mishp. 6; a. fr.—Pl. <span dir=\"rtl\">מְשָׁלִים</span>, <span dir=\"rtl\">מְשָׁלוֹת</span>. <span class=\"citation\">Sot. IX, 15</span> (<span class=\"citation\">49ᵃ</span>) <span dir=\"rtl\">משמת ר&quot;מ בטלו מושלי מ׳</span> with the death of R. M. ceased the composers of fables. Cant. R. l. c. <span dir=\"rtl\">מִשְׁלוֹתָיו של וכ׳</span> the wise sayings of Solomon. Ib. <span dir=\"rtl\">דברי מ׳</span> didactic literature, opp. <span dir=\"rtl\">זמר</span>. Ib. <span dir=\"rtl\">שלש מ׳</span> three collections of sayings (<span class=\"citation\">Prov. I</span> to IX; <span class=\"citation\">X</span> to XXIV; <span class=\"citation\">XXV</span> to XXXI). <span class=\"citation\">Num. R. s. 14</span>, end <span dir=\"rtl\">ועם בלעם … כי אם במ׳</span> God spoke to Balaam only through allegories (visions).—<span class=\"citation\">Succ. 28ᵃ</span> <span dir=\"rtl\">מִשְׁלוֹת שועלין</span> (Ms. M. <span dir=\"rtl\">מִמְשְׁלוֹת</span>, v. Rabb. D. S. a. l. note) fox-fables; <span dir=\"rtl\">מ׳ כובסין</span> washers’ fables; <span class=\"citation\">B. Bath. 134ᵃ</span>. <span class=\"citation\">Snh. 38ᵇ</span> (Ms. M. <span dir=\"rtl\">ממשלת</span>); <span class=\"citation\">Yalk. Prov. 947</span>.—<span class=\"citation\">Gitt. 35ᵃ</span> bot. <span dir=\"rtl\">ספר איוב ומִמְשָׁלוֹת</span> copies of the Books of Job and <i>Proverbs</i> (v. infra).—<a href=\"#\" data-headword=\"מִשְׁלֵי\">מִשְׁלֵי</a> (sub. <span dir=\"rtl\">שלמה</span>) <i>Mishlé, the Book of Proverbs</i> (commencing with the word <i>mishlé</i>). Cant. R. l. c. <span class=\"citation\">B. Bath. 14ᵇ</span>. <span class=\"citation\">Y. Yoma I, end, 39ᵇ</span>; a. e.</div>","alt":[]},"16890":{"h":"מְשַׁלְהֵי","r":"M02914","html":"<div class=\"sense\"><i>tired,</i> v. <a href=\"#\" data-headword=\"שַׁלְהֵי I\">שַׁלְהֵי</a>.</div>","alt":[]},"16891":{"h":"מִשְׁלַחַת","r":"M02915","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>errand, message; substitution</i>. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">והיה זריז במִשְׁלַחְתּוֹ</span> and he (Naftali) was zealous in carrying out his mission. <span class=\"citation\">Koh. R. to VIII, 8</span>. (expl. <a href=\"#\" data-headword=\"מִשְׁלַחַת\">משלחת</a>, ib.) <span dir=\"rtl\">אין אדם וכ׳</span> (‘there is no substitution in war’,) none can say to the angel of death, let my slave or an inmate of my house go in my place.</div><div class=\"sense\"><b>—2)</b> <i>letting loose</i> (by divine dispensation), <i>visitation</i> (of wild beasts). <span class=\"citation\">B. Mets. VII, 9</span>; a. e., v. <a href=\"#\" data-headword=\"זְאֵב\">זְאֵב</a>.</div>","alt":[]},"16892":{"h":"מִשְׁלֵי","r":"M02916","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָשָׁל\">מָשָׁל</a></div>","alt":[]},"16893":{"h":"מְשִׁלְיָא","r":"M02917","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שְׁלֵי I) <i>fork</i>. <span class=\"citation\">Targ. I Sam. II, 13</span>, sq. (ed. Wil. <a href=\"#\" data-headword=\"מְשִׁילְיָא\">מַשִׁילַיָא</a>).—Pl. <span dir=\"rtl\">מְשִׁלְיָיתָא</span>, <span dir=\"rtl\">מְשִׁלְיָתָא</span>, <span dir=\"rtl\">מְשִׁי׳</span>. <span class=\"citation\">Targ. I Chr. XXVIII, 17</span>. <span class=\"citation\">Targ. Y. Ex. XXVII, 3</span> (some ed. <span dir=\"rtl\">מַ׳</span>).—[<span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 3</span>, v. next w.]</div>","alt":["מְשִׁילְיָא"]},"16894":{"h":"מַשְׁלִית","r":"M02918","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשִׁלְיָא\">preced.</a>) <i>a tool for lifting objects out of a well, lifter</i>. <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 3</span> (some ed. <a href=\"#\" data-headword=\"מְשִׁלְיָא\">משליא</a>, corr. acc.).</div>","alt":[]},"16895":{"h":"מִשְׁלָם","r":"M02919","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁלָם\">שְׁלַם</a>) <i>completion, end</i>. <span class=\"citation\">Targ. Job I, 4</span>.—<span class=\"citation\">B. Mets. 67ᵇ</span>, a. e. <span dir=\"rtl\">במִשְׁלַם שניא אילין</span> after the lapse of so and so many years, v. <a href=\"#\" data-headword=\"מַשְׁכַּנְתָּא\">מַשְׁכַּנְתָּא</a>.</div>","alt":["מִי׳"]},"16896":{"h":"משמדות","r":"M02920","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשׁוּמָּדוּת\">מְשׁוּמָּדוּת</a></div>","alt":[]},"16897":{"h":"מָשְׁמָהִיג","r":"M02921","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Mashmahig</i> (P. Sm. 2245), a place on an island of the Persian Gulf.—<span dir=\"rtl\">פרוותא דמ׳</span> the port of M., mentioned for its pearl fisheries. <span class=\"citation\">R. Hash. 23ᵃ</span>. <span class=\"citation\">Yoma 77ᵃ</span> (in a passage omitted in many editions) <span dir=\"rtl\">פ׳ דמ׳</span> (ed. cited in Rabb. D. S. a. l. <a href=\"#\" data-headword=\"משהיג\">משהיג</a>, Ms. O. <span dir=\"rtl\">משנהיג</span>).</div>","alt":[]},"16898":{"h":"מַשְׁמוֹטָא","r":"M02922","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁמַט\">שְׁמַט</a>) <i>a sneak thief</i>, opp. to <a href=\"#\" data-headword=\"לִסְטִין\">לסטיס</a>. <span class=\"citation\">Ab. Zar. 15ᵇ</span> <span dir=\"rtl\">במ׳ דזימנין וכ׳</span> (Ms. M. <span dir=\"rtl\">במשמיטא בעלמא</span>, Rashi <span dir=\"rtl\">במשמוטי׳</span>) it refers to an (ordinary) thief who sometimes commits murder to save his own life.</div>","alt":[]},"16899":{"h":"מִשְׁמוּשׁ","r":"M02923","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִשְׁמֵשׁ\">מִשְׁמֵשׁ</a>) <i>touch</i>. <span class=\"citation\">Gen. R. s. 52</span> <span dir=\"rtl\">מ׳ ידים</span> an illicit touch (of her) with his hand. <span class=\"citation\">Midr. Till. to Ps. VIII, 4</span> [read:] <span dir=\"rtl\">העליונים … אלא מ׳ אצבעותיך</span> (ed. Bub. <a href=\"#\" data-headword=\"מַעֲשֶׂה\">מעשה</a>, corr. acc.) those above (the angels) and those below have only (as much power as) the touch of thy fingers; <span class=\"citation\">Midr. Till. to Ps. XIX</span> <span dir=\"rtl\">כדי מ׳ אצבעו</span> ed. Bub. (ed. <span dir=\"rtl\">כדי אצבעו</span>, corr. acc.); <span class=\"citation\">Yalk. Ps. 640</span>.—[<span class=\"citation\">Y. Ber. III, 6ᵈ</span> bot., v. <a href=\"#\" data-headword=\"מַשְׁמָשׁ\">מַשְׁמָשׁ</a>.]</div>","alt":[]},"16900":{"h":"מִשְׁמָע","r":"M02924","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>obedience</i>. <span class=\"citation\">Sifré Deut. 357</span> ref. to <span class=\"citation\">Deut. XXXIV, 9</span>) <span dir=\"rtl\">אין לך מ׳ גדול וכ׳</span> there can be no obedience greater than this.</div><div class=\"sense\"><b>—2)</b> <i>ordinary sense</i>.—כְּמִשְׁמָעוֹ <i>in its usual sense</i>. <span class=\"citation\">Yoma 61ᵃ</span> מזבח כמ׳ ‘altar’ in its usual sense (requires no explanation); <span dir=\"rtl\">הכהנים כְּמִשְׁמָעָן</span> ‘the priests’ &amp;c.; a. fr.</div>","alt":[]},"16901":{"h":"מַשְׁמָע","r":"M02925","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שָׁמַע <i>Hif.</i>) <i>intimation, logical conclusion</i>. <span class=\"citation\">Yoma 42ᵇ</span>, v. <a href=\"#\" data-headword=\"מֵילָא II\"><span dir=\"rtl\">מֵילָא</span> II</a>.—Esp. <span dir=\"rtl\">מִמַּשְׁמַע</span> <i>by implication, constructively</i>. <span class=\"citation\">Y. Erub. III, 21ᵇ</span> top; <span class=\"citation\">Y. Ned. I, end, 37ᵃ</span>, v. <a href=\"#\" data-headword=\"הֵן\">הֵן</a>.—<span dir=\"rtl\">ממ׳ שנאמר … איני יודע וכ׳</span> by mere logical conclusion from the text …, would I not learn that &amp;c.? <span class=\"citation\">B. Bath. 110ᵃ</span> <span dir=\"rtl\">ממ׳ שנאמר וכ׳</span> when the text says ‘the daughter of Amminadab’, do I not know that she is the sister of N.? <span class=\"citation\">B. Mets. 113ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">מַשְׁמָעוֹת</span>. Y. Yoma V, 43ᵃ top <span dir=\"rtl\">מ׳ ביניהון</span> they differ only as to the grammatical construction of the text (without any difference in the law of the case).—<span dir=\"rtl\">מַשְׁמְעוֹת דורשין איכא בינייהו</span> they differ only as to the texts from which the law is derived. <span class=\"citation\">B. Mets. 27ᵃ</span>; <span class=\"citation\">Snh. 76ᵇ</span>; a. fr.</div>","alt":[]},"16902":{"h":"מַשְׁמַע","r":"M02926","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"שְׁמַע I\"><span dir=\"rtl\">שְׁמַע</span> I</a></div>","alt":[]},"16903":{"h":"מִשְׁמְעָא","r":"M02927","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (שְׁמַע I) <i>hearing</i>. <span class=\"citation\">Targ. Job XLII, 5</span>. <span class=\"citation\">Targ. Y. I Gen. XLIV, 18</span> (Y. II some ed. <span dir=\"rtl\">מִשְׁמָעְייה</span>); a. fr.</div>","alt":["(מִשְׁמָעְיָא)"]},"16904":{"h":"מִשְׁמַעְתָּא","r":"M02928","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִשְׁמְעָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  (= b. h. <span dir=\"rtl\">מִשְׁמַעַת</span>) <i>following, suite</i>. <span class=\"citation\">Targ. I Sam. XXII, 14</span>. <span class=\"citation\">Targ. II Sam. XXIII, 23</span>.</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"שְׁמַעְתָּא\">שְׁמַעְתָּא</a>) <i>tradition</i>. <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">דלביה כמִשְׁמַעְתֵּיה</span> whose own opinion agrees with his tradition (Var. <span dir=\"rtl\">דעביד כשמעתיה</span>).</div>","alt":[]},"16905":{"h":"משמר","r":"M02929","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebi. IV, 35ᵃ</span> bot., v. <a href=\"#\" data-headword=\"*הָאַסְטוּ\">הָאַסְטוּ</a></div>","alt":[]},"16906":{"h":"מִשְׁמָר","r":"M02930","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>guard</i>, esp. <i>a division for duty of priests and Levites.</i> <span class=\"citation\">Taan. IV, 2</span>, v. <a href=\"#\" data-headword=\"מַעֲמָד\">מַעֲמָד</a>. <span class=\"citation\">Hor. 13ᵃ</span> <span dir=\"rtl\">ראש מ׳</span> chief of the guard. Taan. l. c. <span dir=\"rtl\">ישראל שבאותו מ׳</span> the Israelites attached (as <a href=\"#\" data-headword=\"מַעֲמָד\">מַעֲמָד</a>) to that division; a. fr.—Pl. <span dir=\"rtl\">מִשְׁמָרוֹת</span>. Ib. <span class=\"citation\">Num. R. s. 3</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"אַשְׁמוֹרָה\">אַשְׁמוֹרֶת</a>) <i>watch, a certain portion of the day or the night</i>. <span class=\"citation\">Ber. 3ᵃ</span> <span dir=\"rtl\">על כל מ׳ ומ׳</span> at the beginning of every watch.—Pl. as ab. Ib.; <span class=\"citation\">Tosef. ib. I, 1</span> <span dir=\"rtl\">שלש מ׳ בלילה</span> the night is divided into three watches.</div>","alt":[]},"16907":{"h":"מִשְׁמָרָה","r":"M02931","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> as <a href=\"#\" data-headword=\"מִשְׁמָר\">preced.</a> 2, <i>watch</i>. <span class=\"citation\">Ber. 3ᵃ</span> <span dir=\"rtl\">מ׳ ראשונה וכ׳</span> (at the entrance of) the first watch, &amp;c.—Pl. <span dir=\"rtl\">מִשְׁמָרוֹת</span>, v. <a href=\"#\" data-headword=\"מִשְׁמָר\">preced.</a></div>","alt":[]},"16908":{"h":"מִשְׁמֶרֶת","r":"M02932","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מִשְׁמָרָה\">preced.</a>) <i>guard</i>, trnsf. (v. <a href=\"#\" data-headword=\"גֶּדֶר I\">גֶּדֶר</a>) <i>preventive measure</i>. <span class=\"citation\">M. Kat. 5ᵃ</span>; <span class=\"citation\">Yeb. 21ᵃ</span> (ref. to <span class=\"citation\">Lev. XVIII, 30</span>) <span dir=\"rtl\">עשו מ׳ למִשְׁמַרְתִּי</span> make a guard to my guard, enact measures to prevent a transgression of Biblical laws.</div>","alt":[]},"16909":{"h":"מְשַׁמֶּרֶת","r":"M02933","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (שָׁמַר <i>Pa</i>.) <i>filter, strainer</i>. <span class=\"citation\">Sabb. XX, 1</span> you may suspend (spread out) a strainer &amp;c. <span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> <span dir=\"rtl\">המ׳ של יין</span> a strainer filled with wine; a. fr.—Trnsf. <span class=\"citation\">Ab. V, 15</span> <a href=\"#\" data-headword=\"מ׳\">מ׳</a> a scholar retaining what is useless and discarding the useful knowledge.</div>","alt":[]},"16910":{"h":"מִשְׁמֵשׁ","r":"M02934","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a>, <a href=\"#\" data-headword=\"מָשַׁשׁ\"><a href=\"#\" data-headword=\"מָשַׁשׁ\">מָשַׁשׁ</a>)</a><i>to touch, feel; to handle, manipulate</i>; <i>to examine, search</i>. <span class=\"citation\">B. Mets. 21ᵇ</span> <span dir=\"rtl\">אדם עשוי למַשְׁמֵשׁ בכיסו וכ׳</span> a person (carrying money with him on the road) usually feels for his bag at short intervals. <span class=\"citation\">Men. 36ᵃ</span> <span dir=\"rtl\">מְמַשְׁמֵשׁ בהן</span> he puts his hand on them. <span class=\"citation\">Erub. 54ᵇ</span> top <span dir=\"rtl\">כל זמן שאדם ממשמש בה</span> as often as one searches it (the figtree); <span dir=\"rtl\">כ&quot;ז שהתינוק ממשמש בו</span> as often as the suckling touches the breasts. <span class=\"citation\">Sabb. 82ᵃ</span> <span dir=\"rtl\">יְמַשְׁמֵשׁ בצרור וכ׳</span> let him manipulate (stimulate the rectum) with pebbles. <span class=\"citation\">Erub. 13ᵇ</span> <span dir=\"rtl\">ימשמש במעשיו</span> let him examine what he is doing, contrad. to <span dir=\"rtl\">יפשפש</span> search (investigate) his past doings. <span class=\"citation\">Keth. 12ᵃ</span> <span dir=\"rtl\">למַשְׁמֵשׁ את וכ׳</span> to be around (watch) the bridegroom and bride (in order to prevent deception). <span class=\"citation\">Snh. 63ᵇ</span> <span dir=\"rtl\">מְמַשְׁמְשִׁין בהן</span> they (the famished animals) licked them (begging for food); a. fr.—מ׳ ובא <i>to come gropingly, slowly</i>. <span class=\"citation\">Y. Peah VIII, beg. 20ᵈ</span>, v. <a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a> h.—<span class=\"citation\">Y. Ned. III, 38ᵃ</span> <span dir=\"rtl\">ראה … ממשמשין ובאין</span> if he saw the king’s cutters come near and nearer, v. <a href=\"#\" data-headword=\"קָצוֹעַ\">קָצוֹעַ</a>; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ראה דליקה מְמַשְׁמֶשֶׁת ובאה</span> if he saw the fire coming near and nearer.</div><div class=\"sense\"><b>Pulpel. מוּשְׁמָשׁ</b> <div class=\"sense\"><i>to be attended to, watched</i>. Keth. l. c. <span dir=\"rtl\">כל שלא מ׳</span> when he was not watched.</div></div>","alt":[]},"16911":{"h":"מַשְׁמֵשׁ","r":"M02935","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. LIX, 10</span> (h. text <span dir=\"rtl\">גשש</span>). <span class=\"citation\">Targ. Ps. CXV, 7</span> (h. text <span dir=\"rtl\">ימיש׳</span>); a. fr.—<span class=\"citation\">B. Mets. 21ᵇ</span> <span dir=\"rtl\">מַשְׁמוּשֵׁי מְמַשְׁמֵשׁ בהו</span> he feels for them (to make sure that he has not lost them). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ממשמש בהו</span> he has been looking after the fruits (which he was carrying, and found out their loss). <span class=\"citation\">Erub. 41ᵇ</span> <span dir=\"rtl\">למשְׁמוּשֵׁי להו זוודתא</span> (not <span dir=\"rtl\">בהו</span>) to make shrouds ready for them.</div>","alt":[]},"16912":{"h":"מַשְׁמָשׁ","r":"M02936","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַשְׁמֵשׁ\">preced.</a> wds.; cmp. <a href=\"#\" data-headword=\"מַמָּשׁ\">מַמָּשׁ</a>) <i>substance</i>. <span class=\"citation\">Y. Ber. III, 6ᵈ</span> bot. <span dir=\"rtl\">מַשְׁמָשָׁהּ קיים</span> its substance remains visible; <span dir=\"rtl\">מים אין מַשְׁמָשָׁן קיים</span> (not <span dir=\"rtl\">משמשה</span>, ed. Lehm. <span dir=\"rtl\">משמוש׳</span>) of liquids there is no substance left (when the spot is dried up).</div>","alt":[]},"16913":{"h":"מַשְׁמְשָׁנִית","r":"M02937","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַשְׁמָשׁ\">preced.</a> wds.) <i>one who touches everything, thievish</i>. <span class=\"citation\">Gen. R. s. 74</span> <span dir=\"rtl\">היה מכירה שהיא מ׳</span> he knew her to be inclined to steal. <span class=\"citation\">Gen. R. s. 18</span> <span dir=\"rtl\">ממש׳</span>; <span class=\"citation\">Yalk. ib. 24</span> <a href=\"#\" data-headword=\"מֵישָׁרָא\">מש׳</a>; <span class=\"citation\">Yalk. Is. 265</span> <span dir=\"rtl\">ממש׳</span> (<span class=\"citation\">Deut. R. s. 6</span> <a href=\"#\" data-headword=\"גּוֹנֶבֶת\">גּוֹנֶבֶת</a>).</div>","alt":["מְמַשְׁמְ׳"]},"16914":{"h":"מֵשָׁן","r":"M02938","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵישָׁן\">מֵישָׁן</a></div>","alt":[]},"16915":{"h":"מִשְׁנֶה I","r":"M02939","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lieutenant, viceroy</i>. <span class=\"citation\">Midr. Till. to Ps. CXLIX</span> <span dir=\"rtl\">הקב&quot;ה אין לו … ולא מ׳</span> the Lord has no dux nor eparch nor lieutenant.</div>","alt":[]},"16916":{"h":"מִשְׁנֶה II","r":"M02940","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מִשְׁנֶה I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>repetition</i>. (<span dir=\"rtl\">ספר</span>) <span dir=\"rtl\">מִשְׁנֵה תורה</span> <i>the Book of Deuteronomy</i>. <span class=\"citation\">Gen. R. s. 3</span>; <span class=\"citation\">Yalk. Gen. 4</span>. <span class=\"citation\">Meg. 31ᵇ</span> <span dir=\"rtl\">קללות שבמ׳ ת׳ וכ׳</span> the curses contained in Deuteronomy (<span class=\"citation\">Deut. XXVIII, 15—68</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>copy, duplicate</i>. <span class=\"citation\">Snh. 22ᵃ</span></div><div class=\"sense\"><b>—3)</b>  = <a href=\"#\" data-headword=\"מִשְׁנָה\">next w.</a> <span class=\"citation\">Sifré Deut. 161</span>; <span class=\"citation\">Yalk. ib. 915</span> <span dir=\"rtl\">תרגום מביא לידי מ׳ מ׳ מביא וכ׳</span> interpretation (of the Law, Targum) leads to oral law, the study of the oral law leads to discussion (Talmud).</div>","alt":[]},"16917":{"h":"מִשְׁנָה","r":"M02941","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִשְׁנֶה II\">preced.</a>) <i>repetition, verbal teaching by repeated recitation</i>; <i>traditional law</i>, opp. to <a href=\"#\" data-headword=\"מִקְרָא\">מִקְרָא</a>. <span class=\"citation\">Ab. III, 7</span> <span dir=\"rtl\">מפסיק ממִשְׁנָתוֹ</span> interrupts his study. <span class=\"citation\">Ib. 8</span> <span dir=\"rtl\">כל השוכח … ממשנתו</span> he who forgets one word of what he has learned. <span dir=\"rtl\">תקפה עליו משנתו</span> his study was too hard for him. <span class=\"citation\">Erub. 54ᵇ</span> <span dir=\"rtl\">כיצד סדר</span> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"מ׳\">מ׳</a> what was the order of delivery of the oral law? <span class=\"citation\">Ber. 5ᵃ</span> (ref. to <span class=\"citation\">Ex. XXIV, 12</span>) <span dir=\"rtl\">התורה … והמצוה זו מ׳</span> ‘Torah’ means the Pentateuch, ‘Mitsvah’, the oral law; a. fr.—Esp. <i>Mishnah, a collection of oral laws</i>, esp. that edited by R. Judah han-Nasi; also <i>a section of the Mishnah</i>. <span class=\"citation\">Esth. R. to I, 2</span>, a. fr. <span dir=\"rtl\">ששה סדרי מ׳</span> the six Orders of the Mishnah; <span class=\"citation\">Cant. R. to VI, 4</span>; Pesik. Vayhi, p. 7ᵃ, sq. <span dir=\"rtl\">ערכי המ׳</span>, v. <a href=\"#\" data-headword=\"עֵרֶךְ\">עֵרֶךְ</a>. <span class=\"citation\">Ned. 91ᵃ</span> <span dir=\"rtl\">מ׳ ראשונה</span> the earliest collection, <span dir=\"rtl\">מ׳ שניה</span> the second edition. <span class=\"citation\">Y. Keth. V, 29ᵈ</span> bot.; <span class=\"citation\">Y. Ter. VIII, beg. 45ᵃ</span>, sq.; a. fr.—<span class=\"citation\">Y. Yeb. III, 4ᵈ</span>, a. e. <span dir=\"rtl\">אבי המ׳</span>, v. <a href=\"#\" data-headword=\"הוֹשַׁעְיָא\">הוֹשַׁעְיָא</a>. <span class=\"citation\">Y. Hor. III, end, 48ᶜ</span> <span dir=\"rtl\">מִשְׁנָתוֹ של וכ׳</span> the collection made by &amp;c.—<span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">ולא מ׳ עשיתי</span> did I not follow the law of the Mishnah?; <span class=\"citation\">ib.</span> <span dir=\"rtl\">וזו מִשְׁנַת החסידים</span> but is this the <i>mishnah</i> of the pious (who must act kindlier than the strict law demands)?—<span class=\"citation\">Erub. 62ᵇ</span>, a. fr. <span dir=\"rtl\">משנת ר׳ … קב ונקי</span> the opinions of R … recorded in collections are merely a <i>ḳab</i> (few) but pure (incontestable); a. fr.—Pl. <a href=\"#\" data-headword=\"מִשְׁנָיוֹת\">מִשְׁנָיוֹת</a>. Y. Hor. l. c. <span dir=\"rtl\">מ׳ גדולות</span> the large collections. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שיקע … רוב מ׳</span> Rabbi embodied (in his collection) most of the collections (of his predecessors); a. fr.</div>","alt":[]},"16918":{"h":"מַשְׁנֶה","r":"M02942","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִשְׁנָה\">preced.</a>) <i>Mishnah-teacher</i>. <span class=\"citation\">Y. Maasr. III, 50ᵈ</span>, v. <a href=\"#\" data-headword=\"סַפָּר\">סַפָּר</a>.</div>","alt":[]},"16919":{"h":"מַשְׁנוֹיָיתָא","r":"M02943","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁנֵי\">שְׁנֵי</a>) <i>different directions</i> of the axis of the eyes, <i>squinting, strabismus</i>. <span class=\"citation\">Bekh. 44ᵃ</span> <span dir=\"rtl\">מ׳ מבעינו</span> the disqualification from strabismus is derived from <i>b’ʿeno</i> (<span class=\"citation\">Lev. XXI, 20</span>). Ib. <span dir=\"rtl\">משום משניותא</span> (corr. acc.; Rashi: <span dir=\"rtl\">משְׁנָיָיתָא</span>).</div>","alt":[]},"16920":{"h":"מִשְׁנָיוֹת","r":"M02944","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִשְׁנָה\">מִשְׁנָה</a></div>","alt":[]},"16921":{"h":"משניותא","r":"M02945","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִשְׁנָיוֹת\">preced. art.</a></div>","alt":[]},"16922":{"h":"מִשְׁנִים","r":"M02946","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">מִשְׁנִיִּים</span>, denom. of <a href=\"#\" data-headword=\"מִשְׁנָה\">מִשְׁנָה</a>) <i>teachers of Mishnah</i>. Lam. R. introd. (R. Abba 2); <span class=\"citation\">Y. Ḥag. I, 76ᶜ</span>, a. e. <span dir=\"rtl\">סופרים ומ׳</span> teachers of Bible and of Mishnah. <span class=\"citation\">Ex. R. s. 47</span> <span dir=\"rtl\">שיהיו המ׳ יושבין וכ׳</span> that the teachers of Mishnah should hold sessions in the morning &amp;c.; a. e.</div>","alt":["מִשְׁנִין"]},"16923":{"h":"מִשְׁעֲמָמוּתָא","r":"M02947","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שִׁיעֲמוּם\">שִׁיעֲמָמוּתָא</a></div>","alt":[]},"16924":{"h":"מִשְׁעֶנֶת","r":"M02948","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>crutch</i>. <span class=\"citation\">Gitt. 72ᵇ</span>, sq. <span dir=\"rtl\">הלך על מִשְׁעַנְתּוֹ</span> when he walked on his crutch; a. e.</div>","alt":[]},"16925":{"h":"מְשָׁעֵר","r":"M02949","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שַׁעַר\">שַׁעַר</a>) <i>market-commissioner</i>. <span class=\"citation\">Gen. R. s. 98</span>.</div>","alt":[]},"16926":{"h":"*מִשְׁפּוּ","r":"M02950","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שפי\">שפי</a>) <i>wine-sample</i>. <span class=\"citation\">Gen. R. s. 38</span> (play on <a href=\"#\" data-headword=\"שפי\">שפה</a>, <span class=\"citation\">Gen. XI, 1</span>) <span dir=\"rtl\">הא מ׳ דכולא בישא</span> this sample (proves) that all the wine is bad, v. <a href=\"#\" data-headword=\"מִסְתְּיָא\">מִסְתְּיָא</a></div>","alt":[]},"16927":{"h":"מִשְׁפָּחָה","r":"M02951","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>family, kinship</i>. Tanḥ. ed. Bub., Noah 24 (play on <a href=\"#\" data-headword=\"שפי\">שפה</a>, <span class=\"citation\">Gen. XI, 1</span>) <span dir=\"rtl\">מ׳ אחת</span> one kinship (all equally bad, cmp. <a href=\"#\" data-headword=\"*מִשְׁפּוּ\">preced. w.</a>). <span class=\"citation\">B. Bath. 109ᵇ</span> <span dir=\"rtl\">מִשְׁפַּחַת אב קרויה מ׳</span> the father’s kinship is called one’s family (not the mother’s). <span class=\"citation\">Eduy. VIII, 7</span>; <span class=\"citation\">Kidd. 71ᵃ</span> <span dir=\"rtl\">משפחת בית וכ׳</span> (not <span dir=\"rtl\">משפחות</span>) a family named Beth &amp;c.; a. fr.—Pl. <span dir=\"rtl\">מִשְׁפָּחוֹת</span>. <span class=\"citation\">Tosef. Naz. I, 3</span>, a. e., v. <a href=\"#\" data-headword=\"גָּלָה\">גָּלָה</a>; a. fr.</div>","alt":[]},"16928":{"h":"מִשְׁפָּט","r":"M02952","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sentence, judgment; justice, law</i>. <span class=\"citation\">Meg. 21ᵃ</span> top; <span class=\"citation\">Snh. 11ᵇ</span> <span dir=\"rtl\">מה מ׳ ביום וכ׳</span> as sentence can be passed in day-time only &amp;c. <span class=\"citation\">Eduy. II, 10</span> <span dir=\"rtl\">מִשְׁפַּט רשעים וכ׳</span> the judgment (punishment) of the wicked in Gehenna lasts twelve months. Tanḥ. <span class=\"citation\">Mishp. 1</span> <span dir=\"rtl\">בעל זרוע אינו רוצה לעשות דבריו במ׳ אלא מעביר על המ׳</span> a man of might does not care to act according to law, but ignores the law; a. fr.—Pl. <span dir=\"rtl\">מִשְׁפָּטִים</span>. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">על ידי המ׳ שנתת להם וכ׳</span> through the laws which thou hast given to them, they, having a dispute with one another, go to law and make peace. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בבקר ניתנה התורה … נתנו המ׳</span> in the morning the Law (religious principles) was given, and in the evening the civil law (<span class=\"citation\">Ex. XXI</span>, sq.). <span class=\"citation\">Midr. Till. to Ps. XXXVI</span> <span dir=\"rtl\">אין קצבה למ׳ וכ׳</span> there is no limit to the judgments for the wicked; a. fr.—<i>Mishpatim</i>, name of a Scriptural lesson of a week (<span class=\"citation\">Ex. XXI, 1</span> to XXIV, 18).</div>","alt":[]},"16929":{"h":"מַשְׁפֵּךְ","r":"M02953","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפַךְ\">שָׁפַךְ</a>) <i>funnel.</i> <span class=\"citation\">Kel. III, 8</span>. <span class=\"citation\">Tosef. Sabb. VIII</span> (<span class=\"citation\">IX), 10</span>; a. fr.—<span class=\"citation\">Ab. V, 15</span> <a href=\"#\" data-headword=\"מ׳\">מ׳</a> a scholar that learns and forgets easily, cmp. <a href=\"#\" data-headword=\"מְשַׁמֶּרֶת\">מְשַׁמֶּרֶת</a>.—Pl. <span dir=\"rtl\">מַשְׁפֵּכִים</span>, <span dir=\"rtl\">מַשְׁפֵּכִין</span>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 7</span>.</div>","alt":[]},"16930":{"h":"מַשְׁפַּךְ","r":"M02954","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"מַשְׁפֵּךְ\">preced.</a>), <span dir=\"rtl\">מ׳ מֵרָמָתָא</span> <i>outpouring</i> (<i>of torrents</i>) <i>from the heights, ravines</i>; <i>slopes</i>. <span class=\"citation\">Targ. O. Deut. III, 17</span> (h. text <span dir=\"rtl\">אשדת</span>). <span class=\"citation\">Targ. Josh. X, 40</span>; a. fr.</div>","alt":[]},"16931":{"h":"מִשְׁפֶּלֶת","r":"M02955","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁפֵל I\">שָׁפַל</a>, cmp. <a href=\"#\" data-headword=\"פָּשַׁל\">פָּשַׁל</a>) <i>a wicker basket carried on a pole over the shoulder.</i> <span class=\"citation\">Kel. XIX, 10</span>. <span class=\"citation\">Tosef. Kel. B. Mets. VI, 9</span>; a. fr.—Pl. <span dir=\"rtl\">מִשְׁפָּלוֹת</span>. <span class=\"citation\">Kel. XXIV, 9</span>. <span class=\"citation\">Shebi. III, 2</span> <span dir=\"rtl\">מ׳ של לתך לתך</span> baskets (of foliage for dung) of a <i>lethekh</i> each. Ib. <span dir=\"rtl\">מוסיפין על המ׳ וכ׳</span> you may add to the number of baskets (to be put on the dunghills) &amp;c. Y. ib. 34ᶜ top <span dir=\"rtl\">לא יפרוק את המ׳</span> he (the Israelite) must not unload the baskets. <span class=\"citation\">Cant. R. to VII, 3</span>; a. fr.</div>","alt":[]},"16932":{"h":"*מִשְׁקְדֵי","r":"M02956","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁקֵד I\">שקד</a>) <i>guards</i>; <span dir=\"rtl\">מ׳ חלזוני</span> <i>snail-shells</i>. <span class=\"citation\">Ab. Zar. 28ᵇ</span> ed. (Ms. M. a. Ar. <a href=\"#\" data-headword=\"משקרי\">משקרי</a>).</div>","alt":[]},"16933":{"h":"מַשְׁקֶה","r":"M02957","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>drink, liquid</i>. Sifra Sh’mini ch. IX, Par. 8 מ׳ זה היין ‘drink’ (<span class=\"citation\">Lev. XI, 34</span>) means wine. Ib. <span dir=\"rtl\">מ׳ סרוח</span> spoiled liquid; <span class=\"citation\">Pes. 18ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">מַשְׁקִים</span>, <span dir=\"rtl\">מַשְׁקִין</span>. <span class=\"citation\">Ib. 17ᵇ</span> <span dir=\"rtl\">מ׳ הבאין מחמת ידים</span> liquids which have become unclean through contact with unclean hands. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שנטמאו מחמת מ׳</span> vessels which have become unclean through the liquids put into them; a. fr.—<span dir=\"rtl\">מַשְׁקֵי בית מטבחיא</span>, v. <a href=\"#\" data-headword=\"מַטְבָּחַיָּיא\">מַטְבָּחַיָּיא</a> a. <a href=\"#\" data-headword=\"מַטְבָּחַיָּיא\">מַדְבָּחַיָּיא</a>.</div>","alt":[]},"16934":{"h":"מַשְׁקוֹי","r":"M02958","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁקֵי\">מַשְׁקֵי</a></div>","alt":["מַשְׁקוֹיי"]},"16935":{"h":"מִשְׁקוֹל","r":"M02959","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִשְׁקָל\">מִשְׁקָל</a></div>","alt":[]},"16936":{"h":"מִשְׁקוֹלֶת","r":"M02960","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>plummet.</i> <span class=\"citation\">Kel. XXIX, 3</span>. <span dir=\"rtl\">חוט המ׳</span> plumb-line. <span class=\"citation\">B. Bath. II, 13</span> <span dir=\"rtl\">כנגד המ׳</span> measure by the plummet (cutting off all branches as far as they hang over the border line); <span class=\"citation\">Tosef. ib. I, 15</span>; cmp. <a href=\"#\" data-headword=\"מְטוֹטֶלֶת\">מְטוֹטֶלֶת</a>; a. e.—Pl. <a href=\"#\" data-headword=\"מִשְׁקוֹלֶת\">מִשְׁקוֹלוֹת</a>. <span class=\"citation\">Kel. XII, 8</span> Talm. ed. <span dir=\"rtl\">המטולטלות והמ׳</span> (Mish. ed., a. ed. Dehr. <span dir=\"rtl\">מִשְׁקָלוֹת</span>) two kinds of plummets (R. S. <i>weights</i>, v. <a href=\"#\" data-headword=\"מִשְׁקָל\">מִשְׁקָל</a>).</div>","alt":[]},"16937":{"h":"מַשְׁקוּלְתָּא","r":"M02961","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Zech. IV, 10</span>; a. fr.</div>","alt":["מִשְׁקַלְתָּא"]},"16938":{"h":"מַשְׁקוֹף","r":"M02962","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cross-piece, lintel</i>. <span class=\"citation\">Ab. d’R. N. ch. XXVI</span>, end <span dir=\"rtl\">מ׳ העליון</span> the lintel, contrad. to <a href=\"#\" data-headword=\"אִיסְקוּפָּא\">איסקופה</a>. Mekh. Bo, s. 11; <span class=\"citation\">Yalk. Ex. 197</span> <span dir=\"rtl\">שלשה מזבחות … המ׳ וכ׳</span> our ancestors in Egypt had three altars; the lintel and the two posts; a. e.</div>","alt":[]},"16939":{"h":"מַשְׁקוֹפִי","r":"M02963","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁקַף\">שְׁקַף</a>) <i>knock, bruise</i>. <span class=\"citation\">Targ. O. Ex. XXI, 25</span> (not … <a href=\"#\" data-headword=\"פִּי\">פֵי</a>). <span class=\"citation\">Targ. Y. I ib. XV, 25</span>.</div>","alt":["מַשְׁקוּ׳"]},"16940":{"h":"מַשְׁקֵי","r":"M02964","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"מַשְׁקֶה\">מַשְׁקֶה</a>, <i>drink</i>. <span class=\"citation\">Targ. Lev. XI, 34</span>; a. e.—<span class=\"citation\">Koh. R. to III, 9</span> <span dir=\"rtl\">חד מַשְׁקוֹיי חמים</span> (some ed. <a href=\"#\" data-headword=\"מַשְׁקוֹי\">מַשְׁקוֹי</a>, oth. <span dir=\"rtl\">מַשְׁקַיי</span>) one hot drink.</div><div class=\"sense\"><b>—2)</b>  = h. <a href=\"#\" data-headword=\"מִשְׁתֶּה\">מִשְׁתֶּה</a>, <i>feast</i>. <span class=\"citation\">Targ. Esth. I, 3</span>. Targ. II Esth. IX, 17, sq. <a href=\"#\" data-headword=\"מַשְׁקֵי\">מַשְׁקַיָּא</a>; a. fr.</div>","alt":["מַשִׁקְיָא"]},"16941":{"h":"מַשְׁקֵיצָתָא","r":"M02965","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁקַץ\">שְׁקַץ</a>) <i>abominations, idols</i>. <span class=\"citation\">Targ. Y. II, Deut. XXIX, 16</span> <span dir=\"rtl\">מקש׳</span> (corr. acc.).</div>","alt":[]},"16942":{"h":"מִשְׁקָל","r":"M02966","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>weighing, weight</i>. <span class=\"citation\">Tosef. Ḥull. IX, 9</span> <span dir=\"rtl\">לקח הימנו במ׳</span> if he bought of him by the weight. <span class=\"citation\">B. Bath. V, 10</span> <span dir=\"rtl\">על כל מ׳ ומ׳</span> as often as he uses the weights; Sifra K’dosh. Par. 3, ch. VIII <span dir=\"rtl\">על כל מ׳ מ׳</span> (corr. acc.). Ib. (ref. to <span class=\"citation\">Lev. XIX, 35</span>), v. <a href=\"#\" data-headword=\"טוּרְטִינִי\">טוּרְטִינִי</a>. <span class=\"citation\">Ker. 5ᵃ</span> <span dir=\"rtl\">לא יניח מ׳ במ׳ וכ׳</span> he must not use one weighed species as a weight for the other; a. fr.—Pl. <span dir=\"rtl\">מִשְׁקָלוֹת</span>. Sifra. l. c.; B. Bath. l. c.; v. <a href=\"#\" data-headword=\"מָחָה\">מָחָה</a>. Tunḥ. Balak 12 <span dir=\"rtl\">מְעַוֵּל ומשקר במ׳</span> (not <a href=\"#\" data-headword=\"מְעוּלֶה\">מעולה</a>) committing wrong and fraud in weights; ib. <span dir=\"rtl\">משקר במ׳</span> using false weights; <span class=\"citation\">Yalk. Num. 765</span>; a. fr.</div>","alt":[]},"16943":{"h":"מִשְׁקֹלֶת","r":"M02967","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִשְׁקוֹלֶת\">מִשְׁקוֹלֶת</a>, <a href=\"#\" data-headword=\"מַשְׁקוּלְתָּא\"><a href=\"#\" data-headword=\"מַשְׁקוּלְתָּא\">מַשְׁקוּלְתָּא</a>.</a></div>","alt":["מִשְׁקַלְתָּא"]},"16944":{"h":"משקרי","r":"M02968","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"*מִשְׁקְדֵי\">מִשְׁקְדֵי</a></div>","alt":[]},"16945":{"h":"מֵשַׁר","r":"M02969","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵישַׁר\">מֵישַׁר</a></div>","alt":[]},"16946":{"h":"מֵשְׁרָא I","r":"M02970","html":"<div class=\"sense\"><i>garden-bed; plain</i>, v. <a href=\"#\" data-headword=\"מֵישָׁרָא\">מֵישְׁרָא</a>.</div>","alt":[]},"16947":{"h":"מֵשְׁרָא II","r":"M02971","html":"<div class=\"sense\"><i>camp</i>, v. <a href=\"#\" data-headword=\"מַשְׁרֵי\">מַשְׁרֵי</a>.</div>","alt":[]},"16948":{"h":"מִשְׁרָה","r":"M02972","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>infusion; steeping</i>; <span dir=\"rtl\">משְׁרַת ענבים</span> <i>infusion of grapes</i>. <span class=\"citation\">Pes. 44ᵃ</span> <span dir=\"rtl\">האי משרת וכ׳</span> this additional specification of <i>mishrath</i> (<span class=\"citation\">Num. VI, 3</span>) &amp;c.; a. e.—<span class=\"citation\">Tosef. Shebi. VI, 25</span>, v. <a href=\"#\" data-headword=\"כְּבִיסָה\">כְּבִיסָה</a>.—<span class=\"citation\">B. Kam. 102ᵃ</span>, a. e. <span dir=\"rtl\">לאכלה ולא למ׳</span> you may use the products of the Sabbatical year ‘for eating’ (<span class=\"citation\">Lev. XXV, 6</span>), but not as substances for steeping, v. <a href=\"#\" data-headword=\"מָלוּגְמָא\">מְלוּגְמָא</a>; a. fr.—Esp. <i>a pond for steeping flax</i> &amp;c. <span class=\"citation\">B. Bath. II, 10</span> <span dir=\"rtl\">מרחיקין את המ׳ וכ׳</span> you must keep your pond removed from your neighbor’s vegetable garden &amp;c. <span class=\"citation\">Ib. 18ᵇ</span> <span dir=\"rtl\">מ׳ וירקא</span> the legal distance between a pond and your neighbor’s vegetable garden; a. e.</div>","alt":[]},"16949":{"h":"מַשְׁרְוֵי","r":"M02973","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁרֵי\">מַשְׁרֵי</a></div>","alt":[]},"16950":{"h":"מַשְׁרוּנְיָא","r":"M02974","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Mashrunia</i>, in Babylonia. <span class=\"citation\">B. Mets. 107ᵇ</span> <span dir=\"rtl\">בני מ׳</span> (Ar. <span dir=\"rtl\">מְרוּשַׁנְ׳</span>; oth. Var., v. Rabb. D. S. a. l. note 6) the community of M. (to which the adjacent forest belonged).</div>","alt":[]},"16951":{"h":"מַשְׁרוֹעָא","r":"M02975","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁרַע\">שְׁרַע</a>) <i>slippery spot.</i> <i>—</i> Pl. <span dir=\"rtl\">מַשְׁרוֹעִין</span>. <span class=\"citation\">Targ. Jer. XXIII, 12</span>.</div>","alt":[]},"16952":{"h":"מַשְׁרוּעִיתָא","r":"M02976","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"מַשְׁרוֹעָא\">preced.</a>) pr. n. <i>Mashruʿitha</i>, name of a peak. <span class=\"citation\">Targ. I Sam. XIV, 4</span> (h. text <span dir=\"rtl\">בּוֹצֵץ</span>).</div>","alt":[]},"16953":{"h":"מַשְׁרֵי","r":"M02977","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁרֵי\">שְׁרֵי</a>) <i>camp, resting place</i>. <span class=\"citation\">Targ. Y. Gen. XXXII, 9</span>. <span class=\"citation\">Targ. Ps. XIX, 5</span> <a href=\"#\" data-headword=\"מַשְׁרְוֵי\">מַשְׁרְוֵי</a> (<a href=\"#\" data-headword=\"מַשְׁרְוֵי\">מְשַׁרְוֵי</a>; Ms. <a href=\"#\" data-headword=\"מֵישָׁרָא\">מֵישְׁרָא</a>). <span class=\"citation\">Targ. Is. XIII, 22</span> <a href=\"#\" data-headword=\"מֵישְׁרָא II\">מֵישְׁרֵי</a>; a. fr.—Pl. <span dir=\"rtl\">מַשִּׁרְוַיָין</span>, v. <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">next w.</a></div>","alt":["מִ׳","מֵישְׁרֵי"]},"16954":{"h":"מַשְׁרִיתָא","r":"M02978","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מַשְׁרֵי\">same</a>. <span class=\"citation\">Targ. O. Gen. XXXII, 9</span>; a. fr.—Constr. <a href=\"#\" data-headword=\"מַשְׁלִית\">מַשְׁרִית</a>, <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">מַשִּׁרְיַת</a>, <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">מַשִּׁירְ׳</a>. <span class=\"citation\">Targ. Num. II, 9</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">מַשְׁרְיָתָא</a>, <span dir=\"rtl\">מַשִּׁרְיָיתָא</span>, <span dir=\"rtl\">מַשִּׁרְיָין</span>, <span dir=\"rtl\">מַשִּׁי׳</span>. <span class=\"citation\">Targ. Gen. XXXII, 8</span>; <span class=\"citation\">11</span> (Y. <span dir=\"rtl\">מַשִּׁרְוַיָין</span>, v. <a href=\"#\" data-headword=\"מַשְׁרֵי\">preced.</a>). <span class=\"citation\">Targ. Num. XXIII, 10</span>; a. fr.—<span class=\"citation\">Snh. 26ᵃ</span>, sq. <span dir=\"rtl\">באפי מַשִּׁרְיָיתֵיה</span> in the face of his camps (soldiers); <span dir=\"rtl\">מַשִּׁרְיָיתָךְ היכא</span> where are thy soldiers?</div>","alt":["מַשִּׁרְיָא","מַשִּׁירְ׳"]},"16955":{"h":"מְשַׁרְשְׁיָא","r":"M02979","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’sharsh’ya</i>, an Amora. <span class=\"citation\">Snh. 63ᵇ</span>. <span class=\"citation\">Ker. 6ᵃ</span>; a. fr.</div>","alt":["מְשַׁרְשְׁיָה"]},"16956":{"h":"מִשְׁרַת","r":"M02980","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִשְׁרָה\">מִשְׁרָה</a></div>","alt":[]},"16957":{"h":"מַשֶּׁרֶת","r":"M02981","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשַׁר\">נָשַׁר</a>) <i>a depilatory substance</i>. <span class=\"citation\">Naz. 42ᵃ</span> <span dir=\"rtl\">מפני המ׳</span> because he might eventually use a depilatory earth.</div>","alt":[]},"16958":{"h":"מַשְׂרֵת","r":"M02982","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְרֵת\">מַסְרֵת</a></div>","alt":[]},"16959":{"h":"מְשָׁרֵת","r":"M02983","html":"<div class=\"sense\">, m.(b. h.; <i>servant, attendant</i>. <span class=\"citation\">Y. Ned. IX, beg. 41ᵇ</span> מ׳ ר׳ מאיר וכ׳ I was the attendant of R. Meïr on both his flights; a. e.—[<span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">מ׳ תחתיך</span>, v. <a href=\"#\" data-headword=\"שָׁרַת\">שָׁרַת</a>.]—Pl. <span dir=\"rtl\">מְשָׁרְתִים</span>. <span class=\"citation\">Snh. 63ᵇ</span> <span dir=\"rtl\">מְשָׁרְתֵי עכ&quot;ום</span> idolatrous temple-servants.</div>","alt":[]},"16960":{"h":"מָשַׁשׁ","r":"M02984","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מוּשׁ\">מוּשׁ</a>) <i>to feel, grope, search.</i> <i>—Palp</i>. <a href=\"#\" data-headword=\"מִשְׁמֵשׁ\">מִשְׁמֵשׁ</a> q. v.</div>","alt":[]},"16961":{"h":"מְשַׁשׁ I","r":"M02985","html":"<div class=\"sense\"><i>Pa</i>. <span dir=\"rtl\">מַשֵּׁישׁ</span> <a href=\"#\" data-headword=\"מָשַׁשׁ\">same</a>. <span class=\"citation\">Targ. O. Gen. XXXI, 34</span>; <span class=\"citation\">37</span> (Y. <a href=\"#\" data-headword=\"פַּשְׁפֵּשׁ I\">פשפש</a>).</div>","alt":[]},"16962":{"h":"מְשַׁשׁ II","r":"M02986","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁשׁ I\">preced.</a>) <i>substance, essence</i>; <i>reality</i>. <span class=\"citation\">Targ. Lam. II, 14</span>. <span class=\"citation\">Targ. Job XV, 3</span>; a. e.—<span class=\"citation\">Ab. Zar. 55ᵃ</span> <span dir=\"rtl\">דע&quot;ז לית בה מ׳</span> that there is no reality in idols. <span class=\"citation\">Pes. 4ᵇ</span> <span dir=\"rtl\">אטו אמירה דהני מידי מ׳ אית ביה</span> has their declaration any significance?—<span class=\"citation\">Yeb. 102ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲלַץ\">חֲלַץ</a>. <span class=\"citation\">Sabb. 152ᵇ</span> bot., v. <a href=\"#\" data-headword=\"מַמָּשׁ ²\">מַמָּשָׁא</a>; <span class=\"citation\">Yalk. Gen. 33</span> <span dir=\"rtl\">מַשָּׁשָׁה</span>.</div>","alt":["מְשָׁשָׁא","מַשָּׁ׳"]},"16963":{"h":"מְשַׂשְׂתָּן","r":"M02987","html":"<div class=\"sense\">, part. <i>Hif.</i> of <a href=\"#\" data-headword=\"שׂוּשׂ\">שׂוּשׂ</a> q. v. <span class=\"citation\">Koh. R. to VII, 19</span>.</div>","alt":[]},"16964":{"h":"מִשְׁתָּאֵל","r":"M02988","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁאֵיל\">שְׁאֵל</a>) <i>one inquiring of the oracle, augur, diviner</i>. <span class=\"citation\">Targ. Is. III, 2</span> (h. text <a href=\"#\" data-headword=\"קְסַם I\">קֹסֵם</a>).</div>","alt":[]},"16965":{"h":"מִשְׁתֶּה","r":"M02989","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>drink</i>. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">כמִשְׁתֵּה ראשונים וכ׳</span> as those before you drank (the cup of grief) &amp;c.—Esp. <i>feast, wedding meal</i> &amp;c. <span class=\"citation\">Gen. R. s. 53</span> מ׳ גדול מִשְׁתֵּה גדולים ‘a great feast’ (<span class=\"citation\">Gen. XXI, 8</span>) a festive gathering of great men. <span class=\"citation\">Keth. 4ᵃ</span>, a. fr. <span dir=\"rtl\">שבעת ימי המ׳</span> the wedding week. <span class=\"citation\">Sabb. 67ᵇ</span> <span dir=\"rtl\">עשה מ׳ לבנו</span> gave a feast in honor of his son. <span class=\"citation\">Keth. 8ᵃ</span> <span dir=\"rtl\">נערים ממ׳ נגינתם</span> the voices of the youths singing at their banquets. <span class=\"citation\">Ber. I, 1</span>, a. fr. <span dir=\"rtl\">בית המ׳</span> (the house of a) wedding. <span class=\"citation\">Deut. R. s. 1</span>, end; a. fr.—Pl. <span dir=\"rtl\">מִשְׁתָּאוֹת</span>, <span dir=\"rtl\">מִשְׁתָּיוֹת</span>. <span class=\"citation\">B. Bath. 91ᵃ</span>. <span class=\"citation\">Ruth R. to IV, 2</span>; Y. Keth. I, 25ᵃ <span dir=\"rtl\">מכאן לבית הזה שהממנים … בבית מ׳ וכ׳</span> from here (Ruth l. c.) this house (of the Nasi) learned to ordain elders at its banquets. <span class=\"citation\">Nidd. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"רָגַל\">רָגַל</a>; a. fr.</div>","alt":[]},"16966":{"h":"מִשְׁתּוּיִין","r":"M02990","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַשְׁתִּית\">מַשְׁתִּית</a>) <i>foundations, supports</i>; trnsf. <i>faith</i>. Targ. Y. II XXX, 11, v. <a href=\"#\" data-headword=\"מַשְׁתִּית\">מַשְׁתִּית</a>.</div>","alt":[]},"16967":{"h":"מִשְׁתּוֹקָא","r":"M02991","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁתַק\">שְׁתַק</a>) <i>silence</i>. <span class=\"citation\">Targ. Y. Lev. X, 3</span>.—<span class=\"citation\">Meg. 18ᵃ</span>, a. e. <span dir=\"rtl\">מלה בסלע מ׳ בתרין</span> a word is worth a Sela, silence is worth two. Ib.; <span class=\"citation\">Y. Ber. IX, beg. 12ᵈ</span> <span dir=\"rtl\">סמא דכולא מ׳</span>, v. <a href=\"#\" data-headword=\"סַמָּא II\"><span dir=\"rtl\">סַמָּא</span> II</a>.</div>","alt":[]},"16968":{"h":"מִשְׁתּוּתָא","r":"M02992","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>drinking; feast</i>. <span class=\"citation\">Lam. R. to I, 7</span> <span dir=\"rtl\">מדכרא … דמ׳</span> she remembers the seven days of her wedding feast. <span class=\"citation\">Gen. R. s. 3</span> <span dir=\"rtl\">כן וכן אנא מפקד … דמִישְׁתּוּתִי</span> this is my order for my wedding feast. <span class=\"citation\">Y. Shebi. IV, end, 35ᶜ</span>; <span class=\"citation\">Lev. R. s. 11</span>, beg., v. <a href=\"#\" data-headword=\"פְּרוֹטוֹגַמְיָא\">פְּרוֹטוֹגַמְיָא</a>. <span class=\"citation\">Koh. R. to III, 2</span> <span dir=\"rtl\">במִשְׁתּוּתֵיה</span> at his wedding. <span class=\"citation\">Y. Ber. VI, 10ᶜ</span> bot. <span dir=\"rtl\">למִישְׁתִּיתֵיה וכ׳</span> to the wedding at &amp;c.; a. e.—Pl. <span dir=\"rtl\">מִשְׁתְּוָותָא</span>. <span class=\"citation\">Esth. R. to I, 9</span> <span dir=\"rtl\">מִשְׁתְּוָתֵיהוֹן</span>, v. <a href=\"#\" data-headword=\"גְּרַר\">גְּרַר</a>.</div>","alt":["מִישְׁ׳"]},"16969":{"h":"מַשְׁתּוּתָא","r":"M02993","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>foundation</i>. <span class=\"citation\">Esth. R. to I, 9</span> (play on <span dir=\"rtl\">ג̇ם̇</span> a. <span dir=\"rtl\">ושׁת̇י</span>) [read:] <span dir=\"rtl\">גם וגם מ׳ של ושתי הגיע וכ׳</span> level, level the foundation of Vashti, the time has come &amp;c., v. <a href=\"#\" data-headword=\"גְּמַם\">גְּמַם</a>.</div>","alt":[]},"16970":{"h":"מַשְׁתֵּי","r":"M02994","html":"<div class=\"sense\"><i>web</i>, v. <a href=\"#\" data-headword=\"מַשְׁתִּיתָא\">מַשְׁתִּיתָא</a>.</div>","alt":[]},"16971":{"h":"מִשְׁתִּי","r":"M02995","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"מִשְׁתֶּה\">מִשְׁתֶּה</a>. <span class=\"citation\">Targ. Is. III, 1</span>. <span class=\"citation\">Targ. II Chr. IX, 20</span>. <span class=\"citation\">Targ. I Sam. XXV, 36</span>; a. fr.—<span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">מ׳ מעלי</span> drinking is more effective. <span class=\"citation\">Pes. 103ᵇ</span> עקר דעתיה ממִשְׁתְּיֵיה Ms. (ed. <span dir=\"rtl\">ממשתיא</span>) he has discarded the thought of drinking; a. e.—[<span class=\"citation\">Yalk. Is. 289</span>, v. next w.]</div>","alt":["מִשְׁתְּיָא","מִי׳"]},"16972":{"h":"*מַשְׁתָּיֵי","r":"M02996","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִשְׁתִּי\">preced.</a>) <i>horsemen watering their horses</i>. Lam. R. introd. (R. Joḥ. 1) (expl. <span dir=\"rtl\">שת שתו</span>, <span class=\"citation\">Is. XXII, 7</span>) <span dir=\"rtl\">מ׳ אזלין מ׳ אתיין וכ׳</span> one troop watering their horses went, another came, so that they appeared to be very numerous; <span class=\"citation\">Yalk. Is. 289</span> <span dir=\"rtl\">משתי</span> (corr. acc.).</div>","alt":[]},"16973":{"h":"מַשְׁתִּית","r":"M02997","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שָׁת\">שָׁת</a>, pl. <span dir=\"rtl\">שָׁתוֹת</span>; <a href=\"#\" data-headword=\"שִׁית\">שִׁית</a>) <i>foundation</i>. <span class=\"citation\">Gen. R. s. 71</span> (play on <span dir=\"rtl\">ב̇ג̇ד̇</span>, <span class=\"citation\">Gen. XXX, 11</span>) <span dir=\"rtl\">ב̇א מי שעתיד לג̇ד̇ד מַשְׁתִּיתָן וכ׳</span> he is coming who is destined to cut down the foundation (idolatry) of the gentiles (Ellijah the Gadite). v. <a href=\"#\" data-headword=\"מִשְׁתּוּיִין\">מִשְׁתּוּיִין</a>; <span class=\"citation\">Midr. Till. to Ps. XC, 1</span> <span dir=\"rtl\">מַשְׁתִּיתוֹ של עכ&quot;ום</span> the foundation of idolatry. <span class=\"citation\">Gen. R. s. 75</span> (ref. to <span dir=\"rtl\">השתות</span>, <span class=\"citation\">Ps. XI, 3</span>) Jacob <span dir=\"rtl\">שהוא מַשְׁתִּיתוֹ ויסודו וכ׳</span> who is the foundation and basis of the world; (<span class=\"citation\">Yalk. Ps. 653</span> <span dir=\"rtl\">שְׁתִיַּית עולם</span>, v. <a href=\"#\" data-headword=\"שְׁתִיָּה\">שְׁתִיָּה</a>). <span class=\"citation\">Koh. R. to II, 5</span> <span dir=\"rtl\">מַשְׁתִּיתָהּ של ארץ</span> the foundation (centre) of the earth. Ib. to II, 12. Midr. Sam. ch. XXVI.</div>","alt":[]},"16974":{"h":"מִשְׁתִּיתָא","r":"M02998","html":"<div class=\"sense\"><i>drink</i>, v. <a href=\"#\" data-headword=\"מִשְׁתּוּתָא\">מִשְׁתּוּתָא</a>.</div>","alt":[]},"16975":{"h":"מַשְׁתִּיתָא","r":"M02999","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (שְׁתִי II) <i>web</i>. <span class=\"citation\">Targ. Jud. XVI, 13</span>, sq.—<span class=\"citation\">Nidd. 58ᵃ</span>. <span class=\"citation\">Ex. R. s. 42</span>, end <span dir=\"rtl\">משתי בישתא</span>, v. <a href=\"#\" data-headword=\"מַסֵּכָה II\"><span dir=\"rtl\">מַסֵּכָה</span> II</a>.</div>","alt":["מַשְׁתֵּי׳","מַשְׁתֵּי"]},"16976":{"h":"מִשְׁתְּמוֹדַע","r":"M03000","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִשְׁתְּמוֹדַע I\">אִשְׁתְּמוֹדַע</a>) <i>acquaintance, friend</i>. <span class=\"citation\">Targ. Ps. CXLII, 5</span>.</div>","alt":[]},"16977":{"h":"משתמיהה","r":"M03001","html":"<div class=\"sense\">, prob. to be read: <span dir=\"rtl\">מַשְׁתִּימָה</span> m. (<a href=\"#\" data-headword=\"שְׁתַם\">שְׁתַם</a>) <i>borer, siphon</i>.—<span class=\"citation\">Y. Erub. X, 26ᵈ</span> top, expl. <a href=\"#\" data-headword=\"דְּיוֹבִיט\">דְּיוֹבִיט</a>.</div>","alt":[]},"16978":{"h":"מֵת","r":"M03002","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>dying, dead; corpse</i>. <span class=\"citation\">Ber. 3ᵇ</span> <span dir=\"rtl\">בפני המת</span> in the presence of a dead body; <span dir=\"rtl\">דבריו של מת</span> affairs concerning the dead. Ib. 18ᵇ, a. e. <span dir=\"rtl\">קשה רמה למת וכ׳</span> the gnawing of the worm is as painful to the buried corpse as a pin &amp;c.; a. v. fr.—<span dir=\"rtl\">מת מצוה</span>, v. <a href=\"#\" data-headword=\"מִצְוָה\">מִצְוָה</a>.—Pl. <span dir=\"rtl\">מֵתִים</span>, constr. <span dir=\"rtl\">מֵתֵי</span>. <span class=\"citation\">M. Kat. 20ᵃ</span> <span dir=\"rtl\">מתי מצוה</span>, v. <a href=\"#\" data-headword=\"מִצְוָה\">מִצְוָה</a>. <span class=\"citation\">Ber. 18ᵇ</span>. <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 1</span> <span dir=\"rtl\">לבין המ׳</span> to the graveyard; a. v. fr.—<span class=\"citation\">Snh. 55ᵃ</span>, a. fr. <span dir=\"rtl\">משמש מת</span> coition with <i>membrum mortuum</i></div>","alt":[]},"16979":{"h":"מֵתָא","r":"M03003","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִית II\"><span dir=\"rtl\">מֵיתָא</span> I</a> a. II.</div>","alt":[]},"16980":{"h":"מָתָא","r":"M03004","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מָאתָא\">מאתא</a>; <a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>; cmp. <a href=\"#\" data-headword=\"מָקוֹם\">מָקוֹם</a>; Mand. <a href=\"#\" data-headword=\"מָאתָא\">מאתא</a>; Assyr. mâtu, constr. mât <i>land</i>, v. Schr. KAT<sup>2</sup>, p. 510; 568) <i>home, place, town</i>. <span class=\"citation\">Men. 85ᵃ</span> (prov.) <span dir=\"rtl\">למָת ירקא ירקא שקול</span> Ar. a. Ms. K. (Ms. M. <span dir=\"rtl\">לבית</span>; ed. <span dir=\"rtl\">למתא ירקא</span>) carry vegetables to the home of vegetables; <span class=\"citation\">Ex. R. s. 9</span> <span dir=\"rtl\">למתא ירקא</span>; <span class=\"citation\">Yalk. Ex. 182</span> <span dir=\"rtl\">למ׳ דירקא</span>. <span class=\"citation\">Sabb. 145ᵇ</span> bot. (prov.) <span dir=\"rtl\">במ׳ שמאי שלא במ׳ וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">בלא מ׳</span>) at home my name (will give me my position), abroad, my dress. <span class=\"citation\">B. Kam. 113ᵇ</span> <span dir=\"rtl\">בר מ׳ אבר מ׳ מיעבט</span> one citizen may be levied upon for the delinquent taxes of a fellow citizen. <span class=\"citation\">Snh. 112ᵃ</span> <span dir=\"rtl\">בני מ׳</span> citizens (taxpayers, after a residence of twelve months); <span dir=\"rtl\">יתבי מ׳</span> residents (after thirty-days). <span class=\"citation\">Yeb. 17ᵃ</span> <span dir=\"rtl\">מָאתֵיה</span>, v. <a href=\"#\" data-headword=\"הַרְפַּנְיָא\">הַרְפַּנְיָא</a>; a. v. fr.—Pl. (fr. <span dir=\"rtl\">מתותא</span>, v. P. Sm. 2246) <a href=\"#\" data-headword=\"מַתְוָותָא\">מַתְוָותָא</a> <i>settlements</i>. <span class=\"citation\">Gitt. 7ᵃ</span> <span dir=\"rtl\">מ׳ דארעא וכ׳</span> small Palestinian places. <span class=\"citation\">Erub. 21ᵃ</span> <span dir=\"rtl\">מ׳ מבלען וכ׳</span> (ruined) settlements within a distance of &amp;c.—<span dir=\"rtl\">מתא מחסיא</span>, v. <a href=\"#\" data-headword=\"מְחַסְיָא\">מְחַסְיָא</a>.</div>","alt":[]},"16981":{"h":"מַתַּאי","r":"M03005","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mattai</i> (abbr. of <span dir=\"rtl\">מַתִּתְיָהוּ</span>), <i>Matthew</i>, a disciple of Jesus. <span class=\"citation\">Snh. 43ᵃ</span> (in a passage omitted in most editions), <span dir=\"rtl\">חמשה תלמידים היה לו לישו מ׳ וכ׳</span> Jesus had five disciples; M. etc. Ib. (by way of play on <a href=\"#\" data-headword=\"מָתַי\">מָתַי</a>, <span class=\"citation\">Ps. XLII, 3</span>, a. <span class=\"citation\">XLI, 6</span>) <a href=\"#\" data-headword=\"מַתַּי\">מַתַּי</a>, v. <a href=\"#\" data-headword=\"בּוּנִי\">בּוּנִי</a>.—V. <a href=\"#\" data-headword=\"מַתְּיָא\">מַתְּיָא</a>.</div>","alt":[]},"16982":{"h":"מַתְאִים","r":"M03006","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"תָּאַם\">תָּאַם</a>) <i>twin</i>-<i>;</i> esp. <i>twin-leaf, the central rib of a branch of palm-leaves</i>. Y. Succ. III, beg. 53ᶜ; v. <a href=\"#\" data-headword=\"תְּיוֹמֶת\">תְּיוֹמֶת</a>.</div>","alt":[]},"16983":{"h":"מַתְאִימָה","r":"M03007","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"מַתְאִים\">preced.</a>) <i>twin-teeth</i> (<i>bicuspids</i>), <i>molar teeth</i>. <span class=\"citation\">Bekh. VI, 4</span> חמ׳ Mish. (Talm. ed. 39ᵃ <a href=\"#\" data-headword=\"תְּיוֹמֶת\">תיומת</a>; Rashi <span dir=\"rtl\">מתא׳</span>; ib. in Ib. <span dir=\"rtl\">תיומות</span>, <a href=\"#\" data-headword=\"תְּיוֹמֶת\">תיומת</a>); Sifra Emor ch. VI. Par. 7 (Rabad to Sifra l. c.: <i>corner of the mouth</i>).</div>","alt":["מַתְאִימוֹת"]},"16984":{"h":"*מְתָאכְלֵי","r":"M03008","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אִיתְכָּלָא\">אִיתְכָּלָא</a>), <span dir=\"rtl\">מ׳ דתומי</span> <i>bunches of garlic</i>. <span class=\"citation\">B. Bath. 86ᵃ</span>, v. <a href=\"#\" data-headword=\"מְסוּבְלָא\">מְסוּבְלָא</a>.</div>","alt":[]},"16985":{"h":"מְתָארָא","r":"M03009","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">מתחרא</span>, v. <a href=\"#\" data-headword=\"תַּחֲרוּ\">תַּחֲרוּ</a>; <a href=\"#\" data-headword=\"חֲרֵי\">חֲרֵי</a>; Syr. <span dir=\"rtl\">מתרא</span>, <a href=\"#\" data-headword=\"מְתוֹאֲרָא\">מתוארא</a>, P. Sm. 2256) <i>rake, poker, shovel</i>. <span class=\"citation\">Ḥag. 4ᵇ</span>, sq. <span dir=\"rtl\">הות נקיטא מ׳ בידה כ׳</span> (Ar. <span dir=\"rtl\">מתוארה</span>; En Yakob <span dir=\"rtl\">מתחרא</span>) took a shovel in hand and raked &amp;c., v. <a href=\"#\" data-headword=\"חֲרֵי\">חֲרֵי</a>. <span class=\"citation\">Gitt. 69ᵇ</span> bot. <span dir=\"rtl\">וניתי מתוארא וכ׳</span> Ar. ed. Koh. (oth. Ar. ed. <span dir=\"rtl\">מתורא</span>; ed. <a href=\"#\" data-headword=\"פְּתוֹרָא\">פתורא</a>) and let him bring a shovel and put it over them &amp;c. [Ar.: <i>a board</i>.]</div>","alt":[]},"16986":{"h":"מַתְבֵּן","r":"M03010","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>shed for straw</i> &amp;c. <span class=\"citation\">Erub. VII, 5</span>; Tosef. ib. IX (VI), 17; a. e.</div>","alt":[]},"16987":{"h":"מַתְבְּרָא","r":"M03011","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"מַשְׁבֵּר\">מַשְׁבֵּר</a>. <span class=\"citation\">Targ. II Kings XIX, 3</span>; <span class=\"citation\">Targ. Is. XXXVII, 3</span>. <span class=\"citation\">Targ. II Sam. XXII, 5</span> (h. text <span dir=\"rtl\">מִשְׁבְּרֵי</span>); <span class=\"citation\">Targ. Ps. XVIII, 5</span> (h. text <span dir=\"rtl\">חבלי</span>). <span class=\"citation\">Targ. Ex. I, 16</span> (G. ed. Dien. <a href=\"#\" data-headword=\"מַדַּע\">מִ׳</a>; h. text <span dir=\"rtl\">אבנים</span>); a. e.</div>","alt":[]},"16988":{"h":"מִתְבְּרָא","r":"M03012","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"תְּבַר\">תְּבַר</a>) <span dir=\"rtl\">מִתְבְּרִין</span></span> = b. h. <span dir=\"rtl\">מִשְׁבָּרִים</span>, <i>breakers, waves</i>. <span class=\"citation\">Targ. Ps. XLII, 8</span>.</div>","alt":[]},"16989":{"h":"מִתֵּג","r":"M03013","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מֶתֶג\">next w.</a>) <i>to bridle</i>. Pesik. Zakh., p. 24ᵇ <span dir=\"rtl\">את מְמַתְּגוֹ</span>, v. <a href=\"#\" data-headword=\"בָּלַם II\"><span dir=\"rtl\">בָּלַם</span> II</a>; <span class=\"citation\">Yalk. Deut. 938</span>; Tanḥ. ed. Bab., Ki Thetsé 6 <span dir=\"rtl\">שמתגו</span> (corr. acc.)</div>","alt":[]},"16990":{"h":"מֶתֶג","r":"M03014","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>bridle, reins</i>. <span class=\"citation\">Pirké d’R. El. ch. XXXVI</span> (ref. to <span dir=\"rtl\">מתג האמה</span>, <span class=\"citation\">II Sam. VIII, 1</span>) <span dir=\"rtl\">לקח אמה אחת ממ׳ חמור וכ׳</span> he (Isaac) took one cubit’s length of the reins of his ass, and gave it to him (Abimelech) as a sign of friendship (v. <span class=\"citation\">Targ. Y. Gen. XXVI, 31</span>).</div>","alt":[]},"16991":{"h":"מִתגָּא","r":"M03015","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXVI, 31</span> (v. <a href=\"#\" data-headword=\"מֶתֶג\">preced.</a>).—[<span class=\"citation\">Sabb. 51ᵇ</span> bot., v. <a href=\"#\" data-headword=\"מִתְנָא\">מִתְנָא</a>.]</div>","alt":["מִי׳"]},"16992":{"h":"מִתְדַּמָּרוּ","r":"M03016","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"*דְּמַר\">דְּמַר</a></div>","alt":[]},"16993":{"h":"מְתוֹאֲרָא","r":"M03017","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְתָארָא\">מתָארָא</a></div>","alt":[]},"16994":{"h":"מְתוּבִיתָא","r":"M03018","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">יְתַב</span>) <i>seat</i>. <span class=\"citation\">Targ. Jud. V, 11</span> <a href=\"#\" data-headword=\"מְתוּבִיתָא\">מְתוּבִית</a> ed. Lag. (oth. ed. <span dir=\"rtl\">מְתוּבַת</span>) constr.—V. <a href=\"#\" data-headword=\"מְתִיבָא\">מְתִיבְתָּא</a>.</div>","alt":["מְתוּבְתָּא"]},"16995":{"h":"מַתְוָויָא","r":"M03019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַתְוָיָא\">מַתְוָיָא</a></div>","alt":[]},"16996":{"h":"מַתְוָותָא","r":"M03020","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָתָא\">מָתָא</a></div>","alt":[]},"16997":{"h":"מַתְוָיָא","r":"M03021","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>; cmp. <a href=\"#\" data-headword=\"מַתְיָא\">מַתְיָא</a>) <i>being carried, desire</i>. <span class=\"citation\">Targ. Y. Gen. III, 16</span> <span dir=\"rtl\">מַתְוִיךְ</span> (h. text <span dir=\"rtl\">תשוקתך</span>). <span class=\"citation\">Ib. IV, 7</span>; a. e.</div>","alt":["מַתְוָו׳"]},"16998":{"h":"מִתּוֹךְ","r":"M03022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"תָּוֶךְ\">תָּוֶךְ</a></div>","alt":[]},"16999":{"h":"מְתוּכִילְתָּא","r":"M03023","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אֲכַל I) <i>relish, preserve</i>. <span class=\"citation\">Pes. 43ᵃ</span> קריבו לי מידי מ׳ Ms. M. (ed. <span dir=\"rtl\">קריבו לו מתכילתא</span>) bring me something to go with the meat. <span class=\"citation\">Sabb. 77ᵇ</span> (phonetic play) <span dir=\"rtl\">מ׳ מ̇ת̇י תכ̇ל̇יתא דדא</span> Ar. (ed. <span dir=\"rtl\">מתכולתא מתי תכלה דא</span>, Rashi a. Ms. O. <span dir=\"rtl\">מתוכ׳</span>; v. Rabb. D. S. a. l. note 8) <i>m.</i>, ‘when will this end?’</div>","alt":[]},"17000":{"h":"מָאִים","r":"M00024","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָא\">מָא</a>. [<span class=\"citation\">Koh. R. to VI, 1</span>; <span class=\"citation\">IX, 13</span>, v. <a href=\"#\" data-headword=\"*מָאוּז\">מָאוּז</a>.]</div>","alt":[]},"17001":{"h":"מָאִין","r":"M00025","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מַיִין\">מַיִין</a>, <i>water</i>. <span class=\"citation\">Targ. II Chr. XXXII, 4</span>; a. e.</div>","alt":[]},"17002":{"h":"מאינון","r":"M00026","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 33</span> <span dir=\"rtl\">ר׳ י׳ אומר מ׳</span> (<span class=\"citation\">Y. Sabb. II, 4ᵈ</span> bot. <a href=\"#\" data-headword=\"טיינון\">טיינון</a>), corrupt. of <span dir=\"rtl\">יאנטינון</span>, v. <a href=\"#\" data-headword=\"*אלטינון\">אלטינון</a></div>","alt":[]},"17003":{"h":"מאיס","r":"M00027","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to VI, 1</span>; <span class=\"citation\">IX, 13</span>, v. <a href=\"#\" data-headword=\"*מָאוּז\">מָאוּז</a></div>","alt":[]},"17004":{"h":"מְאִיס","r":"M00028","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְאַס\">מְאַס</a>) <i>to be sticky, soiled; to be repulsive</i> (cmp. <span dir=\"rtl\">זהם</span>). <span class=\"citation\">Targ. Ps. XXXVIII, 6</span> (Ms. <span dir=\"rtl\">איתימסיו</span>, v. <a href=\"#\" data-headword=\"מְסִבְּתָא\">מְסִי</a>).—<span class=\"citation\">B. Kam. 18ᵃ</span> <span dir=\"rtl\">דמ׳ בלישא</span> (not <span dir=\"rtl\">דמאוס</span>), v. <a href=\"#\" data-headword=\"ווּס\">ווּס</a>.—Part. <a href=\"#\" data-headword=\"מְאִיס\">מָאִיס</a>. <span class=\"citation\">Targ. Ps. LVIII, 9</span> (ed. Wil. <a href=\"#\" data-headword=\"מָאַס\">מָאַס</a>, read <a href=\"#\" data-headword=\"מָאַס\">מָאִס</a>).—<span class=\"citation\">Keth. 63ᵇ</span> <span dir=\"rtl\">מ׳ עלי</span> he is repulsive to me. <span class=\"citation\">Yoma 63ᵇ</span> <span dir=\"rtl\">משום דמ׳</span> because it is offensive (on account of blemishes).—<span class=\"citation\">Ber. 50ᵇ</span> מידי דלא מ׳ Ms. M. (ed. <span dir=\"rtl\">מִמְּאִיס</span>) something which is not sticky (the handling of which does not create aversion); a. e.—Pl. <span dir=\"rtl\">מְאִיסִין</span>, <span dir=\"rtl\">מְאִיסֵי</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 13</span> (opp. <span dir=\"rtl\">מנטלין</span>).—<span class=\"citation\">Yeb. 100ᵃ</span> <span dir=\"rtl\">משום דמ׳</span> because they (the uncircumcised and the unclean) are rejected on account of their physical condition; a. e.—<span class=\"citation\">Lam. R. to III, 45</span> (transl. <span dir=\"rtl\">סחי ומאוס</span>, ib.) <span dir=\"rtl\">מְאִסַיָּיא פְּסִילַיָּיא</span> loathsome, outcasts, v. <a href=\"#\" data-headword=\"פְּסִילָא\">פְּסִילָא</a>.</div><div class=\"sense\"><b>Ithpe. אִמְּאִיס</b> <div class=\"sense\"><i>to become repulsive, to decay</i>. <span class=\"citation\">Ber. 50ᵇ</span>, v. supra. <span class=\"citation\">Pes. 28ᵃ</span> חמץ דמִמְּאִיס Ms. M. 1 (Ms. M. 2 <span dir=\"rtl\">דמאיס</span>; ed. <span dir=\"rtl\">דמִמִּיס</span>) leavened matter which decays in course of time; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ע&quot;א דלא ממאיס</span> Ms. M. 1 (Ms. M. 2 <a href=\"#\" data-headword=\"מְאִיסָה\">מאיסה</a>; ed. <span dir=\"rtl\">מִמִּיסָה</span>, v. Rabb. D. S. a. l. note) an idolatrous object which is not subject to decay.</div></div>","alt":[]},"17005":{"h":"מְאִיסָה","r":"M00029","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָאַס\">מָאַס</a>) <i>rejection, contempt; use of the verb</i> <a href=\"#\" data-headword=\"מָאַס\">מָאַס</a>. <span class=\"citation\">Lam. R. to V, 20</span>; <span class=\"citation\">Pesik. R. s. 31</span>; <span class=\"citation\">Yalk. Is. 332</span>. <span class=\"citation\">Lam. R. to V, 22</span> (ref. to <span dir=\"rtl\">מאס</span> ib.) <span dir=\"rtl\">אם מ׳ לית היא סבר וכ׳</span> if it be a rejection, there is no hope (of a reconciliation), but if it be anger, there is hope.</div>","alt":[]},"17006":{"h":"מְאִיסוּתָא","r":"M00030","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a>) <i>repulsiveness</i>. <span class=\"citation\">Men. 69ᵃ</span> משום מ׳ הוא … אזדא למְאִיסוּתַיְהוּ וכ׳ Ms. R. (ed. <span dir=\"rtl\">דמאיסותא</span></div>","alt":[]},"17007":{"h":"מֵאִיר","r":"M00031","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Meïr</i>, esp. R. M., a renowned Tannai, disciple of R. Akiba and of Elisha ben Abuya (v. Fr. Darkhe Mish., p. 154, a. <a href=\"#\" data-headword=\"אֶלִישָׁע\">אֱלִישָׁע</a>). <span class=\"citation\">Erub. 13ᵇ</span> <span dir=\"rtl\">לא ר׳ מ׳ שמו אלא ר׳ מיישא שמו</span> (v. Rabb. D. S. a. l. note) his name was not R. M. but R. Maysha. <span class=\"citation\">Hor. 13ᵇ</span>, v. <a href=\"#\" data-headword=\"אַחֵר\">אַחֵר</a>. <span class=\"citation\">Gen. R. s. 9</span>, a. fr. <span dir=\"rtl\">בתורתו של ר׳ מ׳</span> in R. M.’s copy of the Pentateuch. <span class=\"citation\">Ḥull. IV, 4</span>; a. v. fr.</div>","alt":[]},"17008":{"h":"מְאֵירָה","r":"M00032","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מְאֵר׳</span>.</div>","alt":["מְאֵירְתָּא"]},"17009":{"h":"מַאיְשָׁא","r":"M00033","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵישָׁא II\"><span dir=\"rtl\">מֵישָׁא</span> II</a></div>","alt":[]},"17010":{"h":"מָאִית","r":"M00034","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּת\">מוּת</a></div>","alt":[]},"17011":{"h":"מָאַךְ","r":"M00035","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a></div>","alt":[]},"17012":{"h":"מְאַךְ","r":"M00036","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>) <i>to sink; to be humbled</i>. <span class=\"citation\">Targ. Jud. VI, 6</span>. <span class=\"citation\">Targ. Is. II, 9</span>. <span class=\"citation\">Ib. XXV, 5</span> <span dir=\"rtl\">יִמְאֲכוּן</span> (ed. Ven. <span dir=\"rtl\">יִמָ׳</span>; ed. Wil. <span dir=\"rtl\">ימאסון</span>, corr. acc.). <span class=\"citation\">Ib. XXIX, 4</span>; a. fr.</div><div class=\"sense\"><b>Af. אַמְאֵיךְ</b> <div class=\"sense\"><b>1)</b> <i>to lower, humble</i>. Ib. LI, 23; a. fr.—<span class=\"citation\">Targ. Ps. XLIV, 20</span> אַמְאַכְ׳ Ms. (ed. <a href=\"#\" data-headword=\"אֲמַךְ\">אֲמַכְ׳</a>, v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>).</div><div class=\"sense\"><b>—2)</b> <i>to lower one’s self, bow down</i>. Targ. Is. l. c.</div></div><div class=\"sense\"><b>Pa. מָאֵיךְ  מָאַךְ</b> <div class=\"sense\"><i>to lower, humble</i>. Ib. XXV, 5. Ib. XXVI, 5 Levita (ed. <i>Af</i>.). <span class=\"citation\">Targ. Job XVII, 13</span>. <span class=\"citation\">Targ. Ps. CXLVII, 6</span> Ms. (ed. <a href=\"#\" data-headword=\"מַכִּיךְ\">מַכִּיךְ</a>, v. <a href=\"#\" data-headword=\"מְכַךְ\">מְכַךְ</a>). <span class=\"citation\">Targ. Prov. XXIX, 11</span> ed. Wil. [read:] <span dir=\"rtl\">מֵאֲכָהּ</span> lowers it (appeases the fool’s anger), v. <a href=\"#\" data-headword=\"חֲשֵׁב\">חֲשֵׁב</a>.</div></div>","alt":[]},"17013":{"h":"מָאכָא","r":"M00037","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָכָא\">מָכָא</a></div>","alt":[]},"17014":{"h":"מַאֲכוֹלֶת","r":"M00038","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָכַל\">אָכַל</a>) </div><div class=\"sense\"><b>1)</b> <i>louse</i>. <span class=\"citation\">Nidd. 14ᵃ</span>. <span class=\"citation\">Ib. 52ᵇ</span>. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 21</span>; <span class=\"citation\">Sabb. 12ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מַאֲכוֹלֶת\">מַאֲכוֹלוֹת</a>. <span class=\"citation\">Y. Nidd. II, 49ᵈ</span> bot. (ed. Krot. sing.).</div><div class=\"sense\"><b>—2)</b> <i>wood-worm</i>.—<i>Pl.</i> as ab. <span class=\"citation\">Y. Taan. IV, 69ᶜ</span> <span dir=\"rtl\">אינן עושין מ׳</span> do not produce worms (are never worm-eaten); Lam. R. introd. (R. Z’era) <span dir=\"rtl\">לֶת …</span> (sing.).</div>","alt":[]},"17015":{"h":"מַאֲכָל","r":"M00039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>food; meal; meal-time</i>. <span class=\"citation\">Sabb. 10ᵃ</span>; <span class=\"citation\">Pes. 12ᵇ</span> <span dir=\"rtl\">מַאֲכַל לודים</span>, v. <a href=\"#\" data-headword=\"לוּדִים\">לוּדִים</a>. <span class=\"citation\">Ber. 40ᵃ</span> <span dir=\"rtl\">אסור … עד שיתן מ׳ לבהמתו</span> a person is forbidden to eat before giving food to his animal. <span class=\"citation\">Taan. 20ᵃ</span> <span dir=\"rtl\">מ׳ אדם</span> food fit for human beings; a. fr.—[<span class=\"citation\">Y. Ḥag. II, end, 78ᶜ</span> <span dir=\"rtl\">אפי׳ מ׳ אפי׳ כסות</span>, read: <span dir=\"rtl\">אפי׳ מובל אפי׳ כפות</span>, v. <a href=\"#\" data-headword=\"יָבַל I\">יָבַל</a>.]—Pl. <span dir=\"rtl\">מַאֲכָלוֹת</span>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">שתהא אוכל מ׳ כאדם</span> that thou shouldst eat food like human beings; (<span class=\"citation\">Tosef. Sot. IV, 17</span> <span dir=\"rtl\">מעדנים</span>, Var. <span dir=\"rtl\">מאכל אדם</span>).</div>","alt":[]},"17016":{"h":"מַאֲכֶלֶת","r":"M00040","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>preparing food</i>,] <i>slaughtering knife</i>. <span class=\"citation\">Gen. R. s. 56</span>, v. <a href=\"#\" data-headword=\"כָּשֵׁר I\"><span dir=\"rtl\">כָּשֵׁר</span> I</a>. <span class=\"citation\">Pirké d’R. El. ch. XXXI</span>. <span class=\"citation\">Pesik. R. s. 40</span>. Gen. R. l. c. <span dir=\"rtl\">בזכות אותה המ׳</span> through the merit of (taking up) that knife (<span class=\"citation\">Gen. XXII, 10</span>).</div>","alt":[]},"17017":{"h":"מאכסני","r":"M00041","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XXIV, 25</span>, v. <a href=\"#\" data-headword=\"מַכְסָנָא\">מַכְסָנָא</a>.</div>","alt":[]},"17018":{"h":"מְאַלְלָא","r":"M00042","html":"<div class=\"sense\">, m. (<a href=\"#\" data-headword=\"אֲלַל\">אֲלַל</a>) <i>spy</i>.—Pl. <span dir=\"rtl\">מְאַלְלַיָּא</span>, <span dir=\"rtl\">מְאַלְלִין</span>. <span class=\"citation\">Targ. Josh. II, 1</span>. <span class=\"citation\">Targ. O. Num. XXI, 2</span>; a. fr.</div>","alt":[]},"17019":{"h":"מֶאמֶל","r":"M00043","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Maasr. I, 7</span> ed. Zuck., v. <a href=\"#\" data-headword=\"מֶמֶל\">מֶמֶל</a></div>","alt":[]},"17020":{"h":"מַאֲמָר","r":"M00044","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>command, order.</i> <span class=\"citation\">Ab. V, 1</span> <span dir=\"rtl\">והלא במ׳ אחד וכ׳</span> could not the universe have been created by one divine command?—<span class=\"citation\">Meg. 21ᵇ</span>; <span class=\"citation\">R. Hash. 32ᵃ</span> <span dir=\"rtl\">בראשית נמי מ׳ הוא</span> the first verse of Genesis is also to be considered a command. <span class=\"citation\">Gen. R. s. 4</span> <span dir=\"rtl\">המים … תלוים במ׳</span> the upper waters are suspended (in the air) by a divine ordainment; <span class=\"citation\">Taan. 10ᵃ</span>.—<span class=\"citation\">Sabb. 63ᵃ</span> <span dir=\"rtl\">העושה מצוה כמַאֲמָרָהּ</span> who executes a divine command as it has been ordained; a. e.—Pl. <span dir=\"rtl\">מַאֲמָרוֹת</span>. Ab. l. c. <span dir=\"rtl\">בעשרה מ׳ וכ׳</span> the world was created by ten divine orders (counting nine <span dir=\"rtl\">ויאמר</span> in <span class=\"citation\">Gen. ch. I</span>, and the first verse, v. supra).</div><div class=\"sense\"><b>—2)</b> <i>word</i>, esp. <i>maămar, the Yabam’s betrothal</i> (v. <a href=\"#\" data-headword=\"יָבָם\">יָבָם</a>) by word of mouth, contrad. to the consummation of marriage <a href=\"#\" data-headword=\"בִּיָּא\">(בִּיאָה</a>). <span class=\"citation\">Yeb. II, 1</span> <span dir=\"rtl\">עשה בה מ׳</span> if he betrothed her to himself; Y. ib. 3ᶜ <span dir=\"rtl\">איזו היא מ׳ וכ׳</span> what is a <i>maămar</i> with regard to a <i>Y’bamah</i>? Saying, ‘Be betrothed unto me’, while handing to her money or money’s worth. Ib. <span dir=\"rtl\">מ׳ גומר</span> betrothal consummates the <i>yabam’s</i> marriage (carrying with it all the legal consequences of his marriage), v. <a href=\"#\" data-headword=\"גָּמַר I\">גָּמַר</a>; a. v. fr.</div>","alt":[]},"17021":{"h":"מַאֲמָרָא","r":"M00045","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"מַאֲמָר\">מַאֲמַר</a> ch. same, <i>word, sentence</i>. <span class=\"citation\">Targ. Prov. XVI, 24</span>. <span class=\"citation\">Targ. Cant. V, 13</span>; a. e.—Pl. <span dir=\"rtl\">מַאֲמָרַיָּא</span>, constr. <span dir=\"rtl\">מַאֲמָרֵי</span>. <span class=\"citation\">Targ. Prov. IV, 5</span> (ed. Lag. <span dir=\"rtl\">מַאֲמָרַיָּה ד־</span>).</div>","alt":[]},"17022":{"h":"מָאַן","r":"M00046","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">מֵיאֵן</span>, <span dir=\"rtl\">מֵאֵן</span> (b. h.; v. <a href=\"#\" data-headword=\"אֵין\">אֵין</a>) <i>to deny, refuse</i>, esp. </div><div class=\"sense\"><b>1)</b>  (of a woman betrothed in childhood, on arriving at majority) <i>to protest against, to annul one’s marriage</i>. <span class=\"citation\">Yeb. XIII, 1</span> <span dir=\"rtl\">אין מְמָאֲנִין אלא ארוסות</span> only betrothed (not married) women may have their obligation cancelled. Ib. <span dir=\"rtl\">מְמָאֶנֶת והיא קטנה וכ׳</span> she may protest (have her marriage cancelled) even while yet a minor, and even four or five times in succession. Ib. 2 <span dir=\"rtl\">איזו … שצריכה למָאֵן</span> what minor is bound to make declaration (before leaving her husband)?—Ib. 4 <span dir=\"rtl\">הממאנת באיש וכ׳</span> if a woman refuses her husband by declaration, he is permitted to marry her kindred (who otherwise would be forbidden to him); a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to advise a protest.</i> <span class=\"citation\">Eduy. VI, 1</span> <span dir=\"rtl\">שמְמָאֲנִים וכ׳</span> that the court eventually advises women married as minors to protest; <span class=\"citation\">Nidd. 8ᵃ</span>; <span class=\"citation\">Ber. 27ᵃ</span>.—V. <a href=\"#\" data-headword=\"מִיאוּן\">מִיאוּן</a>.</div>","alt":[]},"17023":{"h":"מַאן","r":"M00047","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מָא\">מָא</a>) <i>who?, what?, which?;</i> (relat.) <i>who, which</i>. [Targ. <a href=\"#\" data-headword=\"מַן\">מַן</a>.] <span class=\"citation\">Sabb. 57ᵃ</span>, a. fr. <span dir=\"rtl\">מ׳ דכר וכ׳</span>, v. <a href=\"#\" data-headword=\"דְּכַר I\"><span dir=\"rtl\">דְּכַר</span> I</a>. <span class=\"citation\">Yeb. 107ᵇ</span> <span dir=\"rtl\">מ׳ לא הודו לו</span> who is meant by ‘they did not agree with him’? Ib., a. fr. <span dir=\"rtl\">מ׳ תנא</span> who is the authority for the law just quoted?, i.e. whose opinion is here represented?—<span class=\"citation\">Ḥull. 50ᵃ</span> <span dir=\"rtl\">אמר מ׳ דהו</span> somebody said; <span class=\"citation\">Bets. 27ᵃ</span>; <span class=\"citation\">M. Kat. 22ᵃ</span>; (<span class=\"citation\">Nidd. 48ᵃ</span> <span dir=\"rtl\">ר׳ זירא</span>). <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> <span dir=\"rtl\">פוק חזי מ׳ בעי וכ׳</span> go out and see who it is that wants thee outside (an intimation of a teacher’s displeasure); <span class=\"citation\">Gen. R. s. 33</span> (some ed. <a href=\"#\" data-headword=\"מַן\">מַן</a>). <span class=\"citation\">Ber. 30ᵇ</span>; <span class=\"citation\">Ḥull. 7ᵃ</span> <span dir=\"rtl\">חזי מ׳ גברא וכ׳</span> see how great a man gives testimony about him. <span class=\"citation\">Y. Maas. Sh. II, 53ᵇ</span> bot. <span dir=\"rtl\">מ׳ דאמר וכ׳</span> according to him who says &amp;c.; a. v. fr.—V. <a href=\"#\" data-headword=\"מַן\">מַן</a>.</div>","alt":[]},"17024":{"h":"מָאן","r":"M00048","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַאן\">preced.</a>) [<i>thing</i>,] </div><div class=\"sense\"><b>1)</b> <i>vessel, utensil</i>. <span class=\"citation\">Targ. Ps. II, 9</span>. <span class=\"citation\">Targ. Lev. XI, 33</span>; a. fr. (interch. with <a href=\"#\" data-headword=\"מָאן\">מָן</a>, <a href=\"#\" data-headword=\"מַן\">מַן</a>).—<span class=\"citation\">B. Kam. 17ᵇ</span> <span dir=\"rtl\">מ׳ תבירא תבר</span> it was a broken vessel he broke. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בתר תבר מ׳ אזלינן</span> we judge by the final cause by which the vessel was broken; a. v. fr.—Pl. <span dir=\"rtl\">מָאנִין</span>, <span dir=\"rtl\">מָאנַיָּא</span>, <a href=\"#\" data-headword=\"מָנֵי\">מָאנֵי</a>, <a href=\"#\" data-headword=\"מוּנְיָיק\">מָנ׳</a>. <span class=\"citation\">Targ. Ex. XI, 2</span>; a. fr.—<span class=\"citation\">Sabb. 105ᵇ</span> <span dir=\"rtl\">תבר מ׳ תבירי</span> broke broken vessels (pretending to be angry); a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כְּלִי\">כֶּלִי</a>) <i>garment, dress</i>. Ib. 113ᵇ; <span class=\"citation\">Snh. 94ᵃ</span> <span dir=\"rtl\">קרי למָאנֵיה וכ׳</span> called his dress (garments) &amp;c., v. <a href=\"#\" data-headword=\"כָּבֵד I\"><span dir=\"rtl\">כָּבֵד</span> I</a>; <span class=\"citation\">B. Kam. 91ᵇ</span> <span dir=\"rtl\">למאני</span> (corr. acc.; v. Rabb. D. S. a. l.).—<span class=\"citation\">B. Mets. 47ᵃ</span> <span dir=\"rtl\">במ׳ דכשר למקני ביה</span> (symbolical possession has been given) by means of a garment fit for the purpose; a. fr.—<i>Pl.</i> as ab. <span class=\"citation\">Ber. 6ᵃ</span>. <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> top <span dir=\"rtl\">מָאנוֹי</span>, v. <a href=\"#\" data-headword=\"בְּזַע\">בְּזַע</a>; a. fr.</div><div class=\"sense\"><b>—3)</b>  (= h. <a href=\"#\" data-headword=\"קַנְקָן I\">קַנְקַן</a>) [<i>handle</i>,] <i>coulter of the plough</i>. <span class=\"citation\">B. Mets. 80ᵃ</span></div>","alt":["מַאן","מָאנָא","מָן","מָנָא"]},"17025":{"h":"מָאַס","r":"M00049","html":"<div class=\"sense\"> [<i>to melt, faint</i>,] (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to be tired of, loathe;</i> (with accus.) <i>to cast away, reject</i>. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">אין הקב&quot;ה מוֹאֵס בתפלתו וכ׳</span> the Lord never tires of the prayer of assemblies. Sifra <span class=\"citation\">B’ḥuck. ch. III</span>, Par. 2 <span dir=\"rtl\">מואס באחרים</span> despises others (for being his betters); (ib. <span dir=\"rtl\">מואס אחרים</span>, corr. acc.). Tanḥ. <span class=\"citation\">Mishp. 11</span> <span dir=\"rtl\">כבר מָאֲסָן וכ׳</span> their god has rejected them; <span class=\"citation\">Ex. R. s. 31</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אמת שמָאַסְתָּ וכ׳</span> is it true that thou hast rejected thy son?; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מָאוּס\">מָאוּס</a>, f. <a href=\"#\" data-headword=\"מִאוּס\">מְאוּסָה</a>; pl. <span dir=\"rtl\">מְאוּסִים</span>, <span dir=\"rtl\">מְאוּסִין</span>; <span dir=\"rtl\">מְאוּסוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. LXXV, 9</span> (play on <span dir=\"rtl\">כמס</span>, <span class=\"citation\">Deut. XXXII, 34</span>) <span dir=\"rtl\">כמוס למאוסים</span> reserved for the rejected (nations; differ. in <span class=\"citation\">Sifré Deut. 324</span>). <span class=\"citation\">Der. Er. ch. II</span> <span dir=\"rtl\">המ׳ בעיניהם</span> those who are despised in their own eyes (think little of themselves); a. e.</div><div class=\"sense\"><b>Nif. נִמְאָס</b> <div class=\"sense\"><i>to be repulsive, loathsome; to be rejected</i>. Sifra B’ḥuck. Par. 2, ch. VIII (ref. to <span class=\"citation\">Lev. XXVI, 44</span>) <span dir=\"rtl\">וכי … שלא נִמְאֲסוּ ושלא נגעלו</span> what has been left to them so that (it might be said) they were not cast away and loathed?; <span class=\"citation\">Yalk. Lev. 675</span> (corr. acc.). <span class=\"citation\">Ḥag. 5ᵃ</span> <span dir=\"rtl\">ונ׳</span> and becomes loathsome (creates aversion to his neighbor).—V. <a href=\"#\" data-headword=\"מִיאוּס\">מִיאוּס</a>.</div></div>","alt":[]},"17026":{"h":"מְאַס","r":"M00050","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. XXVI, 44</span>; a. e.—V. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a>.</div><div class=\"sense\"><b>Ithpa. אִתְמָאַס</b> <div class=\"sense\"><i>to melt, faint</i>. <span class=\"citation\">Targ. Ps. LVIII, 8</span> Ms. (ed. <span dir=\"rtl\">יתמסון</span>).</div></div><div class=\"sense\"><b>Ithpe. אִמְּאִיס</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a></div></div>","alt":[]},"17027":{"h":"מָאָס","r":"M00051","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְאַס\">preced.</a>) <i>rejection, contempt</i>. Lam. R. introd. (R. Abba 2) <span dir=\"rtl\">מָאֲסָהּ של תורה</span> the contempt of the Law; (<span class=\"citation\">Y. Ḥag. I, 76ᶜ</span> <span dir=\"rtl\">על מאסם בתורה</span>).</div>","alt":[]},"17028":{"h":"מְאַסָּא","r":"M00052","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲסִי\">אֲסִי</a>) <i>healer</i>. <span class=\"citation\">Targ. Job XXXI, 18</span> Var. Ms. (ed. <a href=\"#\" data-headword=\"כְּאֵבָא\">כְּאַבָּא</a>, Ms. <a href=\"#\" data-headword=\"כְּאֵבָא\">כְּאֵבָא</a>).—Pl. <span dir=\"rtl\">מְאַסֵּין</span>, constr. <span dir=\"rtl\">מְאַסֵּי</span>. <span class=\"citation\">Ib. XIII, 4</span> <span dir=\"rtl\">כִּמְאֲסֵּי</span> (not <span dir=\"rtl\">כִּמְאֲסֵי</span>).</div>","alt":[]},"17029":{"h":"מאסאסה","r":"M00053","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסָּאסָא\">מַסָּאסָא</a></div>","alt":[]},"17030":{"h":"מָאִסַיָּא","r":"M00054","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a></div>","alt":["מָאִסַיָּיא"]},"17031":{"h":"מאספוטמיא","r":"M00055","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְפַּמְיָא\">אִסְפַּמְיָא</a></div>","alt":[]},"17032":{"h":"מַאֲפֶה","r":"M00056","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>something baked, batch</i>. <span class=\"citation\">Men. V, 9</span> <span dir=\"rtl\">מַאֲפֵּה כופח</span>, v. <a href=\"#\" data-headword=\"כּוּפָּח\">כּוּפָּח</a>. <span class=\"citation\">Erub. VII, 10</span> <span dir=\"rtl\">אפי׳ מ׳ סאה והיא פרוסה</span> even a batch of a S’ah but consisting of broken pieces; Y. ib. VI, 23ᵈ top. <span class=\"citation\">Ab. Zar. 35ᵇ</span>, v. <a href=\"#\" data-headword=\"פּוּרְנִי\">פּוּרְנִי</a>.</div>","alt":[]},"17033":{"h":"מַאֲפֵי","r":"M00057","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. II, 4</span> ed. Berl. (oth. ed. … <span dir=\"rtl\">פֵה</span>, … <span dir=\"rtl\">פָה</span>).</div>","alt":[]},"17034":{"h":"מַאֲפֵל","r":"M00058","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>darkness</i>. Tanḥ. B’midb. 2 <span dir=\"rtl\">לא אני … מַאֲפֵלְכֶם</span> did I not myself illumine your darkness?</div>","alt":[]},"17035":{"h":"מַאְפֵּלְיָה","r":"M00059","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מַאֲפֵל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>darkness, gloom</i>. <span class=\"citation\">Yalk. Jer. 267</span> (ref. to <span class=\"citation\">Jer. II, 31</span>) <span dir=\"rtl\">שמא … שהיא נאה והיא ארץ מ׳</span> did I tell them that it was a beautiful land, and it was a land of gloom?</div><div class=\"sense\"><b>—2)</b>  (homil.) <i>lateness, procrastination</i>. Ib. <span dir=\"rtl\">ד&quot;א מאפילה שמא וכ׳</span> (corr. acc.) another interpretation; did I promise to bring you good things and procrastinate it? <span dir=\"rtl\">ואין מ׳ אלא לשון הלקשה</span>, v. <a href=\"#\" data-headword=\"הַלְקָשָׁה\">הַלְקָשָׁה</a>; Tanḥ. B’midb. 2; Masé 9; <span class=\"citation\">Num. R. s. 1</span>; s. 23; <span class=\"citation\">Yalk. Num. 683</span>.</div>","alt":[]},"17036":{"h":"מָאר","r":"M00060","html":"<div class=\"sense\"><i>lord</i>, v. <a href=\"#\" data-headword=\"מַר IV\"><span dir=\"rtl\">מַר</span> IV</a>.</div>","alt":["מָארָא"]},"17037":{"h":"מְאֵרָה","r":"M00061","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>curse, evil; decrease, destruction</i>, opp. <a href=\"#\" data-headword=\"בְּרָכָה\">בְּרָכָה</a>. <span class=\"citation\">Ber. 20ᵇ</span> <span dir=\"rtl\">תבא מ׳ וכ׳</span> curse (poverty) will come upon him &amp;c.; <span class=\"citation\">Y. Dem. II, 22ᵈ</span> bot.; <span class=\"citation\">Y. Peah V, end, 19ᵃ</span>. <span class=\"citation\">Y. Snh. X, 28ᵇ</span>; ib. 29ᵈ <span dir=\"rtl\">נשלטה בהן מ׳</span> (not <span dir=\"rtl\">ושלטה</span>) curse (poverty) was given power over them. Tanḥ. <span class=\"citation\">B’resh. 11</span> <span dir=\"rtl\">מה אנו מולידות למ׳</span> why should we give birth for curse (to see our offspring perish)?; <span class=\"citation\">Gen. R. s. 23</span>. <span class=\"citation\">Gen. R. s. 34</span>.—Sifra Thazr., Par. 5, ch. XIV (ref. to <span dir=\"rtl\">ממארת</span>, <span class=\"citation\">Lev. XIII, 51</span>) <span dir=\"rtl\">תן בו מ׳ וכ׳</span> put a curse on it (the garment) that no use be made thereof. <span class=\"citation\">Bets. 15ᵇ</span> <span dir=\"rtl\">הללו בעלי מ׳</span> these (being the last to leave) are poor men. <span class=\"citation\">Tosef. Kidd. I, 11</span> <span dir=\"rtl\">תהא לה מ׳</span> (Var. <a href=\"#\" data-headword=\"מוֹר ²\">מורא</a>) she will be cursed; a. fr.—Pl. <span dir=\"rtl\">מְאֵרוֹת</span>, <a href=\"#\" data-headword=\"מְאֵרָה\">מְאֵי׳</a>. <span class=\"citation\">Tosef. B. Bath. VI, 2</span> <span dir=\"rtl\">עשר מ׳ למאה</span> (ed. Zuck. <span dir=\"rtl\">מרים לסאה</span>) ten <i>spoiled</i> (bitter) pumpkins out of each hundred.</div>","alt":["מְאֵי׳"]},"17038":{"h":"*מַאֲרוֹפָה","r":"M00062","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ארף</span>, dial. for <span dir=\"rtl\">גרף</span> or <span dir=\"rtl\">חרף</span>; v. <a href=\"#\" data-headword=\"מַגְרֵיף\">מַגְרֵיפָה</a> a. <a href=\"#\" data-headword=\"חָרוֹפָה\"><a href=\"#\" data-headword=\"חָרוֹפָה\">חָרוֹפָה</a>)</a><i>shovel, rake</i>.—Pl. <span dir=\"rtl\">מַאֲרוֹפוֹת</span>. <span class=\"citation\">Shebi. V, 4</span> ed. (Ms. M. <span dir=\"rtl\">חָרוֹפוֹת</span>).</div>","alt":[]},"17039":{"h":"מָארֵי","r":"M00063","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַר IV\"><span dir=\"rtl\">מַר</span> IV</a></div>","alt":[]},"17040":{"h":"מָארִי","r":"M00064","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"מָרִי\">מָרִי</a></div>","alt":[]},"17041":{"h":"מַאֲרִיסָא","r":"M00065","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרַס\">אֲרַס</a>) = <a href=\"#\" data-headword=\"אָרִיס\">אֲרִיסָא</a>, <i>tenant</i>. <span class=\"citation\">Lev. R. s. 5</span>, end <span dir=\"rtl\">דוד מ׳ טבא הוה</span> David was a smart tenant (that knows how to persuade the landlord to reduce the rent).</div>","alt":[]},"17042":{"h":"מָאַרְכָן","r":"M00066","html":"<div class=\"sense\"> = <span dir=\"rtl\">מָה אַרְכָן</span>. Mekh. B’shall., Vayassa, s. 1, v. <a href=\"#\" data-headword=\"אַרְכָן II\"><span dir=\"rtl\">אַרְכָן</span> II</a></div>","alt":[]},"17043":{"h":"מְאָרַע","r":"M00067","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אֲרַע I, v. <a href=\"#\" data-headword=\"מְאוֹרָע\">מְאוֹרָע</a>) <i>that which is struck against, object of attack, mark</i>. <span class=\"citation\">Targ. Job VII, 20</span> (h. text <span dir=\"rtl\">מפגע</span>).</div>","alt":[]},"17044":{"h":"מְאָרְעָא","r":"M00068","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"מְאָרַע\">מְאָרַע</a>, <span dir=\"rtl\">מְאַ׳</span>, <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מְעַ׳</a>, <a href=\"#\" data-headword=\"מ׳\">מ׳</a> m. (אֲרַע II) <span dir=\"rtl\">מ׳ קדיש</span> <i>holy convocation, festival</i>. <span class=\"citation\">Targ. O. Lev. XXIII, 3</span>; <span class=\"citation\">8</span> <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מְעֲ׳</a>, <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מְעָ׳</a> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מֵעַ׳</a>); Y. <span dir=\"rtl\">מא׳</span>; a. fr.—Pl. constr. <span dir=\"rtl\">מֵאַרְעֵי</span>, <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מֵעַ׳</a>. Ib. 4; a. fr.</div>","alt":["מְעָרְעָא"]},"17045":{"h":"מָאשֵׁי","r":"M00069","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשֵׁי\">מְשִׁי</a></div>","alt":[]},"17046":{"h":"מָאתָא","r":"M00070","html":"<div class=\"sense\"><i>town</i>, v. <a href=\"#\" data-headword=\"מָתָא\">מָתָא</a>.</div>","alt":[]},"17047":{"h":"מָאתַיִן","r":"M00071","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְאָה\">מְאָה</a></div>","alt":["מָאתָן"]},"17048":{"h":"מַבָּאנָא","r":"M00072","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְבִינָא\">מְבִינָא</a></div>","alt":[]},"17049":{"h":"מַבְגַּאי","r":"M00073","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mabgay</i>, a Samaritan name. <span class=\"citation\">Macc. 11ᵃ</span>; <span class=\"citation\">Gen. R. s. 80</span> <a href=\"#\" data-headword=\"מַגְבַּאי\">(מגבאי</a>), v. <a href=\"#\" data-headword=\"גְּזַר\">גְּזַר</a>.—<span class=\"citation\">Erub. 64ᵇ</span>; <span class=\"citation\">Tosef. Pes. I</span> (<span class=\"citation\">II), 27</span> <span dir=\"rtl\">מ׳ שמני</span> my name is M.</div>","alt":["מַבְגַּיי"]},"17050":{"h":"מְבַהֲתָנָא","r":"M00074","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּהַת\">בְּהַת</a>) <i>causing shame, degenerate</i>. <span class=\"citation\">Targ. Prov. X, 5</span>; <span class=\"citation\">XVII, 2</span>; a. e.</div>","alt":[]},"17051":{"h":"מָבוֹא","r":"M00075","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">מְבוֹאוֹת</span>, v. <a href=\"#\" data-headword=\"מָבוֹי\">מָבוֹי</a>.</div>","alt":[]},"17052":{"h":"מְבוֹאָה","r":"M00076","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"מָבוֹי\">מָבוֹי</a>. <span class=\"citation\">Erub. 15ᵃ</span>. <span class=\"citation\">B. Bath. 21ᵇ</span> <span dir=\"rtl\">בר מ׳</span> the inmate (of a building) in an alley. <span class=\"citation\">Keth. 77ᵇ</span> <span dir=\"rtl\">ההיא מ׳</span> (fem.).</div>","alt":[]},"17053":{"h":"מָבוֹג","r":"M00077","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mabog</i>. <span class=\"citation\">Zeb. 9ᵇ</span></div>","alt":[]},"17054":{"h":"מָבוֹי","r":"M00078","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>entrance, gate</i>, esp. <i>entrance to a group of buildings, alley, lane</i>. <span class=\"citation\">Erub. I, 1</span> <span dir=\"rtl\">מ׳ שהוא גבוה וכ׳</span> an entrance the joist over which lies higher than &amp;c. <span class=\"citation\">Ib. 8ᵇ</span> <span dir=\"rtl\">מ׳ העשוי כנדל</span> an alley formed like a polyp (with side entrances beside the main gateway). <span class=\"citation\">Tosef. ib. I, 2</span> <span dir=\"rtl\">מ׳ שיש לו צורת פתח</span> an alley which has the shape of a gate (archway); a. fr.—Pl. <span dir=\"rtl\">מְבוֹאוֹת</span> (fem.). <span class=\"citation\">B. Bath. 21ᵇ</span> <span dir=\"rtl\">בני מ׳</span> inmates of the same alley. Y. Ber. II, 4ᵇ top <span dir=\"rtl\">מ׳ המטונפות</span> filthy alleys; a. fr.</div>","alt":[]},"17055":{"h":"מַבּוּל","r":"M00079","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> Del. Proleg., p. 122) <i>decay, destruction</i>. <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">מפני המ׳</span> in order to accelerate the decay (of my body in the ground; Midr. Haggad. <span dir=\"rtl\">המוחל</span>). <span class=\"citation\">Snh. 108ᵇ</span> <span dir=\"rtl\">מ׳ של אש</span> a destruction by fire; <span dir=\"rtl\">מ׳ של מים</span> by water; <span class=\"citation\">Gen. R. s. 39</span>. <span class=\"citation\">Tosef. Taan. III</span> (<span class=\"citation\">II), 1</span> <span dir=\"rtl\">מ׳ של כל בשר</span> a destruction of all flesh (flood, <span class=\"citation\">Gen. IX, 11</span>) ; <span dir=\"rtl\">מ׳ של בשר</span> ed. Zuck. (Var. <span dir=\"rtl\">מ׳ של יחידים</span>) of individuals; ib. <span dir=\"rtl\">זה הוא מַבּוּלוֹ</span> this (drowning) is his <i>mabbul</i> (v. infra); <span dir=\"rtl\">מ׳ של דבר</span> an epidemic.—Esp. (<a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a>) <i>the flood</i> of Noah’s days. <span class=\"citation\">Snh. X, 3</span>, v. <a href=\"#\" data-headword=\"דּוֹר\">דּוֹר</a>. <span class=\"citation\">Gen. R. s. 31</span> <span dir=\"rtl\">אנשי המ׳</span> the men of the flood-period; a. v. fr.</div>","alt":[]},"17056":{"h":"מַבּוּלָא","r":"M00080","html":"<div class=\"sense\"> Targ. <span class=\"citation\">Hab. III, 6</span>; a. e.—<span class=\"citation\">Gen. R. s. 33</span> לא טפת … במ׳ Palestine was not submerged during the flood; <span class=\"citation\">Cant. R. to IV, 1</span>. <span class=\"citation\">Gen. R. s. 32</span>, v. <a href=\"#\" data-headword=\"טוּף\">טוּף</a> ch.; a. fr.</div>","alt":[]},"17057":{"h":"מַבּוּעַ","r":"M00081","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>well, spring</i>. <span class=\"citation\">Koh. R. to XII, 7</span> (ref. to Koh. ib. 6) <span dir=\"rtl\">כדו של … על מַבּוּעוֹ וכ׳</span> the (drawing) pitcher of Barukh over the well (of prophecy) of Jeremiah: <span dir=\"rtl\">כדו … על מבועו של ברוך</span> the (pouring) pitcher of Jeremiah over the well (of inspiration) of Barukh; Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>).—Pl. <span dir=\"rtl\">מַבּוּעִים</span>, <span dir=\"rtl\">מַבּוּעִין</span>. Mekh. B’shall., Vayassa, s. 1; <span class=\"citation\">Yalk. Ex. 257</span>; a. e.</div>","alt":[]},"17058":{"h":"מַבּוּעַ ²","r":"M00082","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XVIII, 14</span> (ed. Wil. <span dir=\"rtl\">מַבּוּעֵי</span> <i>pl.</i>). <span class=\"citation\">Targ. Prov. XIV, 27</span>; a. e.—<span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> <span dir=\"rtl\">הא מ׳ וכ׳</span> the well is before thee, drink! (i.e. do what you please, I shall not assist you). <span class=\"citation\">Y. Dem. I, 22ᵃ</span> top <span dir=\"rtl\">לית מַבּוּעָן וכ׳</span> our well does not supply us.—<i>Pl.</i> <span dir=\"rtl\">מַבּוּעִין</span>, <span dir=\"rtl\">מַבּוּעֵי</span>. <span class=\"citation\">Targ. O. Ex. XV, 27</span>. <span class=\"citation\">Targ. Is. XLIX, 10</span>; a. e., v. supra.—[<span class=\"citation\">Targ. Ps. CIV, 6</span> מבועין Ms., v. <a href=\"#\" data-headword=\"מְבַזְעָא\">מְבַזְעָא</a>.]</div>","alt":["מַבּוּעָא"]},"17059":{"h":"מַבּוֹרָא","r":"M00083","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַבָּרָא\">מַבָּרָא</a>) <i>ferry-man</i>. <span class=\"citation\">Ḥull. 94ᵃ</span> <span dir=\"rtl\">מַבּוֹרִין</span> (not <span dir=\"rtl\">מבוריה</span>) our ferry-man, v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a> ch.</div>","alt":[]},"17060":{"h":"מְבַזְעָא","r":"M00084","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּעַ\">בְּוַע</a>) <i>shred</i> of a garment.—Pl. <span dir=\"rtl\">מְבַזְעִין</span>. <span class=\"citation\">Targ. Ps. CIV, 6</span> (Ms. <span dir=\"rtl\">מַבּוּעִין</span>).</div>","alt":[]},"17061":{"h":"מְבִינָא","r":"M00085","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">מלבינא</span>; <a href=\"#\" data-headword=\"ל\">ל</a> rejected as in <a href=\"#\" data-headword=\"מִקָּח\">מֶקַח</a>, fr. <a href=\"#\" data-headword=\"לָקַח\">לָקַח</a>, cmp. <a href=\"#\" data-headword=\"מַסְקָנָא\">מַסְקָנָא</a> fr. <a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>; v. <a href=\"#\" data-headword=\"לָבַן II\"><span dir=\"rtl\">לָבַן</span> II</a>) <i>broom</i>. <span class=\"citation\">Targ. Is. XIV, 23</span> (some ed. incorr. <span dir=\"rtl\">מכ׳</span>).—<span class=\"citation\">Gen. R. s. 79</span> end <span dir=\"rtl\">אומרת אשאיל לי מְבִינָיךְ וכ׳</span> (not <a href=\"#\" data-headword=\"מבנייך\">מבנייך</a>, <a href=\"#\" data-headword=\"מבנייך\">מבניך</a>) wanted to say, Lend me thy broom, and she said, Lend me <span dir=\"rtl\">מְטַאֲטֵיךְ</span>; [<span class=\"citation\">Y. Meg. II, 73ᵃ</span> bot. <a href=\"#\" data-headword=\"אַלְבִּינָא\">אלבינה</a>; correct etymol. s. v. <a href=\"#\" data-headword=\"אַלְבִּינָא\">אַלְבִּינָא</a>].</div>","alt":[]},"17062":{"h":"מְבַלְבְּלִיתָא","r":"M00086","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּלְבֵּל\">בַּלְבֵּל</a></div>","alt":[]},"17063":{"h":"מבליגא","r":"M00087","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זַבְלִיגָא\">זַבְּלִיגָא</a></div>","alt":["מבליגה"]},"17064":{"h":"מַבְלַעְתָּא","r":"M00088","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּלַע\">בְּלַע</a>) <i>the uppermost part of the gullet</i>. <span class=\"citation\">Ḥull. 43ᵇ</span>, expl. <span dir=\"rtl\">תורבץ הוושט</span>.</div>","alt":[]},"17065":{"h":"מבנייך","r":"M00089","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְבִינָא\">מְבִינָא</a></div>","alt":["מבניך"]},"17066":{"h":"מַבְסִימָא","r":"M00090","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mabsima</i>. <span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span> <span dir=\"rtl\">מנחם בר מ׳</span>.</div>","alt":[]},"17067":{"h":"מבססין","r":"M00091","html":"<div class=\"sense\"> Ar., v. <a href=\"#\" data-headword=\"מוֹכְסָסִים\">מוֹכְסָסִים</a></div>","alt":[]},"17068":{"h":"מְבַסְרָנָא","r":"M00092","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (בְּסַר I) <i>despiser; haughty</i>.—Pl. <span dir=\"rtl\">מְבַסְרָנַיָּא</span>. <span class=\"citation\">Targ. Ps. LXVIII, 17</span>. <span class=\"citation\">Ib. CXXIII, 4</span>.</div>","alt":[]},"17069":{"h":"מַבַּע","r":"M00093","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּעַע\">בְּעַע</a></div>","alt":["מַבְּעָא","(מִבְ׳)"]},"17070":{"h":"מַבְעֶה","r":"M00094","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּעָה\">בָּעָה</a></div>","alt":[]},"17071":{"h":"מַבְעִיר","r":"M00095","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּעַר\">בָּעַר</a>. [<span class=\"citation\">Tosef. B. Kam. IX, 1</span> <span dir=\"rtl\">והמבעיר</span>, read with ed. Zuck. <span dir=\"rtl\">והמבעה</span>.]</div>","alt":[]},"17072":{"h":"מַבָּרָא","r":"M00096","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">מעברא</span>; <a href=\"#\" data-headword=\"עֲבַר\">עֲבַר</a>) <i>ferry, ford, crossing board</i>. <span class=\"citation\">Ḥull. 94ᵃ</span> <span dir=\"rtl\">עבר במ׳</span> was crossing on a ferry-boat; <span class=\"citation\">Keth. 105ᵇ</span> <span dir=\"rtl\">עבר במ׳</span> on a board (cmp. <a href=\"#\" data-headword=\"גַּמְלָא I\">גַּמְלָא</a>). <span class=\"citation\">Ḥull. 95ᵃ</span> <span dir=\"rtl\">הוה יתיב במ׳ וכ׳</span> was sitting by the ford of &amp;c., v. <a href=\"#\" data-headword=\"*אִישְׁתַּטִּית\">אִישְׁתַּטִּית</a>. <span class=\"citation\">Ib. 95ᵇ</span> <span dir=\"rtl\">בדיק במ׳</span> made the readiness of a ferry-boat a foreboding test (whether it was auspicious to undertake the journey).</div>","alt":[]},"17073":{"h":"מַבְרַחַת","r":"M00097","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּרַח\">בָּרַח</a>) <i>a woman making an assignment before marrying in order to exclude her husband from the right of inheritance</i>. <span class=\"citation\">Keth. 79ᵃ</span> <span dir=\"rtl\">שטר מ׳</span> the document of assignment. <span class=\"citation\">B. Bath. 150ᵇ</span> <span dir=\"rtl\">מ׳ צריכה וכ׳</span> a <i>mabraḥath</i> must assign all her belongings. <span class=\"citation\">Ib. 151ᵃ</span> <span dir=\"rtl\">מ׳ קני</span> (sub. <span dir=\"rtl\">שטר</span>) an assignment of a woman &amp;c. gives possession to the assignee (although it is merely formal); a. e.</div>","alt":[]},"17074":{"h":"מַבְרֵי","r":"M00098","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (inf. <i>Af</i>. of <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a>) <i>strengthening food</i> (v. <a href=\"#\" data-headword=\"הַבְרָאָה\">הַבְרָאָה</a>). <span class=\"citation\">Targ. Ps. XLII, 4</span> (ed. Wil. <a href=\"#\" data-headword=\"מַדַּע\">מִ׳</a>).</div>","alt":["(מָבְ׳)"]},"17075":{"h":"מברין","r":"M00099","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ḥall. I, 58ᵃ</span> top, ed. Krot., v. <a href=\"#\" data-headword=\"מכרין\">מכרין</a></div>","alt":[]},"17076":{"h":"מַבְרַכְתָּא","r":"M00100","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַבְרַכְתָּה\">next w.</a>) <i>Mabrakhta</i>, a caravan station and market near Maḥoza. <span class=\"citation\">Erub. 47ᵇ</span> <span dir=\"rtl\">דכרי דאתו למ׳</span> rams that came to M. (on a Holy Day). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בני מ׳</span> the inhabitants of M.; <span class=\"citation\">ib. 61ᵇ</span>. <span class=\"citation\">Keth. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"חֲבַט\">חֲבַט</a>.</div>","alt":[]},"17077":{"h":"מַבְרַכְתָּה","r":"M00101","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּרַךְ\">בָּרַךְ</a>; cmp. <span class=\"citation\">Gen. XIV, 11</span>) <i>a caravan</i> (of camels). <span class=\"citation\">Y. Keth. XIII, 35ᵈ</span> top <span dir=\"rtl\">מ׳ היתה עוברת</span> a caravan passed (Shiloh); <span class=\"citation\">Y. Sot. I, 17ᵃ</span> top; <span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">מ׳ … בבאר שבע</span>.</div>","alt":["(מַבְרַכְתָּא)"]},"17078":{"h":"מְבַשְׁקְרָנָא","r":"M00102","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*בַּשְׁקַר\">בַּשְׁקַר</a>) [<i>what is known by searching</i>,] <i>innermost, true nature</i> (corresp. to b. h. <a href=\"#\" data-headword=\"חֵקֶר\">חֵקֶר</a>).—Pl. <span dir=\"rtl\">מְבשְׁקְרָנֵי</span>. <span class=\"citation\">Targ. Job XXXVII, 16</span> (h. text <span dir=\"rtl\">מִפְלְשֵׂי</span>, cmp. <a href=\"#\" data-headword=\"פָּלַשׁ I\"><span dir=\"rtl\">פָּלַשׁ</span> I</a>).</div>","alt":[]},"17079":{"h":"מְבָתָא","r":"M00103","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּת\">בּוּת</a>) <i>night-lodging</i>. <span class=\"citation\">Targ. Jer. XIV, 8</span> (some ed. <a href=\"#\" data-headword=\"מְבָתָא\">מַבָּתָא</a>). <span class=\"citation\">Targ. Is. I, 8</span> <span dir=\"rtl\">ערסל מ׳</span> (ed. Wil. <a href=\"#\" data-headword=\"מְבָתָא\">מַבְּתּוּתָא</a>, corr. acc.; Regia <a href=\"#\" data-headword=\"מְבָתָא\">מַבָּתוּתָא</a>; some ed. <span dir=\"rtl\">מכ׳</span>, corr. acc.) the hammock for night-lodging (h. text <span dir=\"rtl\">מלונה</span>).—<a href=\"#\" data-headword=\"מִלְוָון\">בֵּית מ׳</a> (<a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>) <i>lodging place</i>. <span class=\"citation\">Targ. Gen. XLII, 27</span>; a. e.—<span class=\"citation\">Targ. Jer. IX, 1</span> <span dir=\"rtl\">מְבָתָת</span> (<span dir=\"rtl\">מַבָּתַת</span>, constr.).</div>","alt":["מִבְתוּתָא"]},"17080":{"h":"מְגָאגָא","r":"M00104","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגָגָא\">מְגָגָא</a></div>","alt":[]},"17081":{"h":"מַגָּאנָא","r":"M00105","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְגָּנָא\">מַנְגָּנָא</a></div>","alt":[]},"17082":{"h":"מַגְבַּאי","r":"M00106","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַבְגַּאי\">מַבְגַּאי</a></div>","alt":[]},"17083":{"h":"מִגְבָּה","r":"M00107","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּבָה\">גָּבָה</a>) <i>collection</i>. <span class=\"citation\">Y. Keth. IX, 33ᵇ</span> bot.; <span class=\"citation\">Y. Gitt. V, 46ᵈ</span> top <span dir=\"rtl\">במ׳ הדבר תלוי</span> it (the widow’s right of alimentation) depends on (ceases with) the collection of her widowhood; Y. Shebu. V, 36ᵇ bot.—Y. Meg. I, 70ᵇ bot.; <span class=\"citation\">B. Mets. 78ᵇ</span>, 106ᵇ; <span dir=\"rtl\">מִגְבַּת פורים וכ׳</span> the collection for Purim must be given to the poor for the Purim festival; <span class=\"citation\">Tosef. Meg. I, 5</span> <a href=\"#\" data-headword=\"מַגְבִּית\">מַגְבִּית</a>. Ib. <span dir=\"rtl\">מגבית העיר</span> what has been collected in one town. <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">עסק מגבת צדקה לחכמים</span> the business of collecting contributions for the maintenance of students; <span class=\"citation\">Esth. R. to I, 4</span> <span dir=\"rtl\">מגבת חכמים</span>.</div>","alt":[]},"17084":{"h":"מַגַּבְיָא","r":"M00108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָגַב\">נְגַב</a>; cmp. Syr. <a href=\"#\" data-headword=\"מַגַּבְיָא\">מגביא</a> coagulum, P. Sm. 2001) [<i>astringent</i>,] <i>alum</i>.—<span dir=\"rtl\">(<a href=\"#\" data-headword=\"ג׳\">ג׳</a>) <span dir=\"rtl\">מ׳ גילא</span></span> (v. <a href=\"#\" data-headword=\"גִּילָא II\"><span dir=\"rtl\">גִּילָא</span> II</a>) <i>liquid alum</i>. <span class=\"citation\">Sabb. 110ᵃ</span> (in a prescription) <span dir=\"rtl\">מתקל זוזא מ׳ ג׳</span> Ar. (ed. <a href=\"#\" data-headword=\"מַגַּבְיָא\">גביא</a>, Ms. M. only <span dir=\"rtl\">מגבי</span>; Ms. O. <a href=\"#\" data-headword=\"מַגַּבְיָא\">מגביא</a>) alum of the weight of a Zuz. <span class=\"citation\">Men. 42ᵇ</span> bot. <span dir=\"rtl\">מ׳ גילא</span> (Ms. R. 2 <a href=\"#\" data-headword=\"גַּלְיָא I\">גליא</a>, v. Rabb. D. S. a. l. note 8).</div>","alt":["גַּבְיָא"]},"17085":{"h":"מַגְבִּילָה","r":"M00109","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Magbilah</i>. <span class=\"citation\">Y. Ber. III, 6ᵃ</span> bot. <span dir=\"rtl\">מ׳ אחוי דר׳ אבא בר כהן</span>; Y. Naz. VII, 56ᵃ <span dir=\"rtl\">גבילה</span>; <span class=\"citation\">Pesik. R. s. 33</span> <a href=\"#\" data-headword=\"*אבליג\">אבליג</a>, <a href=\"#\" data-headword=\"*אבליג\">אבליגה</a> (corr. acc.).</div>","alt":[]},"17086":{"h":"מַגְבִּית","r":"M00110","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִגְבָּה\">מִגְבָּה</a></div>","alt":[]},"17087":{"h":"מַגְבִּיתָא","r":"M00111","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (dial. for <span dir=\"rtl\">מגפיתא</span>; <a href=\"#\" data-headword=\"נְגַף\">נְגף</a>; cmp. Sam. <span dir=\"rtl\">מגופי</span>, <span class=\"citation\">Lev. XIX, 14</span>, a. <span dir=\"rtl\">מגבי</span> <span class=\"citation\">Ex. XXIII, 33</span>; v. Fränkel Zeitschr. f. Assyriol., April 1894, p. 3) <i>stumbling block</i>. <span class=\"citation\">Targ. Is. III, 6</span> (h. text <span dir=\"rtl\">מכשלה</span>).</div>","alt":[]},"17088":{"h":"מֶגֶג","r":"M00112","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מָגַג\">next w.</a>) <i>megeg</i>, a species of <i>reed.</i> <span class=\"citation\">Par. III, 9</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">II), 9</span>; <span dir=\"rtl\">חבל של מ׳</span> a rope made of <i>m</i>.; <span class=\"citation\">Erub. 58ᵃ</span></div>","alt":[]},"17089":{"h":"מָגַג","r":"M00113","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מוּג\">מוּג</a>) <i>to soften, dissolve, steep</i>. <span class=\"citation\">Y. Maas. Sh. II, 53ᶜ</span> top <span dir=\"rtl\">מוֹגֵג בידים טמאות</span> you may steep (fenugrec in a lotion) with levitically unclean hands.</div><div class=\"sense\"><b>Hithpalp. הִתְמַגְמֵג</b> <div class=\"sense\"><i>to be dissolved, melt</i>. <span class=\"citation\">Pesik. R. s. 21</span> (ref. to <span dir=\"rtl\">נמוגים</span>, <span class=\"citation\">Ps. LXXV, 4</span>) <span dir=\"rtl\">כבר היה העולם מִתְמַגְמֵג והולך</span> the world would have gone on melting away; <span class=\"citation\">Cant. R. to VII, 1</span> <span dir=\"rtl\">מתגמגם</span> (transpos.).</div></div>","alt":[]},"17090":{"h":"מְגַג","r":"M00114","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"מוּג\">מוּג</a> ch.</div>","alt":[]},"17091":{"h":"מְגָגָא","r":"M00115","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְגַג\">preced.</a>) <i>solution, maceration</i>.—Pl. <span dir=\"rtl\">מְגָגֵי</span>. <span class=\"citation\">Pes. 107ᵃ</span> שיכרא בר תליסר מ׳ Ar. (ed. <span dir=\"rtl\">מגני</span>, Ms. M. <a href=\"#\" data-headword=\"גְּנֵי\">אגני</a>; Ms. M. 2 <span dir=\"rtl\">מְגָאגֵי</span>; Ms. O. <span dir=\"rtl\">מגאני</span>) a date beer of thirteen solutions (the same water poured over thirteen basins of crushed dates in succession).</div>","alt":[]},"17092":{"h":"מֶגֶד","r":"M00116","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , as <span dir=\"rtl\">מֶמֶר</span> fr. <a href=\"#\" data-headword=\"מָרַר\">מָרַר</a>; cmp. <a href=\"#\" data-headword=\"גָּד\">גָּד</a> <i>fortune</i>) [<i>allotted gift</i>,] <i>precious goods</i>, esp. <i>fine fruit</i>.—Pl. <span dir=\"rtl\">מְגָדִים</span>. <span class=\"citation\">Sabb. 127ᵇ</span> <span dir=\"rtl\">מיני מ׳</span> all sorts of delicacies.</div>","alt":[]},"17093":{"h":"מַגְדָּא","r":"M00117","html":"<div class=\"sense\">, <i>precious ware, fine fruit</i>.—Pl. <span dir=\"rtl\">מַגְדִּין</span>, <span dir=\"rtl\">מִגְדַּיָּא</span>, <span dir=\"rtl\">מְגָדֵי</span>, <a href=\"#\" data-headword=\"מִגְזְרָא\">מִיגְ׳</a>. <span class=\"citation\">Targ. Job IX, 26</span>. <span class=\"citation\">Targ. Y. Ex. XV, 19</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 23</span>. <span class=\"citation\">Ib. XXXIII, 13</span>, sq., v. <a href=\"#\" data-headword=\"מִגְדָּנִין\">מִגְדָּנִין</a>. [<span class=\"citation\">Targ. Y. I Num. XXII, 7</span> <span dir=\"rtl\">מיגדין דקיסמין</span> jewels of divination (?); Y. II אגרין <i>letters</i>.]—<span class=\"citation\">Men. 43ᵇ</span> <span dir=\"rtl\">איספרמקי ומגדי</span> spices and choice fruits.</div>","alt":["מִגְ׳","מִיגְ׳ I"]},"17094":{"h":"מִגְדָּא","r":"M00118","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְגַד\">(נְגַד</a>), constr. <a href=\"#\" data-headword=\"מִגְדַּת\">מִגְדַּת</a>, <i>guidance, leading string</i>. <span class=\"citation\">Targ. Hos. XI, 4</span> (ed. Wil. <a href=\"#\" data-headword=\"מגרת\">מגרת</a>); cmp. <a href=\"#\" data-headword=\"תִּיגְדָּא\">תִּיגְדָּא</a>.</div>","alt":["מִיגְ׳ II"]},"17095":{"h":"מגדירה","r":"M00119","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַגְרֶרֶת\">מַגְרֵדָה</a></div>","alt":[]},"17096":{"h":"מִגְדָּל","r":"M00120","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>tower, turret</i>. <span class=\"citation\">Sabb. XIII, 5</span>. <span class=\"citation\">Tosef. Ohol. XVIII, 5</span> <span dir=\"rtl\">הנכנס … במ׳</span> he who enters gentile lands … in a portable turret. Ohol. IV, 1, v. <a href=\"#\" data-headword=\"אָוִיר\">אָוִיר</a>. <span class=\"citation\">Ḥag. 15ᵇ</span>; <span class=\"citation\">Snh. 106ᵇ</span> three hundred <i>hălakhoth</i> (about levitical cleanness) <span dir=\"rtl\">במ׳ הפורח באויר</span> concerning a turret flying (moving) in the air (cmp. Tosef. l. c.); [oth. opin. = <span dir=\"rtl\">מ׳ העומד באויר</span>, Ohol. l. c.; for oth. explan. v. Rashi to Ḥag. a. Snh. l. c.].—<span class=\"citation\">Erub. 34ᵃ</span> <span dir=\"rtl\">מ׳ שאינו מסומר</span> a turret which is not fastened (which can be let up and down). <span class=\"citation\">Kel. XII, 3</span> <span dir=\"rtl\">מ׳ של בעלי וכ׳</span> a turret (spice chest) of private people, <span dir=\"rtl\">של רופאים</span> of physicians. <span class=\"citation\">Tosef. Sot. III, 10</span> <span dir=\"rtl\">אנשי מ׳</span> the builders of the Tower of Babel, v. <a href=\"#\" data-headword=\"הַפְלָגָה\">הַפְלָגָה</a>; a. fr.—Pl. <span dir=\"rtl\">מִגְדָּלִים</span>, <a href=\"#\" data-headword=\"מִגְדָּנִין\">מִגְדָּלִין</a>, <span dir=\"rtl\">מִגְדָּלוֹת</span>. <span class=\"citation\">Y. B. Bath. IV, 14ᶜ</span> bot.; <span class=\"citation\">Tosef. B. Bath. III, 3</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> the turrets (store closets) in bath-houses. <span class=\"citation\">Tosef. Kel. B. Mets. II, 8</span>, v. <a href=\"#\" data-headword=\"אֲקוּנְבִּי\">אֲקוּנְבִּי</a>. <span class=\"citation\">B. Mets. 25ᵃ</span> <span dir=\"rtl\">עשויין כמ׳</span>; <span class=\"citation\">Tosef. ib. II, 7</span> <span dir=\"rtl\">עשויות מגדלות</span> coins piled up pyramidally; ib. <span dir=\"rtl\">מקצתן מגדלין</span> some of them piled up; a. fr.—Esp. <a href=\"#\" data-headword=\"מִגְדָּל\">מִגְדָּל</a> pr. n. pl. <i>Migdal, Magdala</i>, near Tiberias. <span class=\"citation\">Tosef. Erub. VI</span> (<span class=\"citation\">V), 13</span>; Y. ib. V, 22ᵈ bot.—In compounds: <a href=\"#\" data-headword=\"מִגְדַּל\">מִגְדַּל</a>, e. g. <span dir=\"rtl\">מ׳ עדר</span>, <span dir=\"rtl\">מ׳ חרוב</span>, v. respective determinants.</div>","alt":[]},"17097":{"h":"מִגְדַּל","r":"M00121","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. II, 15</span>. <span class=\"citation\">Targ. Gen. XI, 4</span> (ed. Berl. <span dir=\"rtl\">מַ׳</span>). <span class=\"citation\">Targ. Jud. VIII, 9</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מַגְדְּלָאָה\">מִגְדָּלַיָּא</a>, <a href=\"#\" data-headword=\"מִגְדַּל\">מוּגְ׳</a>. <span class=\"citation\">Targ. II Chr. XXVI, 9</span>, sq. <span class=\"citation\">Targ. Ez. XXXVIII, 20</span> (h. text <span dir=\"rtl\">מדרגות</span>); a. fr.—Esp. <a href=\"#\" data-headword=\"מִגְדַּל\">מַגְדְּלָא</a>, <a href=\"#\" data-headword=\"מִגְדַּל\">מוּגְ׳</a> <i>Magdala</i>, v. <a href=\"#\" data-headword=\"מִגְדָּל\">preced.</a> <span class=\"citation\">Y. Snh. II, beg. 19ᵈ</span> <span dir=\"rtl\">ערק לדא מוג׳</span> he fied to M.; <span class=\"citation\">Y. Hor. III, beg. 47ᵃ</span> <span dir=\"rtl\">ערק בדא דמ׳</span> (read: <span dir=\"rtl\">לדא</span>, sub. <a href=\"#\" data-headword=\"כְּנִישָׁא\">כנישתא</a>) to the synagogue (and school house) of M.; <span class=\"citation\">ib.</span> <span dir=\"rtl\">בדא דמ׳</span> he is in the synagogue of M.; Y. Snh. l. c. 20ᵃ top <span dir=\"rtl\">בהדא מ׳</span>; Midr. Sam. ch. VII <span dir=\"rtl\">מִגְדַּל צְבוֹעַיָּיא</span>. <span class=\"citation\">Y. Maasr. III, 50ᶜ</span> top. <span class=\"citation\">Koh. R. to X, 8</span> <span dir=\"rtl\">כנישתא דמ׳</span>, v. supra; a. fr.—In compounds: <a href=\"#\" data-headword=\"מִגְדַּל\">מִגְדַּל</a>, <span dir=\"rtl\">מגדלא ד־</span>, v. respective determinants.</div>","alt":["מִגְדְּלָא","מַגְ׳","מוּגְ׳"]},"17098":{"h":"מַגְדְּלָאָה","r":"M00122","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִגְדַּל\">preced.</a>) <i>of Magdala</i>, surname of several scholars. <span class=\"citation\">B. Mets. 25ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"יִצְחָק\">יִצְחָק</a>. <span class=\"citation\">Y. Ber. IX, 14ᵃ</span> top; <span class=\"citation\">Y. Taan. I, 64ᵇ</span> top; a. e.</div>","alt":["מַגְדְּלָיָא","מוּגְ׳"]},"17099":{"h":"מְגַדֶּלֶת","r":"M00123","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּדַל I\">גָּדַל</a>) </div><div class=\"sense\"><b>1)</b> <i>child’s nurse</i>. <span class=\"citation\">Lev. R. s. 36</span>, end.</div><div class=\"sense\"><b>—2)</b> <i>hair-dresser, hand-maid</i>, v. <a href=\"#\" data-headword=\"גַּדֶּלֶת\">גַּדֶּלֶת</a>.</div>","alt":[]},"17100":{"h":"מגדן","r":"M00124","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to VII, 26</span> some ed., v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a></div>","alt":[]},"17101":{"h":"מִגְדָּנִין","r":"M00125","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"מֶגֶד\">מֶגֶד</a>) <i>precious goods</i>. <span class=\"citation\">Targ. O. Gen. XXIV, 53</span> (Y. <span dir=\"rtl\">דורונין</span>, h. text <span dir=\"rtl\">מגדנות</span>). <span class=\"citation\">Targ. O. Deut. XXXIII, 13</span>, sq., v. <a href=\"#\" data-headword=\"מַגְדָּא\">מַגְדָּא</a>.</div>","alt":["מַגְ׳"]},"17102":{"h":"מִגְדַּת","r":"M00126","html":"<div class=\"sense\">, v. <span dir=\"rtl\">מִגְדָּא II</span></div>","alt":[]},"17103":{"h":"מִגּוֹ","r":"M00127","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גֵּו\">גֵּו</a></div>","alt":["מִיגּוֹ"]},"17104":{"h":"*מָגוֹב","r":"M00128","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּבַב\">גָּבַב</a>) <i>rake</i>, an agricultural implement with many teeth, forming a sort of sieve to separate the grain from the chaff. <span class=\"citation\">Kel. XIII, 7</span>; <span class=\"citation\">T’bul Yom IV, 6</span>; [Ar. s. v.: a sort of <i>glove</i>, oth. expl.: reading <span dir=\"rtl\">מַגֵּיב</span>, fr. <a href=\"#\" data-headword=\"נָגַב\">נָגַב</a>, <i>an implement for drying</i> the grain by winnowing].</div>","alt":[]},"17105":{"h":"מָגוֹג","r":"M00129","html":"<div class=\"sense\"> (b. h.) pr. n. gent. <i>Magog</i>, <span dir=\"rtl\">גוג ומ׳</span> Gog and Magog, the two allied nations, the defeat of which, it is believed, will precede the redemption of Israel (v. <span class=\"citation\">Ez. XXXVIII</span>, sq.). <span class=\"citation\">Eduy. II, 10</span> <span dir=\"rtl\">משפט ג׳ ומ׳ וכ׳</span> the judgment of Gog and Magog in the Messianic days will last twelve months. <span class=\"citation\">Ber. 13ᵃ</span> <span dir=\"rtl\">מלחמת גוג ומ׳</span> the war with G. a. M. <span class=\"citation\">Snh. 95ᵇ</span>; a. fr.</div>","alt":[]},"17106":{"h":"מָגוֹד","r":"M00130","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָגַד\">נָגַד</a>; cmp. <a href=\"#\" data-headword=\"*גּוֹד\">גּוֹד</a>) <i>a frame to spread clothes on</i>. <span class=\"citation\">B. Mets. 30ᵃ</span>; <span class=\"citation\">Pes. 26ᵇ</span> <span dir=\"rtl\">אבידה לא ישטחנה ע&quot;ג … מ׳ וכ׳</span> the finder must not spread a lost object in his charge over a bed or a frame for his own use.</div>","alt":[]},"17107":{"h":"מְגוּסָא","r":"M00131","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגִיסָא\">מְגִיסָא</a></div>","alt":[]},"17108":{"h":"מְגוֹסֶת","r":"M00132","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (?) <i>M’goseth</i>. <span class=\"citation\">Yeb. VIII, 4</span> (<span class=\"citation\">79ᵇ</span>) <a href=\"#\" data-headword=\"מְקוֹשֵׁשׁ II\">בן מ׳</a> one Ben M.</div>","alt":[]},"17109":{"h":"מְגוּסְתָּא","r":"M00133","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגִיזְתָּא I\">מְגִיזְתָּא</a> a. <a href=\"#\" data-headword=\"מְגִיסְתָּא\"><a href=\"#\" data-headword=\"מְגִיסְתָּא\">מְגִיסְתָּא</a>.</a></div>","alt":[]},"17110":{"h":"מְגוּפָה","r":"M00134","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גּוּף I\"><span dir=\"rtl\">גּוּף</span> I</a>), constr. <a href=\"#\" data-headword=\"מְגוּפָה\">מְגוּפַת</a> </div><div class=\"sense\"><b>1)</b> <i>bung, stopper.</i> <span class=\"citation\">Kel. IX, 1</span>. <span class=\"citation\">Ib. X, 3</span>, v. <a href=\"#\" data-headword=\"חִלְחֵל\">חִלְחֵל</a>.</div><div class=\"sense\"><b>—2)</b> <i>the clay used for sealing wine vessels, sealing clay</i>. <span class=\"citation\">Y. Ber. IX, 13ᵈ</span> bot. <span dir=\"rtl\">כדי שתשרה המ׳</span> so much rain that the sealing clay looks as if dissolving; <span class=\"citation\">Y. Taan. I, 64ᵇ</span> top (not <span dir=\"rtl\">שתשרף</span>); a. e.</div><div class=\"sense\"><b>—3)</b> <i>an air-tight vessel</i>. <span class=\"citation\">Tosef. Bets. II, 14</span>; Y. ib. II, 61ᶜ bot. <span dir=\"rtl\">היו מכניסין … במ׳</span> they brought the burning perfume (<a href=\"#\" data-headword=\"מוּגְמָר\">מוּגְמָר</a>) into the dining room (on a Holy Day) in an air-tight vessel.</div>","alt":[]},"17111":{"h":"מְגוּפְתָּא","r":"M00135","html":"<div class=\"sense\">, <i>stopper; clay-seal</i>. Targ. O. a. Y. I <span class=\"citation\">Num. XIX, 15</span> (Y. II <a href=\"#\" data-headword=\"פּוּרְיְיתָא I\">פורייתא</a>). Targ. Y. ib. 9.—Pl. <a href=\"#\" data-headword=\"מְגוּפְתָּא\">מְגוּפָתָא</a>. <span class=\"citation\">Targ. Joel I, 17</span> <span dir=\"rtl\">מְגוּפָתְהוֹן</span> (h. text <span dir=\"rtl\">מגרפתיהם</span>!).</div>","alt":[]},"17112":{"h":"מָגוֹר","r":"M00136","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>dwelling, neighborhood</i>. <span class=\"citation\">Sabb. 149ᵇ</span> (expl. <span dir=\"rtl\">יגרך</span>, <span class=\"citation\">Ps. V, 5</span>) <span dir=\"rtl\">לא יגור במְגוֹרְךָ רע</span> a bad man shall not dwell in thy neighborhood; <span class=\"citation\">Ḥag. 12ᵇ</span> evil shall not &amp;c.; a. e.—</div><div class=\"sense\"><b>*2)</b> <i>rest, stand</i>. <span class=\"citation\">Tosef. Kel. B. Kam. IV, 20</span> (R. S. to <span class=\"citation\">Kel. V, 11</span> <span dir=\"rtl\">מגיר</span>).</div>","alt":[]},"17113":{"h":"מָגוֹר ²","r":"M00137","html":"<div class=\"sense\"><i>neighbor</i>, v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a>.</div>","alt":["מָגוֹרָא"]},"17114":{"h":"מְגוּרָה I","r":"M00138","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>store-room; bin</i> for wheat, figs &amp;c.; <i>reservoir</i>. <span class=\"citation\">Pes. 4ᵇ</span>, a. e. <span dir=\"rtl\">מ׳ מליאה פירות</span> a store-house full of provision. <span class=\"citation\">Maasr. I, 8</span>, v. <a href=\"#\" data-headword=\"עָגַל\">עָגַל</a>; a. e.—<span class=\"citation\">Tosef. Mikv. I, 17</span> <span dir=\"rtl\">מ׳ של דיסקוס וכ׳</span> (ed. Zuck. <span dir=\"rtl\">ינורס</span>, corr. acc.) the water-reservoir of Discus in Jabneh; <span class=\"citation\">Y. Ter. VIII, 45ᵇ</span> <span dir=\"rtl\">מְגוֹרֶת של וכ׳</span>; <span class=\"citation\">Kidd. 66ᵇ</span> <span dir=\"rtl\">מ׳ של דסקים</span>.—Trnsf. (v. <a href=\"#\" data-headword=\"*אֲגוֹרָה\">אֲגוֹרָה</a>) <i>pericarp</i> of nuts, almonds &amp;c.; <i>drupe.</i> <span class=\"citation\">Maasr. I, 2</span> nuts are subject to tithes <span dir=\"rtl\">משיעשו מ׳</span> from the time they form drupes; <span class=\"citation\">Tosef. ib. I, 1</span>; Y. ib. I, 48ᵈ bot.—<span class=\"citation\">Gen. R. s. 18</span> <span dir=\"rtl\">בנה בה מגורות וכ׳</span> (read <a href=\"#\" data-headword=\"מְגוֹרֶת\">מְגוֹרֶת</a>) he built in woman’s body one store-room (the womb) more than in man; (<span class=\"citation\">Erub. 18ᵃ</span> sq. <span dir=\"rtl\">כבנין אוצר</span>).—Pl. <span dir=\"rtl\">מְגוּרוֹת</span>. <span class=\"citation\">B. Bath. IV, 6</span> (<span class=\"citation\">67ᵇ</span>) <span dir=\"rtl\">מ׳ שלמים</span> (Ms. M. <span dir=\"rtl\">מערות</span>) reservoirs. <span class=\"citation\">Kel. XIX, 7</span> <span dir=\"rtl\">מ׳ שבה</span> the <i>drawers</i> in a chest. <span class=\"citation\">Tosef. Kel. B. Kam. II, 7</span> <span dir=\"rtl\">בית תבלין … העשוי מ׳ מ׳ וכ׳</span> a wooden spice box having <i>compartments</i> (<i>partitions</i>) without lids. Ib. <span class=\"citation\">B. Mets. VIII, 1</span> <span dir=\"rtl\">שידה שהמ׳ שלה וכ׳</span> (ed. Zuck. <span dir=\"rtl\">מגירות</span>, corr. acc.) a chest whose drawers are inside (not protruding). <span class=\"citation\">Yalk. Cant. 992</span>, v. <a href=\"#\" data-headword=\"*אֲגוֹרָה\">אֲגוֹרָה</a>.</div>","alt":[]},"17115":{"h":"מְגוּרָה II","r":"M00139","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (גּוּר I) <i>a court containing several dwellings</i>. <span class=\"citation\">Erub. 70ᵇ</span> (Rashi: <i>a barn divided off</i>, v. <a href=\"#\" data-headword=\"מְגוּרָה I\">preced.</a>).—Pl. <span dir=\"rtl\">מְגוּרוֹת</span> (or <span dir=\"rtl\">מְגוֹרוֹת</span>) <i>neighborhood, neighbors</i>. <span class=\"citation\">Gen. R. s. 99</span>; Tanḥ. Vayḥi 9, v. <a href=\"#\" data-headword=\"מְכֵרוֹת\">מְכֵרוֹת</a>.</div>","alt":[]},"17116":{"h":"מגורה","r":"M00140","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. XVI, end, 15ᵈ</span> <span dir=\"rtl\">במ׳ דר׳ יונה</span>, read <span dir=\"rtl\">מְגִירֵיה</span>, v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a></div>","alt":[]},"17117":{"h":"מגורסי","r":"M00141","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to II, 22</span>, Ar. ed. Koh., v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a></div>","alt":[]},"17118":{"h":"מְגוֹרֶרֶת","r":"M00142","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>strigil</i>, v. <a href=\"#\" data-headword=\"מַגְרֶרֶת\">מַגְרֶרֶת</a>.</div>","alt":[]},"17119":{"h":"מְגוֹרֶת","r":"M00143","html":"<div class=\"sense\"> f. </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"מְגוּרָה I\"><span dir=\"rtl\">מְגוּרָה</span> I</a>, q. v.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"מוֹגֵרָה\">מוֹגֵרָה</a></div>","alt":[]},"17120":{"h":"מְגוּרְתָּא","r":"M00144","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"מְגוּרָה II\"><span dir=\"rtl\">מְגוּרָה</span> II</a>, <i>court, neighborhood</i>. Y. Sabb. XVI, end, 15ᵈ [read:] <span dir=\"rtl\">נפלת … במְגוּרְתֵּיה וכ׳</span> a fire broke out in the court of R. J.; <span class=\"citation\">Y. Yoma VIII, 45ᵇ</span> <span dir=\"rtl\">במְגִירוּתֵיה</span>; Y. Ned. IV, 38ᵈ</div><div class=\"sense\"><b>—2)</b> <i>neighbor</i>, v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a>.</div>","alt":["מְגִירוּתָא"]},"17121":{"h":"מָגוֹשׁ","r":"M00145","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>magian, sorcerer</i>. <span class=\"citation\">Sabb. 75ᵃ</span>. <span class=\"citation\">Sot. 22ᵃ</span> <span dir=\"rtl\">ה&quot;ז מ׳</span> he is a magian (saying words he does not understand).</div>","alt":[]},"17122":{"h":"מָגוֹשָׁא","r":"M00146","html":"<div class=\"sense\"> <span class=\"citation\">Yoma 35ᵃ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"אַמְגֹּושָׁא\">אמגושא</a>). <span class=\"citation\">Sot. 22ᵃ</span> (prov.) <span dir=\"rtl\">רטין מ׳ ולא וכ׳</span> the magian mumbles and understands not what he says.</div>","alt":[]},"17123":{"h":"מָגוּשְׁתָּא","r":"M00147","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָגוֹשָׁא\">preced.</a>) <i>the magian’s practices</i>, v. <a href=\"#\" data-headword=\"אַמְגּוּשְׁתָּא\">אַמְגּוּשְׁתָּא</a>.</div>","alt":[]},"17124":{"h":"מִגְזְרָא","r":"M00148","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּזַר\">גְּזַר</a>) <i>cutting tool, sickle, pruning knife</i>.—Pl. <span dir=\"rtl\">מִגְזְרִין</span>, <a href=\"#\" data-headword=\"מִגְזְרָא\">מִיגְ׳</a>. <span class=\"citation\">Targ. II Sam. XII, 31</span> (h. text <span dir=\"rtl\">מגזרות</span>).—Y. Sabb. VI, 8ᵇ bot. (expl. <span dir=\"rtl\">מזמרות</span>, <span class=\"citation\">Is. II, 4</span>) <a href=\"#\" data-headword=\"מיגזיין\">מיגזיין</a> (corr. acc.).</div>","alt":["מִיגְ׳"]},"17125":{"h":"מְגִזְתָּא","r":"M00149","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגִיזְתָּא I\">מְגִיזְתָּא</a></div>","alt":[]},"17126":{"h":"מְגֵי","r":"M00150","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּג\">מוּג</a></div>","alt":[]},"17127":{"h":"מַגִּיד","r":"M00151","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָגַד\">נָגַד</a>) <i>speaker, preacher</i>. <span class=\"citation\">Pes. 52ᵇ</span> (play on <span class=\"citation\">Hos. IV, 12</span> <span dir=\"rtl\">ומקלו יגיד לו</span>) <span dir=\"rtl\">כל המיקל לו מ׳ לו</span> whoever makes it easy for him, is his preacher.—Pl. <span dir=\"rtl\">מַגִּידִים</span>, constr. <span dir=\"rtl\">מַגִּידֵי</span>. <span class=\"citation\">Erub. 53ᵇ</span>, v. <a href=\"#\" data-headword=\"עֲלָטָה\">עֲלָטָה</a>.</div>","alt":[]},"17128":{"h":"מגידונית","r":"M00152","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Num. 786</span>, read <a href=\"#\" data-headword=\"מַטְרוֹנִית\">מַטְרוֹנִית</a>.</div>","alt":[]},"17129":{"h":"מגידם","r":"M00153","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 4</span>, end, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגִירוֹס</a></div>","alt":[]},"17130":{"h":"מְגִיזָה","r":"M00154","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מְגִיזְתָּא I\">מְגִיזְתָּא</a>) <i>M’gizah</i> (<i>Pass</i>), <i>Mazaca</i>, later Caesarea, capital of Cappadocia. <span class=\"citation\">Yeb. 25ᵇ</span> <span dir=\"rtl\">מְגִיזַת קפוטקיא</span>; (Y. ib. II, end, 4ᵇ <span dir=\"rtl\">קיסרין שבקפודקייא</span>; Tosef. ib. IV, 5 <span dir=\"rtl\">בקפ׳</span> only). Y. ib. XVI, 15ᵈ top <span dir=\"rtl\">מג׳ של קפ׳</span>; Tosef. ib. XIV, 5 <span dir=\"rtl\">מְזִיגַת קפ׳</span> (Var. <span dir=\"rtl\">מדינת</span>; Bab. ib. 121ᵃ <span dir=\"rtl\">מדינת</span>; <span class=\"citation\">Koh. R. to XI, 1</span> <span dir=\"rtl\">מדינת</span>). <span class=\"citation\">Tosef. Sabb. XV</span> (<span class=\"citation\">XVI), 8</span> <span dir=\"rtl\">מז׳</span> (Var. <span dir=\"rtl\">מדינת</span>). <span class=\"citation\">M. Kat. 26ᵃ</span> <span dir=\"rtl\">מזיגת קסרי</span> (Ms. M. <span dir=\"rtl\">מדינת דקסרי</span>).</div>","alt":["(מְזִיגָה)"]},"17131":{"h":"מְגִיזוּתָא","r":"M00155","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגִיזְתָּא II\"><span dir=\"rtl\">מְגִיזְתָּא</span> II</a></div>","alt":[]},"17132":{"h":"מְגִיזְתָּא I","r":"M00156","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּזַז\">גְזַז</a> or <a href=\"#\" data-headword=\"גּוּז\">גּוּז</a>), constr. <a href=\"#\" data-headword=\"מְגִיזָה\">מְגִיזַת</a>, <span dir=\"rtl\">מְגִוַּת</span>, <i>ford, pass</i>. <span class=\"citation\">Targ. II Sam. XIX, 19</span>. <span class=\"citation\">Targ. Num. XXI, 11</span>; a. e.—Pl. <a href=\"#\" data-headword=\"מְגִיזְתָּא I\">מְגִיזָתָא</a>, <span dir=\"rtl\">מְגִזָּ׳</span>. <span class=\"citation\">Targ. Y. Num. XXXIII, 45</span>. <span class=\"citation\">Targ. Jer. XXII, 20</span>; a. e.</div>","alt":["מְגִזְתָּא"]},"17133":{"h":"מְגִיזְתָּא II","r":"M00157","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּזַז\">גְּזַז</a>) <i>arbitrary decision</i>. <span dir=\"rtl\">דיני דמ׳</span> <i>the arbitration practice of untrained magistrates</i>, opp. to learned courts. <span class=\"citation\">B. Mets. 30ᵇ</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"אֲלָא I\">אלא</a> (<a href=\"#\" data-headword=\"מַאי\">מאי</a>) <span dir=\"rtl\">דינא דמ׳ לדיינו</span></span> ed. (Ms. M. <a href=\"#\" data-headword=\"מְגוּסְתָּא\">מגוסתא</a>, v. Rabb. D. S. a. l. note) what else should they have done (in lieu of deciding according to the law of the Torah)? Should they have followed the practice of the arbitrators?—V. <a href=\"#\" data-headword=\"מְגִיזְתָּא II\"><span dir=\"rtl\">מְגִיסְתָּא</span> II</a>.</div>","alt":[]},"17134":{"h":"מְגִילָּה","r":"M00158","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מְגִלְתָּא\">מְגִלְ׳</a>.</div>","alt":["מְגִילְתָּא"]},"17135":{"h":"מָגִינּ־","r":"M00159","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגֵן\">מָגֵן</a></div>","alt":[]},"17136":{"h":"מַגִּין","r":"M00160","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>shield, protection</i>. <span class=\"citation\">Targ. Deut. XXXII, 38</span> (some Ms. <a href=\"#\" data-headword=\"מְגָן\">מְגָן</a>, Y. ed. Amst. <a href=\"#\" data-headword=\"מַגִּין\">מֵגִין</a>); a. e.—<span class=\"citation\">Gen. R. s. 59</span>, end <span dir=\"rtl\">אניף במָגִינֵּיה</span> he swung his shield; <span class=\"citation\">Yalk. ib. 107</span>; <span class=\"citation\">Yalk. Sam. 156</span>. <span class=\"citation\">Gen. R. s. 77</span>, end <span dir=\"rtl\">מגיניה דידין וכ׳</span> the shield of the one against that of the other; a. e.—Pl. <span dir=\"rtl\">מָגִינִּין</span>, <span dir=\"rtl\">מָגִינַּיָּיא</span>. <span class=\"citation\">Targ. I Kings X, 17</span> (ed. Wil. <span dir=\"rtl\">מָגִנִּין</span>); a. e.—<span dir=\"rtl\">בֵּית מָגִינַּיָּיא</span> pr. n. pl. <i>Beth Maginnaya</i> (Shield-House). <span class=\"citation\">Kil. VI, 4</span> Y. ed. (Bab. ed. a. Mish. <span dir=\"rtl\">בית המגנייה</span>; Ms. M. <a href=\"#\" data-headword=\"הַמְגַּנְיָא\">המגניא</a>; Tosef. ib. IV, 7 <span dir=\"rtl\">בית המגינין</span>).</div>","alt":["(מָגֵין)","מְגִינָּא"]},"17137":{"h":"מָגֶינֶת","r":"M00161","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגֶנֶת\">מָגֶנֶת</a></div>","alt":[]},"17138":{"h":"מֵגֵיס","r":"M00162","html":"<div class=\"sense\">) m. (v. <a href=\"#\" data-headword=\"גְּסַס\">גְּסַס</a>) <i>tray, plate.</i> <span class=\"citation\">Yoma VI, 7</span>; <span class=\"citation\">Pes. V, 10</span> <span dir=\"rtl\">נתנן במ׳ והקטירן וכ׳</span> he put them (the parts belonging on the altar) on a tray and burned them &amp;c. <span class=\"citation\">Ib. 65ᵇ</span> אטו במ׳ גופיה מקטר להו Var. in Rashi (v. Rabb. D. S. a. l. note 60; ed. <span dir=\"rtl\">אטו הוא גופיה וכ׳</span>) did he burn them on the very plate?; <span class=\"citation\">Yoma 67ᵇ</span> (<a href=\"#\" data-headword=\"אָטוּ\">אטו</a>) <span dir=\"rtl\">במ׳ מקטר להו</span> Var. in Rashi a. Tosaf. (v. Rabb. D. S. a. l. note 9). <span class=\"citation\">Kel. XVI, 1</span> <span dir=\"rtl\">המגס</span> (ed. Dehr. <span dir=\"rtl\">המגיס</span>; <span class=\"citation\">Tosef. Kel. B. Mets. V, 10</span> <a href=\"#\" data-headword=\"קְעָרָה\">קערה</a>). <span class=\"citation\">Y. Yoma V, beg. 42ᵇ</span> כף מ׳ <i>Kaf</i> (Mish. <span class=\"citation\">ib. V, 1</span>) means <i>plate</i>.</div>","alt":["מֵגֵס","מַגָּס"]},"17139":{"h":"מְגִיסָא","r":"M00163","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מֵגֵיס\">same</a>, <i>plate, dish</i>. <span class=\"citation\">Targ. Ps. CXXIII, 2</span> <span dir=\"rtl\">מודיקין … מ׳ וכ׳</span> looking out for (the remnant of) a dish at the hands of their masters (in ed. Wil. our w. omitted); <span class=\"citation\">Targ. Y. Num. XI, 6</span> (not <span dir=\"rtl\">דמוריק</span>).—<span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">כיון דהוה מ׳ עליל</span> whenever a dish was brought in; <span class=\"citation\">ib.</span> <span dir=\"rtl\">וכיון דמְגוּסִי עליל</span> as soon as a dish of mine comes in; (<span class=\"citation\">Koh. R. to I, 3</span> <a href=\"#\" data-headword=\"תַּבְשִׁיל ²\">תבשילא</a>).—Pl. <span dir=\"rtl\">מְגִיסִין</span>, <span dir=\"rtl\">מְגִיסַיָּא</span>, <a href=\"#\" data-headword=\"מְגִיסְתָּא\">מְגוּ׳</a>. <span class=\"citation\">Targ. O. Num. IV, 7</span> (ed. Amst. <a href=\"#\" data-headword=\"מַגֵּפָה\">מַגִּי׳</a>); a. fr.—<span class=\"citation\">Targ. Ez. XIII, 19</span> <span dir=\"rtl\">מגוסין דלחם</span> (not <a href=\"#\" data-headword=\"מוּנְיָיק\">מנ׳</a>; ed. Lag. <span dir=\"rtl\">מְגוּסְיָין</span>) plates with morsels from the tables (h. text <span dir=\"rtl\">פתותי</span>).—Lev. R. l. c. <span dir=\"rtl\">למה מגו׳ נפקין וכ׳</span> why are the plates carried out without having been tasted?—2 (= Lat. <i>accubatio</i>) <i>dinner, banquet</i>. <span class=\"citation\">Koh. R. to I, 3</span> <span dir=\"rtl\">דבגין מְגִיסָךְ אתית</span> that I came for the sake of thy dinner. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> [read:] <span dir=\"rtl\">אעליה ועביד ליה מגיסא</span> (or <a href=\"#\" data-headword=\"מְגִיסְתָּא\">מְגִיסְתָּא</a>) he took him into his house and prepared a dinner for him.—[<span class=\"citation\">Targ. Y. Ex. XXVIII, 39</span> <span dir=\"rtl\">מגיסי</span>, v. <a href=\"#\" data-headword=\"גּוּס\">גּוּס</a> I ch.]—[Pesik. Ha‘omer, p. 70ᵃ <span dir=\"rtl\">מגיסך</span>, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגִירוֹס</a>.]</div>","alt":["מְגוּסָא"]},"17140":{"h":"מגיסטאר","r":"M00164","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגִיסְטֵיר\">next w.</a></div>","alt":["מגיסטי"]},"17141":{"h":"מָגִיסְטֵיר","r":"M00165","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (magister) <i>a high imperial officer</i> (v. Sm. Ant. s. v.). <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">קרב קיסין למ׳</span> put the Magister in stocks. <span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">מאן דעביד מ׳ פלטון וכ׳</span> he who used to appoint the Magister Palatii is now to be made a bather &amp;c.—Pl. <span dir=\"rtl\">מָגִיסְטְרֵי</span> (magistri). <span class=\"citation\">Gen. R. s. 26</span> (expl. <span dir=\"rtl\">זמזמים</span>, <span class=\"citation\">Deut. II, 20</span>, v. <a href=\"#\" data-headword=\"זָמַם I\"><span dir=\"rtl\">זָמַם</span> I</a>) <span dir=\"rtl\">מנטרומין מגיסטי מלחמה</span> (some ed. <span dir=\"rtl\">מנטרמוי בג׳</span>; Yalk. ib. 47 <span dir=\"rtl\">מנדמטין מגוסטי</span>) read: <span dir=\"rtl\">מִנְסוֹרִין ומגיסטרי וכ׳</span> mensores (camp-surveyors) and magistri militum (chief commanders).</div>","alt":["מָגִסְ׳"]},"17142":{"h":"מגיסטריני","r":"M00166","html":"<div class=\"sense\">, Targ. II Esth. IX, 3 (Var. <span dir=\"rtl\">מגיסטרני</span>, <a href=\"#\" data-headword=\"מָגִיסְטֵיר\">מגס׳</a>, <a href=\"#\" data-headword=\"מסטרני\">מסטרני</a>, <a href=\"#\" data-headword=\"מכיצטרכי\">מכיצטרכי</a>) read: <span dir=\"rtl\">מָגִיסְטְרָטֵי</span> m. pl. (magistratus) <i>officials</i> (h. text <span dir=\"rtl\">אחשדרפנים</span>).</div>","alt":[]},"17143":{"h":"מְגִיסְתָּא","r":"M00167","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְגִיסָא\">מְגִיסָא</a>) <i>tray, plate</i>. <span class=\"citation\">Targ. O. Num. VII, 13</span> (ed. Amst. <a href=\"#\" data-headword=\"מָגִיסְטֵיר\">מְגִסְ׳</a>; h. text <a href=\"#\" data-headword=\"קְעָרָה\">קערה</a>); a. fr.—Pl. <a href=\"#\" data-headword=\"מְגִיסְתָּא\">מְגִיסָתָא</a>, <a href=\"#\" data-headword=\"מְגִיסְתָּא\">מְגוּ׳</a>. <span class=\"citation\">Y. Snh. VIII, end, 26ᶜ</span> [read:] <span dir=\"rtl\">מיסב מְגִיסָתַיי מיני</span> to steal my (silver) plate.</div>","alt":["מְגוּ׳ I"]},"17144":{"h":"מְגִיסְתָּא ²","r":"M00168","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (גּוּס I) <i>haughtiness, violence</i>. <span class=\"citation\">B. Kam. 114ᵃ</span> <span dir=\"rtl\">בדינא דמ׳</span> (Ms. M. <span dir=\"rtl\">דמגו׳</span>; Rashi in early prints <span dir=\"rtl\">מגוש׳</span>; oth. vers. <span dir=\"rtl\">מגוז׳</span>; Ms. F. <a href=\"#\" data-headword=\"מָגוֹר ²\">מגורא</a> read <span dir=\"rtl\">מגוסא</span>, v. Rabb. D. S. a. l. note) in a court of violence, opp. <span dir=\"rtl\">בי דוואר</span> regular Persian courts. V. <a href=\"#\" data-headword=\"מְגִיזְתָּא II\"><span dir=\"rtl\">מְגִיזְתָּא</span> II</a>.</div>","alt":["מְגוּ׳ II"]},"17145":{"h":"מַגֵּיפָה","r":"M00169","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מַגּפ׳</span>.</div>","alt":["מַגֵּיפְתָּא"]},"17146":{"h":"מָגִיר","r":"M00170","html":"<div class=\"sense\"><i>rest</i>, v. <a href=\"#\" data-headword=\"מָגוֹר\">מָגוֹר</a>.</div>","alt":[]},"17147":{"h":"מָגֵיר","r":"M00171","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (גּוּר I; v. <a href=\"#\" data-headword=\"מְגוּרָה II\"><span dir=\"rtl\">מְגוּרָה</span> II</a>) <i>fellow-inhabitant, neighbor</i>. <span class=\"citation\">Koh. R. to II, 20</span>; <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">אנתתיה דמ׳</span> the wife of a neighbor (of the old man). <span class=\"citation\">Y. Yoma VIII, 45ᵇ</span>; <span class=\"citation\">Y. Ned. IV, end, 38ᵈ</span> <span dir=\"rtl\">הוה מָגִירֵיה וכ׳</span> was a neighbor of (living in the same court with) R. J.; <span class=\"citation\">Y. Sabb. XVI, end, 15ᵈ</span> <span dir=\"rtl\">במגורה</span> (corr. acc.). Y. B. Bath. II, end, 13ᶜ <span dir=\"rtl\">הוה מגיריה וכ׳</span> was his neighbor in the field and in the house (living in the same court). <span class=\"citation\">Koh. R. to VII, 26</span> <span dir=\"rtl\">מ׳ ליסטיס</span> (not <a href=\"#\" data-headword=\"מַגִּיד\">מגיד</a>) a neighbor who was a robber. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מְגֵרָן</span> (not <a href=\"#\" data-headword=\"מגדן\">מגדן</a>) our neighbor. <span class=\"citation\">Ib. X, 19</span>; a. fr.—Pl. <span dir=\"rtl\">מָגִירִין</span>, <span dir=\"rtl\">מָגִירַיָּא</span>, <a href=\"#\" data-headword=\"מָגֵיר\">מָגוֹ׳</a>. Y. Peah III, 17ᵈ top <span dir=\"rtl\">מגו׳ נוכראין</span> gentile neighbors. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">כל מ׳ … למְגִירֵיהוֹן עבדין</span> do all neighbors, bent on doing evil, do it to their neighbors?—<span class=\"citation\">Midr. Till. to Ps. XLVIII</span> (prov.) <span dir=\"rtl\">לא כמה דאמרת … דאמרין מָגוֹרַיָּה</span> (ed. Bub.) go not by what thy mother says (of thee), but what the neighbors say. <span class=\"citation\">Cant. R. to VII, 2</span>; a. fr.—[<span class=\"citation\">Lam. R. to II, 22</span> <span dir=\"rtl\">מגו ביתאי</span> ed. (Ar. <span dir=\"rtl\">מגרוסי</span>) read: <span dir=\"rtl\">מְגוֹרֵי ביתאי</span> inmates of my house, v. <a href=\"#\" data-headword=\"קוֹסִיטְרַפִּיזִין\">קוסיטרפיזין</a>.]—<i>Fem</i>. <a href=\"#\" data-headword=\"מֵגִירְתָּא\">מְגִירְתָּא</a>, <a href=\"#\" data-headword=\"מְגִיסְתָּא\">מְגוּ׳</a>. <span class=\"citation\">Targ. Y. II, Ex. III, 22</span> <span dir=\"rtl\">ממְגוּרְתָּהּ</span> (not … <a href=\"#\" data-headword=\"רָתָה\">רָתָהּ</a>).—<span class=\"citation\">Lev. R. s. 5</span>, end <span dir=\"rtl\">אתית לגבי מ׳ … שלמא עליך מְגִרְתִּי</span> she comes to a neighbor …, peace with thee, my neighbor! <span class=\"citation\">Lev. R. s. 6</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מֵגִירְתָּא\">מְגִירָתָא</a>. <span class=\"citation\">Ib. s. 9</span> <span dir=\"rtl\">אמרין לה מְגִירָתָהּ</span> (some ed. … <a href=\"#\" data-headword=\"תָּא\">תא</a>) said her neighbors to her. <span class=\"citation\">Ned. 21ᵇ</span> <span dir=\"rtl\">דאמרין מְגִירָתָךְ עלה דברתך וכ׳</span> that thy neighbors will say of thy daughter &amp;c. <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> bot. [read:] <span dir=\"rtl\">ובלחוד דלא ידעין מ׳</span> (not <a href=\"#\" data-headword=\"מגיריית\">מגיריית</a>) provided the neighbors do not know it.</div>","alt":["מָגֵירָא","(מָגֵר","מָגֵרָא","מָגוֹ׳"]},"17148":{"h":"מְגֵירָה","r":"M00172","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>saw.</i> <span class=\"citation\">Kel. XIII, 4</span>. <span class=\"citation\">Bets. IV, 3</span>. <span class=\"citation\">Ḥull. I, 2</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>plane</i>. <span class=\"citation\">Tosef. B. Kam. XI, 15</span>; <span class=\"citation\">B. Kam. 119ᵇ</span>, v. <a href=\"#\" data-headword=\"גָּרַר I\"><span dir=\"rtl\">גָּרַר</span> I</a>.—[<span class=\"citation\">Tosef. Kel. B. Mets. VIII, 1</span> <span dir=\"rtl\">מגירות</span> ed. Zuck., v. <a href=\"#\" data-headword=\"מְגוּרָה I\"><span dir=\"rtl\">מְגוּרָה</span> I</a>].</div>","alt":["מְגֵרָה"]},"17149":{"h":"מגִירוֹס","r":"M00173","html":"<div class=\"sense\">, (<a href=\"#\" data-headword=\"מַגְרוֹס\">מַגְרוֹס</a>) m. (μάγειρος) <i>baker, cook</i>. <span class=\"citation\">Lam. R. to III, 16</span> אצל המגרוס Ar., v. <a href=\"#\" data-headword=\"פָּרָכוּטֵס\">פָּרָכוּטֵס</a>. <span class=\"citation\">Lev. R. s. 28</span>; <span class=\"citation\">Pesik. R. s. 18</span>; <span class=\"citation\">Yalk. Lev. 643</span>, a. e. (<span dir=\"rtl\">מְגִרְסָךְ</span>) <span dir=\"rtl\">מְגִירְסָךְ אנא</span> I (the Lord) am thy cook (ripening thy fruits); Pesik. Haʿomer, p. 70ᵃ <span dir=\"rtl\">מגיסך</span> (corr. acc.). Ib. <span dir=\"rtl\">כמו גרייס</span> read: <span dir=\"rtl\">כמגירוס</span>. <span class=\"citation\">Num. R. s. 4</span>, end <span dir=\"rtl\">מ׳ של בו&quot;ד</span> (not <a href=\"#\" data-headword=\"מגירם\">מגירם</a>, <a href=\"#\" data-headword=\"מגידם\">מגידם</a>) the cook of a human master. <span class=\"citation\">Y. Keth. I, 25ᶜ</span> <span dir=\"rtl\">קול מגרוס בעיר</span> when it was announced that a cook (or baker) was in town (<span class=\"citation\">Snh. 32ᵇ</span> <span dir=\"rtl\">קול רחים</span>).—Pl. <span dir=\"rtl\">מְגִירוֹסִין</span>, <span dir=\"rtl\">מְגִירְסִין</span>. <span class=\"citation\">Lev. R. s. 7</span>; Yalk. Num. 777 <span dir=\"rtl\">מגרסין</span>; <span class=\"citation\">Pesik. R. s. 16</span> <a href=\"#\" data-headword=\"מגריפים\">מגריפים</a> (corr. acc.); Pesik. Eth Korb., p. 61ᵃ.—[<span class=\"citation\">Lam. R. to II, 22</span> מגרוסי Ar., v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a>.]</div>","alt":[]},"17150":{"h":"מְגִירוּתָא","r":"M00174","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגוּרְתָּא\">מְגוּרְתָּא</a></div>","alt":[]},"17151":{"h":"מָגִירְיוֹן","r":"M00175","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μαγειρεῖον) <i>cook-shop, kitchen</i>. <span class=\"citation\">Y. Bets. V, end, 63ᵇ</span></div>","alt":[]},"17152":{"h":"מגיריית","r":"M00176","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. III, 5ᵈ</span> bot., v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a> end.</div>","alt":[]},"17153":{"h":"מגירם","r":"M00177","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגֵירוֹס</a></div>","alt":["מָגִירָס","מָגִירְסָא"]},"17154":{"h":"מֵגִירְתָּא","r":"M00178","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a></div>","alt":[]},"17155":{"h":"מַגָּל","r":"M00179","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"עָגַל\">עָגַל</a>) </div><div class=\"sense\"><b>1)</b>  <span dir=\"rtl\">מַגַּל קציר</span> or <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>sickle, scythe</i>, an implement with indentations. <span class=\"citation\">Succ. 32ᵃ</span> <span dir=\"rtl\">עקום דומה למ׳</span> a Lulab curved like a sickle. Y. ib. III, 53ᶜ bot. <span dir=\"rtl\">עשוייה כמין מ׳</span> leaves shaped (and serried) like a sickle; Bab. <span class=\"citation\">ib. 34ᵃ</span> <span dir=\"rtl\">עלה שלה עגול ופיה דומה למ׳</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">מַגַּל יד</span> or <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>an implement combining knife and saw.</i> <span class=\"citation\">Kel. XIII, 1</span>. <span class=\"citation\">Ḥull. I, 2</span>. <span class=\"citation\">Bets. IV, 3</span> (used for splitting wood); a. fr.—<span class=\"citation\">Snh. 95ᵇ</span> <span dir=\"rtl\">מֵגָּלְךָ נטושה</span> (<i>fem</i>.), v. <a href=\"#\" data-headword=\"נָטַשׁ I\"><span dir=\"rtl\">נָטַשׁ</span> I</a>.</div>","alt":[]},"17156":{"h":"מַגַּל","r":"M00180","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Deut. XVI, 9</span>; <span class=\"citation\">XXIII, 26</span> (h. text <span dir=\"rtl\">חרמש</span>).—<span class=\"citation\">Taan. 31ᵃ</span> <span dir=\"rtl\">יום תבר מגל</span> the day of breaking the <i>maggal</i> (suspending the chopping of wood for the Temple).—Pl. <span dir=\"rtl\">מַגָּלִין</span>, <span dir=\"rtl\">מַגָּלֵי</span>. <span class=\"citation\">Targ. Is. II, 4</span>; <span class=\"citation\">Mic. IV, 3</span>; <span class=\"citation\">Joel IV, 10</span> (h. text <span dir=\"rtl\">מזמרות</span>).</div>","alt":["מַגְּלָא","מַגָּ׳"]},"17157":{"h":"מַגְלָב","r":"M00181","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">גלב</span>, v. Fl. to Levy Targ. Dict. II, p. 567ᵃ) [<i>scraper</i>,] an instrument of torture, <i>goad</i> or <i>whip</i>. <span class=\"citation\">Gen. R. s. 41</span>, beg.; s. 52; <span class=\"citation\">Yalk. Gen. 69</span> <a href=\"#\" data-headword=\"מַגְלָבָה\">מגלבה</a>; (Tanḥ. Lekh. 5 <a href=\"#\" data-headword=\"שַׁרְבִיט\">שרביט</a>).—Pl. <span dir=\"rtl\">מַגְלָבִים</span>, <span dir=\"rtl\">מַגְלָבִין</span>. <span class=\"citation\">Ex. R. s. 14</span>, beg. <span dir=\"rtl\">לך והכהו המשים מ׳</span> go and give him fifty lashes. Tanḥ. M’tsora 4 <span dir=\"rtl\">כבלים ומ׳</span> chains and straps; <span class=\"citation\">Num. R. s. 13</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חמשה מ׳</span> five <i>afflictions</i>. <span class=\"citation\">Num. R. s. 10</span>, beg.; <span class=\"citation\">Lev. R. s. 27</span>; <span class=\"citation\">Cant. R. to V, 16</span>, v. <a href=\"#\" data-headword=\"מַרְזוֹבוֹת\">מַרְזוֹבוֹת</a>.</div>","alt":[]},"17158":{"h":"מַגְלָבָא","r":"M00182","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. XXVI, 3</span> (Var. <span dir=\"rtl\">ומגלכא</span>, Ms. <span dir=\"rtl\">נמגלבא</span>, corr. acc.; h. text <span dir=\"rtl\">מתג</span>).—Pl. <span dir=\"rtl\">מַגְלְבַיָּא</span>, <span dir=\"rtl\">מַגְלְבִין</span>. <span class=\"citation\">Lev. R. s. 15</span> <span dir=\"rtl\">חמת מ׳ תלן</span> she saw the straps hanging. <span class=\"citation\">Gen. R. s. 84</span>, beg.; <span class=\"citation\">Yalk. ib. 140</span>; <span class=\"citation\">Yalk. Job 904</span> <span dir=\"rtl\">מאה מ׳</span> one hundred lashes.</div>","alt":["מַגְלְבָא"]},"17159":{"h":"מַגְלָבָה","r":"M00183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַגְלָב\">מַגְלָב</a></div>","alt":[]},"17160":{"h":"מְגִלָּה","r":"M00184","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>roll, scroll, volume, part of a</i> <a href=\"#\" data-headword=\"סֵפֶר\">סֵפֶר</a>. <span class=\"citation\">Treat. Sof’rim V, 9</span> <span dir=\"rtl\">אין עושין שמע</span> (<a href=\"#\" data-headword=\"אוֹ I\">או</a>)<span dir=\"rtl\">הלל מ׳ וכ׳</span> you must not prepare the section of <i>Sh’ma</i> or of <i>Hallel</i> as a special volume for children; <span class=\"citation\">Gitt. 60ᵃ</span> <span dir=\"rtl\">מהו לכתוב מ׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"לָמֵד I\">לָמַד</a>; <span class=\"citation\">Yoma 37ᵇ</span>. Gitt. l. c. <span dir=\"rtl\">תורה מ׳ מ׳ ניתנה</span> the Pentateuch was published in sections, opp. <span dir=\"rtl\">חתומה</span>. <span class=\"citation\">Deut. R. s. 8</span> <span dir=\"rtl\">תחלה קורא במ׳</span> when beginning, the student reads (the Pentateuch) in a detached scroll, opp. <span dir=\"rtl\">בספר</span>.—<span class=\"citation\">Y. Shek. V, 49ᵃ</span>; <span class=\"citation\">Yoma 38ᵃ</span>; <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">מְגִלַּת ס</span>(<a href=\"#\" data-headword=\"מ\">מ</a>)<span dir=\"rtl\">מנין</span> a volume containing prescriptions for frankincense; a. fr.—<span dir=\"rtl\">מ׳ יוחסין</span>, <span dir=\"rtl\">מ׳ סתרים מגלת אסתר</span>, &amp;c., v. respect. determinants.—Pl. <span dir=\"rtl\">מְגִלּוֹת</span>, <a href=\"#\" data-headword=\"מְצִילָּה\">מְגִילּוֹת</a>. Cant. R. l. c. <span dir=\"rtl\">היו מוסרין מְגִילּוֹתָם וכ׳</span> they handed over their rolls (containing the prescriptions) one to the other; (Y. Shek. l. c. <span dir=\"rtl\">את המגלה הזאת</span>).—Esp. (<a href=\"#\" data-headword=\"שַׁרְיֵי\">הַ</a>)<a href=\"#\" data-headword=\"מְגִלָּה\">מְּגִלָּה</a> = <span dir=\"rtl\">מגלת אסתר</span>, a. <a href=\"#\" data-headword=\"אֶסְתֵּר\">אֶסְתֵּר</a>. <span class=\"citation\">Meg. I, 1</span>. <span class=\"citation\">Ib. 19ᵃ</span> <span dir=\"rtl\">מ׳ נקראת ספר</span> the book of Esther is called a book and also a letter. Ib., sq. <span dir=\"rtl\">הקורא במ׳ הכתובה בין וכ׳</span> he who recites from a Book of Esther as written among the Hagiographa (instead of using a special scroll); a. v. fr.—<i>M’gillah</i>, name of a treatise of the Mishnah, Tosefta, Talmud Babli a. Y’rushalmi, treating chiefly of the Festival of Purim.—<i>M’gilloth</i>, the five books: Esther, Ruth, Canticum, Lamentations and Koheleth.</div>","alt":["מְגִילָּה"]},"17161":{"h":"מַגְלוֹנָאָה","r":"M00185","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלוֹגְנָאָה\">מְלוֹגְנָאָה</a></div>","alt":[]},"17162":{"h":"מַגְלְיינָא","r":"M00186","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּלֵי\">גְּלֵי</a>) <i>decreer of exile</i>. <span class=\"citation\">Y. Yoma III, 40ᶜ</span> top <span dir=\"rtl\">נסוחה מ׳</span> <i>kerets</i> (<span class=\"citation\">Jer. XLVI, 20</span>) means <i>sweeper</i>, that is, he who will banish (v. <span class=\"citation\">Deut. XXVIII, 63</span>).</div>","alt":[]},"17163":{"h":"מְגִלְתָּא","r":"M00187","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"מְגִלָּה\">מְגִלַּת</a>, <a href=\"#\" data-headword=\"מְגִילָּה\">מְגִילַּת</a> ch. = h. <a href=\"#\" data-headword=\"מְגִלָּה\">מְגִלָּה</a>. <span class=\"citation\">Targ. Jer. XXXVI, 2</span>; a. e.</div>","alt":["מְגִילְ׳"]},"17164":{"h":"מֻגְמָר","r":"M00188","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּגְמָר\">מוּגְמָר</a></div>","alt":[]},"17165":{"h":"מָגֵן","r":"M00189","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>shield, defense</i>. Pesik. Haʿomer, p. 70ᵃ; 70ᵇ (ref. to <span dir=\"rtl\">ואל מצנים</span>, <span class=\"citation\">Job V, 5</span>) <span dir=\"rtl\">לא בזיין ולא במ׳</span> not with weapon or with shield (will he prevail); <span class=\"citation\">Lev. R. s. 28</span>; <span class=\"citation\">Pesik. R. s. 18</span>; <span class=\"citation\">Yalk. Job 898</span>.—<span class=\"citation\">Cant. R. to IV, 4</span> end (ref. to <span dir=\"rtl\">אלף המגן</span>, ib.) <span dir=\"rtl\">אלף דור … אותו המ׳</span> I folded together (skipped over) a thousand generations and brought unto them that shield (the Torah).—<span class=\"citation\">Midr. Till. to Ps. I, 5</span>, v. <a href=\"#\" data-headword=\"גּוּן\">גּוּן</a>; a. fr.—Pl. <span dir=\"rtl\">מָגִנִּים</span>, <span dir=\"rtl\">מָגִינִּים</span>. Lam. R. introd. (R. Joḥ. 1) (ref. to <span class=\"citation\">Is. XXII, 5</span>) <span dir=\"rtl\">שהיו מקרקרים … עושין אותן מ׳</span> they broke down the walls of their houses and made of them defenses. Cant. R. l. c. <span dir=\"rtl\">לבניך אני נעשה מ׳ הרבה</span> unto thy children I shall be many defenses. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">מ׳ של צדיקים</span> shields of the righteous (protectors of their generation by dint of their righteousness); a. e.—Esp. <i>Magen, the first section of the Prayer of Benedictions</i> closing with <span dir=\"rtl\">מָגֵן אַבְרָהָם</span> (usu. called <span dir=\"rtl\">אָבוֹת</span>, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>). <span class=\"citation\">Deut. R. s. 11</span>, beg. <span dir=\"rtl\">חוזר לתחלת מ׳</span> (<span class=\"citation\">Ber. 34ᵃ</span> <span dir=\"rtl\">לראש</span>) he must go back to the beginning of the first section. <span class=\"citation\">Erub. 65ᵃ</span>, v. <a href=\"#\" data-headword=\"פּוּק\">פּוּק</a> h.—<span dir=\"rtl\">בֵּית הַמָּגִינִּין</span>, <span class=\"citation\">Tosef. Kil. IV, 7</span>, v. <a href=\"#\" data-headword=\"מַגִּין\">מְגִינָּא</a>.</div>","alt":[]},"17166":{"h":"מְגָן","r":"M00190","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מַגִּין\">מַגִּין</a></div>","alt":["מָגִנָּא"]},"17167":{"h":"מַגָּן","r":"M00191","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּנַן\">גְּנַן</a>; cmp. <a href=\"#\" data-headword=\"חִנָּם\">חִנָּם</a> fr. <a href=\"#\" data-headword=\"חָנַן\">חָנַן</a>) <i>grace, undeserved gift</i>; (adv. with or without prepos.) <i>for nothing, in vain</i>. <span class=\"citation\">Targ. Prov. XV, 27</span>.—<span class=\"citation\">Targ. Gen. XXIX, 15</span>. <span class=\"citation\">Targ. Ex. XX, 7</span>; <span class=\"citation\">Targ. Deut. V, 11</span>; a. e.—<span class=\"citation\">Y. Bicc. III, 65ᶜ</span> bot. <span dir=\"rtl\">לא מ׳ מאריך ימים</span> it is not for nothing that he has been allowed a long life. <span class=\"citation\">B. Kam. 85ᵃ</span> <span dir=\"rtl\">אסיא דמ׳</span> a physician (that will cure thee) without pay; <span dir=\"rtl\">אסיא דמ׳ כמ׳ שוי</span> Ms. M. a. oth. (ed. incorr., v. Rabb. D. S. a. l. note) a physician without pay is worth as much as unpaid service can be expected to be, i.e. an unpaid physician is likely to be careless. <span class=\"citation\">Y. Snh. X, 29ᵃ</span> bot. <span dir=\"rtl\">אפי׳ על מ׳</span> even if the curse has been pronounced gratuitously (without cause), cmp. <span dir=\"rtl\">קללת חנם</span> s. v. <a href=\"#\" data-headword=\"חִנָּם\">חִנָּם</a>.</div>","alt":["מַגָּנָא"]},"17168":{"h":"מְגָנָא","r":"M00192","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּנֵי\">גְּנֵי</a>) <i>couch</i>, or <i>couch-room</i>.—Pl. <a href=\"#\" data-headword=\"מִגַּנְיָא\">מְגָנַיָּא</a>. Targ. II Esth. I, 9 (ed. Lag. a. oth. <span dir=\"rtl\">מנגניא</span>, corr. acc.).—[<span class=\"citation\">Pes. 107ᵃ</span> <span dir=\"rtl\">מגני</span>, v. <a href=\"#\" data-headword=\"מְגָגָא\">מְגָגָא</a>.]</div>","alt":[]},"17169":{"h":"מַגָּנָה","r":"M00193","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְגָּנָא\">מַנְגָּנָא</a></div>","alt":[]},"17170":{"h":"מַגְּנוֹן","r":"M00194","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְגָּנוֹן\">מַנְגָּנוֹן</a></div>","alt":[]},"17171":{"h":"מִגַּנְיָא","r":"M00195","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (part. Ithpe. of <a href=\"#\" data-headword=\"גְּנֵי\">גְּנֵי</a>) = h. <span dir=\"rtl\">מְגוּנֶּה</span> (v. <a href=\"#\" data-headword=\"גָּנָה\">גָּנָה</a>), <i>blame-worthy</i>; <span dir=\"rtl\">מילתא מ׳</span> <i>blemish, defect</i>. <span class=\"citation\">Gen. R. s. 60</span> (prov.) <span dir=\"rtl\">מילתא דאית בך מ׳ וכ׳</span> what blemish there be in thee, be the first to tell it; <span class=\"citation\">B. Kam. 92ᵇ</span> מילתא דמִיגַּ׳ Ms. M. (ed. <a href=\"#\" data-headword=\"גִּנָּאָה\">גנאה</a>).</div>","alt":[]},"17172":{"h":"מַגָּנִיּוֹת","r":"M00196","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַנְגָּנָא\">מַנְגָּנָא</a>.—[Mekh. B’shall. s. 2 <a href=\"#\" data-headword=\"מַגָּנִיּוֹת\">מגניות</a>, emend. for <span dir=\"rtl\">מגפות</span>, read: <a href=\"#\" data-headword=\"סִגְנִיּוֹת\">סִגְנִיּוֹת</a>, v. <a href=\"#\" data-headword=\"סִגְנוּם\">סִגְנוֹן</a>.]</div>","alt":[]},"17173":{"h":"מנגנימין","r":"M00197","html":"<div class=\"sense\">, v. <span dir=\"rtl\">במנגנימין</span></div>","alt":[]},"17174":{"h":"מָגֶנֶת","r":"M00198","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מָגֵן\">מָגֵן</a>, <i>protection, defense</i>. <span class=\"citation\">Pirké d’R. El. ch. XXVIII</span>; <span class=\"citation\">Yalk. Gen. 76</span> (expl. <span dir=\"rtl\">מגן</span>, <span class=\"citation\">Gen. XV, 1</span>) <span dir=\"rtl\">אני מ׳ לך</span> I am defense to thee.</div>","alt":["מָגֶינֶת"]},"17175":{"h":"מֵגַס","r":"M00199","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵגֵיס\">מֵגֵיס</a></div>","alt":["מַגָּס"]},"17176":{"h":"מָגִסְטָאר","r":"M00200","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מגיס׳</span>.</div>","alt":["מָגִסְטֵיר","מגסטרני","מְגִסְתָּא"]},"17177":{"h":"מַגָּע","r":"M00201","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָגַע\">נָגַע</a>) <i>touch, contact.</i> <span class=\"citation\">Kel. I, 1</span>, a. fr. <span dir=\"rtl\">מטמא במ׳</span>, makes unclean by contact. <span class=\"citation\">Toh. VI, 4</span> <span dir=\"rtl\">ספק מַגַּע טומאה וכ׳</span> a doubt as to having touched an unclean thing is judged in favor of uncleanness; <span class=\"citation\">Ab. Zar. 70ᵃ</span>, a. e.—<span dir=\"rtl\">מַגַּע נכרי</span> wine touched by a gentile suspected of idolatrous manipulations. <span class=\"citation\">Ib. 58ᵇ</span>.—<span class=\"citation\">Ib. 69ᵃ</span> <span dir=\"rtl\">מ׳ חבירו</span> another ignorant man’s touching things kept in levitical cleanness; a. fr.—Pl. <span dir=\"rtl\">מַגָּעוֹת</span>. <span class=\"citation\">Y. Sabb. VII, 9ᵈ</span> bot., v. <a href=\"#\" data-headword=\"מִדָּף\">מִדָּף</a>.—Constr. <span dir=\"rtl\">מַגָּעֵי</span>. <span class=\"citation\">Y. Pes. VII, 34ᵈ</span> bot. <span dir=\"rtl\">מ׳ זבין</span> those unclean through contact with gonorrhoeists.</div>","alt":[]},"17178":{"h":"מַגְעוּרִי","r":"M00202","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גְּעַר\">גְּעַר</a>) <i>threatening, shouting</i>. <span class=\"citation\">Yalk. Ps. 864</span>; <span class=\"citation\">Midr. Till. to Ps. CVI, 9</span> ed. Bub. (missing in eds.) <span dir=\"rtl\">אפי מ׳ לא הוות וכ׳</span> it was not even a shouting (at the sea) but only a blowing. Yalk. l. c. (missing in Midr. Till. l. c.) <span dir=\"rtl\">לא מ׳ אלא מנהומי</span> not only a shouting but even a roaring.</div>","alt":[]},"17179":{"h":"מֵגֵף","r":"M00203","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּפַף\">גָּפַף</a> or <a href=\"#\" data-headword=\"גּוּף\">גּוּף</a>) <i>sealer</i> of wine vessels. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> top <span dir=\"rtl\">שיתומהון דרבנן מעשה מ׳</span> (not <span dir=\"rtl\">מעש</span>) the boring of which the Rabbis speak (Mish. <span class=\"citation\">ib. V, 4</span>) is the work of a professional sealer (requiring care and time).</div>","alt":[]},"17180":{"h":"מַגֵּפָה","r":"M00204","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>striking</i>,] </div><div class=\"sense\"><b>1)</b> <i>wound.</i> <span class=\"citation\">Makhsh. VI, 8</span> <span dir=\"rtl\">דם מַגֵּפָתָהּ</span> the blood flowing from a woman’s wound. <span class=\"citation\">Nidd. 55ᵇ</span>; <span class=\"citation\">Ker. 13ᵃ</span>. <span class=\"citation\">Ḥull. 35ᵇ</span>. <span class=\"citation\">Yalk. Num. 710</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>sudden death, plague</i>. Mekh. B’shall. s. 2 <span dir=\"rtl\">אין הממה אלא מ׳</span> the verb <a href=\"#\" data-headword=\"הָמַם\">המם</a> (<span class=\"citation\">Ex. XIV, 24</span>) means pestilence. <span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">מיתת מ׳</span> a sudden death. <span class=\"citation\">Ber. 4ᵇ</span> <span dir=\"rtl\">בשעת המ׳</span> during an epidemic; a. fr.—[<span dir=\"rtl\">מגפות</span>, Mekh. l. c., v. <a href=\"#\" data-headword=\"מְנָפָה\">מְנָפָה</a> a. <a href=\"#\" data-headword=\"סִגְנוּם\">סִגְנוֹן</a>.]</div>","alt":["מַגֵּי׳"]},"17181":{"h":"מְגָפַיִּים","r":"M00205","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (גּוּף I) <i>greaves, metal leggins</i>. <span class=\"citation\">Sabb. VI, 2</span> (expl. <span class=\"citation\">ib. 62ᵃ</span> <a href=\"#\" data-headword=\"פַּזְמְקֵי\">פזמקי</a>). <span class=\"citation\">Kel. XI, 8</span>; <span class=\"citation\">Tosef. Kel. B. Mets. III, 1</span> <a href=\"#\" data-headword=\"מנפש\">מנפש</a> ed. Zuck. (corr. acc.; Var. <a href=\"#\" data-headword=\"מְגָפַיִּים\">מְגָפַיִּם</a>).</div>","alt":["מְגָפַיִּין"]},"17182":{"h":"מַגֵּפְתָּא","r":"M00206","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"מַגֵּפָה\">מַגֵּפָה</a>. <span class=\"citation\">Targ. Y. II, Num. XXV, 8</span> <span dir=\"rtl\">פָתָא …</span> (corr. acc.).</div>","alt":["מַגֵּיפְ׳"]},"17183":{"h":"מְגַר","r":"M00207","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"מָגֵר\">מַגֵּר</a>, <a href=\"#\" data-headword=\"מָגֵיר\">מַגֵּיר</a> (b. h. <span dir=\"rtl\">מִגֵּר</span>; cmp. <a href=\"#\" data-headword=\"גְּרַר\">גְּרַר</a>) </div><div class=\"sense\"><b>1)</b> <i>to drag down; to throw over</i>. <span class=\"citation\">Targ. Gen. XLIX, 17</span> (h. text <span dir=\"rtl\">ויפל</span>). <span class=\"citation\">Targ. Ps. LXXXIX, 45</span>. <span class=\"citation\">Targ. Ez. XXXIX, 3</span>. <span class=\"citation\">Targ. II Kings IX, 33</span> (h. text <span dir=\"rtl\">שמט</span>). <span class=\"citation\">Targ. Is. XXII, 19</span> (h. text <span dir=\"rtl\">הרס</span>); a. e.</div><div class=\"sense\"><b>—2)</b>  [<i>to scrape off</i>,] <i>to diminish, destroy</i> (corresp. to b. h. <a href=\"#\" data-headword=\"צָמַת\">צָמַת</a> a. <a href=\"#\" data-headword=\"גָּוַע\">גָּוַע</a>). <span class=\"citation\">Targ. Ps. CXIX, 139</span>. <span class=\"citation\">Ib. CI, 5</span>; <span class=\"citation\">8</span>. <span class=\"citation\">Ib. CXLIII, 12</span>; a. e.</div><div class=\"sense\"><b>Ithpa. אִתְמַגַּר</b> <div class=\"sense\"><i>to be diminished</i>. <span class=\"citation\">Targ. Job VI, 17</span>. <span class=\"citation\">Ib. XXIII, 17</span> Ms. (ed. <span dir=\"rtl\">אתגמר׳</span>, h. text <span dir=\"rtl\">נצמתי</span>).</div></div>","alt":[]},"17184":{"h":"מָגֵר","r":"M00208","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָגֵיר\">מָגֵיר</a>, a. <a href=\"#\" data-headword=\"סִבְבָא\">סִבְבָא</a>.</div>","alt":["מָגֵרָא"]},"17185":{"h":"מַגְרְדָא","r":"M00209","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מַגְרר׳</span>.</div>","alt":["מַגְרֶדֶת","מַגְרַדְתָּא"]},"17186":{"h":"מְגֵרָה","r":"M00210","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְגֵירָה\">מְגֵירָה</a></div>","alt":[]},"17187":{"h":"מַגְרוּמְתָּא","r":"M00211","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Hif.</i> <span class=\"citation\">B. Kam. 99ᵇ</span> <span dir=\"rtl\">ההיא מ׳</span> (Ms. R. <a href=\"#\" data-headword=\"מַגְרַמְתָּא\">מַגְרַמְתָּא</a>) a case of a <i>mugremeth</i>.</div>","alt":[]},"17188":{"h":"מַגְרוֹס","r":"M00212","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגִירוֹס</a></div>","alt":["מגריס"]},"17189":{"h":"מגרופות","r":"M00213","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 6</span>, read <a href=\"#\" data-headword=\"מַגְרוֹפִית\">מַגְרוֹפִית</a>.</div>","alt":[]},"17190":{"h":"מַגְרוֹפִי","r":"M00214","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַגְרוֹפִיתָא\">מַגְרוֹפִיתָא</a></div>","alt":[]},"17191":{"h":"מַגְרוֹפִית","r":"M00215","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּרַף\">גָּרַף</a>; v. <a href=\"#\" data-headword=\"מַגְרֵפָה\">מַגְרֵפָה</a>) </div><div class=\"sense\"><b>1)</b> <i>spade, shovel</i>. <span class=\"citation\">Gen. R. s. 16</span>, beg. <span dir=\"rtl\">ארבעה … פותק במ׳ אחת</span> he divided off the course of four river-heads with one (cut of the) spade.</div><div class=\"sense\"><b>—2)</b> <i>trowel</i>. <span class=\"citation\">Pesik. R. s. 6</span> [read:] <span dir=\"rtl\">לא נשבר לא מ׳ וכ׳</span> no trowel nor axe was broken; <span class=\"citation\">Yalk. Kings 186</span> <a href=\"#\" data-headword=\"מגרופת\">מגרופת</a> (corr. acc.).</div>","alt":[]},"17192":{"h":"מַגְרוֹפִיתָא","r":"M00216","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 38</span>. <span class=\"citation\">Lev. R. s. 24</span>.—Pl. <a href=\"#\" data-headword=\"מַגְרוֹפִיתָא\">מַגְרוֹפְיָתָא</a>. <span class=\"citation\">Targ. Num. IV, 14</span>; <span class=\"citation\">Targ. O. Ex. XXVII, 3</span> (Y. <a href=\"#\" data-headword=\"מגרפתיה\">מִגְרְפַתֵּיה</a>, corr. acc.); a. fr. (h. text <span dir=\"rtl\">יָעִים</span>).</div>","alt":["מַגְרוֹפִי"]},"17193":{"h":"מגרופת","r":"M00217","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַגְרוֹפִית\">מַגְרוֹפִית</a></div>","alt":[]},"17194":{"h":"מַגְרֵיף","r":"M00218","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַגְרֵף\">מַגְרֵף</a>, <a href=\"#\" data-headword=\"מַגְרֵפָה\"><a href=\"#\" data-headword=\"מַגְרֵפָה\">מַגְרֵפָה</a>.</a></div>","alt":["מַגְרֵיפָה"]},"17195":{"h":"מגריפים","r":"M00219","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 16</span>, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגִירוֹס</a></div>","alt":[]},"17196":{"h":"מַגְרַמְתָּא","r":"M00220","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מַגְרוּמְתָּא\">מַגְרוּמְתָּא</a></div>","alt":[]},"17197":{"h":"מְגִירְסָא","r":"M00221","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מגִירוֹס\">מָגִירוֹס</a></div>","alt":[]},"17198":{"h":"מַגְרֵף","r":"M00222","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"גָּרַף\">גְָּרַף</a>) </div><div class=\"sense\"><b>1)</b> <i>trowel</i>. Y’lamd. to Gen. XI, 1, quot. in Ar. s. v. <span dir=\"rtl\">גרף</span>.</div><div class=\"sense\"><b>—2)</b> <i>shovel</i>. <span class=\"citation\">Y. Shebi. III, 34ᶜ</span>; <span class=\"citation\">Y. M. Kat. I, 80ᵇ</span> <span dir=\"rtl\">סלו ומַגְרֵיפוֹ וכ׳</span> his basket and shovel show that he is preparing dung.</div>","alt":[]},"17199":{"h":"מַגְרֵפָה","r":"M00223","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַגְרֵף\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>spoon, ladle; trowel.</i> <span class=\"citation\">Kel. XXIX, 8</span> <span dir=\"rtl\">מ׳ של ב&quot;ב</span> the ladle of the household (v. Maim. a. l.); <span dir=\"rtl\">מ׳ של סיידים</span> the plasterers’ trowel. Tanḥ. Sh’moth 9 <span dir=\"rtl\">של טיט</span> the trowel for clay; <span class=\"citation\">Ex. R. s. 1</span> (some ed. <span dir=\"rtl\">מַגְרֵיפוֹ של טיט</span>, v. <a href=\"#\" data-headword=\"מַגְרֵף\">preced.</a>). <span class=\"citation\">Kel. XIII, 4</span> <a href=\"#\" data-headword=\"מ׳\">מ׳</a> ladle (v. Maim. a. l.).</div><div class=\"sense\"><b>—2)</b>  (usu. in connection with <span dir=\"rtl\">סל</span>) <i>spade</i> used for digging and shovelling; <i>shovel</i>. <span class=\"citation\">Gen. R. s. 16</span>; <span class=\"citation\">Sifré Deut. 6</span>, a. e., v. <a href=\"#\" data-headword=\"פְּרָת\">פְּרָת</a>.—<span class=\"citation\">Tosef. Toh. VIII, 13</span>; <span class=\"citation\">Zeb. 99ᵇ</span>. <span class=\"citation\">Sabb. XVII, 2</span> <span dir=\"rtl\">מ׳ לגרוף וכ׳</span> one may handle a spade (on the Sabbath) for grabbing &amp;c., v. <a href=\"#\" data-headword=\"גָּרַף\">גָּרַף</a>. <span class=\"citation\">Num. R. s. 15</span>; <span class=\"citation\">Yalk. Ex. 163</span>. <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Cant. R. to IV, 8</span> <span dir=\"rtl\">היא והסל והמ׳ וכ׳</span> it (the Torah) and all its implements, v. <a href=\"#\" data-headword=\"אֶרְגַּלְיָא\">אֶרְגַּלְיָא</a>.—<span class=\"citation\">Y. Ḥag. II, 78ᵇ</span> bot. <span dir=\"rtl\">מ׳ של מתכת</span> an iron spade (flat); <span dir=\"rtl\">מ׳ של עץ</span> a wooden shovel; a. e.—Pl. <span dir=\"rtl\">מַגְרֵפוֹת</span>, <a href=\"#\" data-headword=\"מַגְרֵפָה\">מַגְרֵי׳</a>. <span class=\"citation\">B. Mets. 30ᵃ</span>. <span class=\"citation\">Tam. II, 1</span>. <span class=\"citation\">Gen. R. s. 46</span>, beg.; a. e.</div><div class=\"sense\"><b>—3)</b> <i>magrefah</i>, a) name of <i>a musical instrument in the Temple</i>. <span class=\"citation\">Arakh. 10ᵇ</span>; <span class=\"citation\">Y. Succ. V, 55ᵈ</span> top.—b) name of a sort of <i>tympanum</i>. <span class=\"citation\">Tam. V, 6</span>, <span class=\"citation\">Ib. III, 8</span>; Y. l. c. 55ᵇ bot.</div>","alt":["מַגְרֵי׳"]}};
